    #[test]
    fn standardize_targets_yields_zero_mean_unit_variance_and_preserves_order() {
        let mk = |t: f64| SoccerNeuralTrainingSample {
            input: [0.0; SOCCER_NEURAL_FEATURE_DIM],
            target: t,
            priority: 1.0,
        };
        // Targets clustered near a small constant — the collapse regime the fix targets.
        let raw = [
            0.041, 0.043, 0.038, 0.050, 0.045, 0.039, 0.047, 0.042, 0.044, 0.040,
        ];
        let mut samples: Vec<SoccerNeuralTrainingSample> = raw.iter().map(|&t| mk(t)).collect();
        soccer_standardize_sample_targets(&mut samples, 13.0);
        let n = samples.len() as f64;
        let mean = samples.iter().map(|s| s.target).sum::<f64>() / n;
        let var = samples
            .iter()
            .map(|s| (s.target - mean).powi(2))
            .sum::<f64>()
            / n;
        assert!(mean.abs() < 1e-9, "standardized mean ≈ 0, got {mean}");
        assert!(
            (var - 1.0).abs() < 1e-6,
            "standardized variance ≈ 1, got {var}"
        );
        // Ranking invariance: the largest raw target (idx 3 = 0.050) stays largest.
        assert!(
            samples[3].target > samples[2].target && samples[3].target > samples[0].target,
            "affine rescale preserves relative order"
        );
    }

    #[test]
    fn standardize_targets_noop_for_small_or_degenerate_batches() {
        let mk = |t: f64| SoccerNeuralTrainingSample {
            input: [0.0; SOCCER_NEURAL_FEATURE_DIM],
            target: t,
            priority: 1.0,
        };
        // Small batch (<8): untouched (per-batch stats too noisy to trust).
        let mut small: Vec<SoccerNeuralTrainingSample> = (0..5).map(|i| mk(i as f64)).collect();
        soccer_standardize_sample_targets(&mut small, 13.0);
        assert_eq!(small[4].target, 4.0, "small batch left unchanged");
        // Degenerate (all equal ⇒ std 0): untouched, no divide-by-zero blowup.
        let mut flat: Vec<SoccerNeuralTrainingSample> = (0..10).map(|_| mk(0.044)).collect();
        soccer_standardize_sample_targets(&mut flat, 13.0);
        assert!(
            flat.iter().all(|s| (s.target - 0.044).abs() < 1e-12),
            "zero-variance batch left unchanged"
        );
    }

    #[test]
    fn full_game_actor_cap_preserves_priority_and_spreads_ordinary_samples() {
        let samples: Vec<SoccerPolicySample> = (0..10)
            .map(|index| {
                let mut state_features = [0.0; SOCCER_POLICY_FEATURE_DIM];
                state_features[0] = index as f64;
                SoccerPolicySample {
                    state_features,
                    action_index: 0,
                    advantage: 1.0,
                    old_action_probability: None,
                    legal_action_mask: Vec::new(),
                    sample_weight: if index >= 8 { 2.0 } else { 1.0 },
                    mcts_distillation: false,
                    forward_select_eligible: false,
                }
            })
            .collect();

        let capped = SoccerMatch::capped_full_game_policy_samples_for_training(samples, 4);
        let retained: Vec<usize> = capped
            .iter()
            .map(|sample| sample.state_features[0] as usize)
            .collect();

        assert_eq!(retained, vec![2, 6, 8, 9]);
    }

    #[test]
    fn away_learning_actor_training_uses_dedicated_away_sidecars() {
        let mut config = MatchConfig::default();
        config.learning_enabled = true;
        config.neural_learning.enabled = true;
        config.neural_learning.backend = SoccerNeuralLearningBackend::Inline;
        config.neural_blend.actor_critic = true;
        let mut sim = SoccerMatch::default_11v11(config);

        sim.set_team_neural_brain(Team::Home, None, true)
            .expect("install frozen home brain");
        sim.set_team_neural_brain(Team::Away, None, false)
            .expect("install learning away brain");

        assert_eq!(sim.skill_policy_training_team(), Team::Away);
        sim.ensure_policy_head_for_training(sim.skill_policy_training_team());
        sim.ensure_skill_policy_heads_for_training(sim.skill_policy_training_team());
        assert!(
            sim.policy_head.is_none(),
            "away-learning matches must not allocate or train the home/shared joint actor"
        );
        assert!(
            sim.away_policy_head.is_some(),
            "away-learning matches need a dedicated joint actor to serve and export"
        );
        assert!(sim.policy_head_for(Team::Home).is_none());
        assert!(sim.policy_head_for(Team::Away).is_some());
        assert!(sim
            .neural_network_snapshot_for(Team::Away)
            .expect("away learner snapshot")
            .policy_head
            .is_some());
        assert!(
            sim.skill_policy_heads.is_none(),
            "away-learning matches must not train the home/shared skill sidecar"
        );
        assert!(
            sim.away_skill_policy_heads.is_some(),
            "away-learning matches need a dedicated skill sidecar to export"
        );
    }

