    fn world_test_transition(
        sim: &SoccerMatch,
        player_id: usize,
        action: &str,
        tick: u64,
    ) -> SoccerLearningTransition {
        let snapshot = WorldSnapshot::from_match(sim);
        let player = sim.players.get(player_id).expect("test player exists");
        let mdp_state = snapshot.mdp_state_for_player(player_id);
        let observation = snapshot.observation_for(player_id);
        let mut transition = sim.neural_decision_transition(
            &snapshot,
            player_id,
            player.team,
            player.role,
            &mdp_state,
            &observation,
        );
        transition.tick = tick;
        transition.action = action.to_string();
        transition
    }

    fn first_home_field_pair(sim: &SoccerMatch) -> (usize, usize) {
        let mut ids = sim
            .players
            .iter()
            .filter(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .map(|player| player.id);
        let first = ids.next().expect("home field player");
        let second = ids.next().expect("second home field player");
        (first, second)
    }

    struct TestEnvVarGuard {
        key: &'static str,
        previous: Option<std::ffi::OsString>,
    }

    impl Drop for TestEnvVarGuard {
        fn drop(&mut self) {
            if let Some(previous) = self.previous.take() {
                std::env::set_var(self.key, previous);
            } else {
                std::env::remove_var(self.key);
            }
        }
    }

    fn set_test_env_var(key: &'static str, value: &str) -> TestEnvVarGuard {
        let previous = std::env::var_os(key);
        std::env::set_var(key, value);
        TestEnvVarGuard { key, previous }
    }

    fn soccer_world_env_lock() -> std::sync::MutexGuard<'static, ()> {
        static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
        LOCK.lock().expect("test poison soccer world env lock")
    }

    #[test]
    fn pass_role_risk_composite_orders_safe_and_risky() {
        let safe = pass_role_risk_test_quality(0.94, 0.03, 0.92, 0.0, 0.0);
        let risky = pass_role_risk_test_quality(0.35, 0.70, 0.35, 0.55, 0.40);

        let safe_risk = pass_target_risk_from_quality(&safe);
        let risky_risk = pass_target_risk_from_quality(&risky);
        let safe_safety = pass_target_safety_from_quality(&safe);
        let risky_safety = pass_target_safety_from_quality(&risky);

        assert!(safe_risk < 0.10, "safe pass risk was {safe_risk}");
        assert!(
            risky_risk > safe_risk + 0.35,
            "risky pass risk {risky_risk} should clear safe {safe_risk}"
        );
        assert!(
            safe_safety > risky_safety,
            "safe pass safety {safe_safety} should clear risky {risky_safety}"
        );
    }

    #[test]
    fn learned_receiver_net_forward_quality_rejects_receipt_only_turnover_trap() {
        let _env_lock = soccer_world_env_lock();
        let _quality_floor = set_test_env_var(
            "SOCCER_LEARNED_PASS_RECEIVER_MIN_NET_FORWARD_QUALITY",
            "0.26",
        );
        let passer = Vec2::new(40.0, 52.0);
        let floor = learned_pass_receiver_min_net_forward_quality();
        let receipt_only_trap = PassTargetQuality {
            expected_completion: 0.22,
            lane_interception_risk: 0.88,
            mpc_receipt_probability: 0.86,
            mpc_receipt_race_advantage_seconds: -0.45,
            mpc_receipt_qp_accel_fit: 0.35,
            ..PassTargetQuality::default()
        };
        let clean_forward = PassTargetQuality {
            expected_completion: 0.72,
            lane_interception_risk: 0.08,
            mpc_receipt_probability: 0.72,
            mpc_receipt_race_advantage_seconds: 0.22,
            mpc_receipt_qp_accel_fit: 0.68,
            ..PassTargetQuality::default()
        };
        let safe_recycle = PassTargetQuality {
            expected_completion: 0.92,
            lane_interception_risk: 0.04,
            mpc_receipt_probability: 0.90,
            mpc_receipt_race_advantage_seconds: 0.0,
            mpc_receipt_qp_accel_fit: 0.80,
            ..PassTargetQuality::default()
        };

        let trap_score = SoccerMatch::learned_pass_receiver_net_forward_quality_from_quality(
            Team::Home,
            passer,
            Vec2::new(42.0, 64.0),
            &receipt_only_trap,
            PassFlight::Floor,
        );
        let clean_score = SoccerMatch::learned_pass_receiver_net_forward_quality_from_quality(
            Team::Home,
            passer,
            Vec2::new(42.0, 62.0),
            &clean_forward,
            PassFlight::Floor,
        );
        let recycle_score = SoccerMatch::learned_pass_receiver_net_forward_quality_from_quality(
            Team::Home,
            passer,
            Vec2::new(39.0, 50.0),
            &safe_recycle,
            PassFlight::Floor,
        );

        assert!(
            trap_score < floor,
            "high receipt alone must not pass the learned receiver gate: {trap_score}"
        );
        assert!(
            clean_score >= floor,
            "clean progressive receiver should clear net-forward quality floor: {clean_score}"
        );
        assert!(
            recycle_score >= floor,
            "safe recycle should survive the quality gate when it is genuinely clean: {recycle_score}"
        );
        assert!(
            clean_score > trap_score + 0.25,
            "composite should separate clean forward target from turnover trap: clean={clean_score}, trap={trap_score}"
        );
    }

