    #[test]
    fn runaround_success_counts_as_dribble_beat_and_replays_launch_decision() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            learning_enabled: true,
            full_game_learning_enabled: true,
            ..MatchConfig::default()
        });
        let attacker = 9;
        let defender = 13;
        sim.tick = 160;
        sim.clock_seconds = 12.0;
        sim.players[defender].position = Vec2::new(40.0, 60.0);
        sim.players[attacker].position = Vec2::new(41.0, 62.5);
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[attacker].runaround = Some(RunaroundDribble {
            defender,
            launch_clock_seconds: sim.clock_seconds - 2.35,
            push_target: Vec2::new(41.0, 61.0),
            recollect_point: sim.players[attacker].position,
            knocked: true,
        });
        let launch_tick = sim
            .tick
            .saturating_sub(RUNAROUND_LEARNING_CREDIT_MAX_AGE_TICKS - 1);
        sim.recent_learning_history.push_back(world_test_transition(
            &sim,
            attacker,
            "runaround-dribble",
            launch_tick,
        ));
        sim.recent_learning_history.push_back(world_test_transition(
            &sim,
            defender,
            "defend",
            launch_tick,
        ));

        let deferred_start = sim.deferred_reward_transitions.len();
        let episode_start = sim.episode_learning_transitions.len();
        let event_start = sim.events.len();
        let beat_start = sim.stats.dribble_beats_home;
        sim.maintain_runaround_commitments();

        assert!(sim.players[attacker].runaround.is_none());
        assert_eq!(sim.stats.dribble_beats_home, beat_start + 1);
        assert!(
            sim.events[event_start..]
                .iter()
                .any(|event| { event.team == Some(Team::Home) && event.kind == "carry-forward" }),
            "runaround success must emit a dribble-beat event for accounting"
        );
        let added = &sim.deferred_reward_transitions[deferred_start..];
        assert!(
            added.iter().any(|transition| {
                transition.player_id == attacker
                    && transition.tick == launch_tick
                    && normalize_soccer_action_label(&transition.action) == "runaround-dribble"
                    && transition.reward > 0.0
            }),
            "runaround success must replay the launch decision, got {added:?}"
        );
        assert!(
            added.iter().any(|transition| {
                transition.player_id == defender
                    && transition.tick == launch_tick
                    && normalize_soccer_action_label(&transition.action) == "defend"
                    && transition.reward < 0.0
            }),
            "runaround success must replay the beaten defender decision, got {added:?}"
        );
        assert!(
            sim.episode_learning_transitions[episode_start..]
                .iter()
                .any(|transition| {
                    transition.player_id == attacker
                        && transition.tick == launch_tick
                        && normalize_soccer_action_label(&transition.action) == "runaround-dribble"
                        && transition.reward > 0.0
                }),
            "full-game replay must include the credited runaround decision"
        );
    }

    #[test]
    fn overdribble_dispossession_penalty_replays_original_dribble_transition_across_ticks() {
        let _env = set_test_env_var("DD_SOCCER_ENABLE_OVERDRIBBLE_PENALTY", "1");
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            learning_enabled: true,
            full_game_learning_enabled: true,
            duration_seconds: 1.0,
            seed: 13_337,
            ..MatchConfig::default()
        });
        let attacker = sim
            .players
            .iter()
            .find(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .expect("home field player")
            .id;
        let defender = sim
            .players
            .iter()
            .find(|player| player.team == Team::Away && player.role != PlayerRole::Goalkeeper)
            .expect("away field player")
            .id;
        let spot = Vec2::new(
            sim.config.field_width_yards * 0.5,
            sim.config.field_length_yards * 0.5,
        );
        sim.tick = 240;
        sim.clock_seconds = 5.0;
        sim.players[attacker].position = spot;
        sim.players[defender].position = spot + Vec2::new(1.0, 0.0);
        sim.ball.holder = Some(attacker);
        sim.ball.position = spot;
        sim.ball.last_touch_team = Some(Team::Home);
        sim.ball.position_history.clear();
        for i in 0..40_u64 {
            sim.ball.position_history.push_back(BallPositionSample {
                tick: i,
                clock_seconds: 3.0 + i as f64 * 0.05,
                position: spot,
                velocity: Vec2::zero(),
                acceleration: Vec2::zero(),
                jerk: Vec2::zero(),
                curl_acceleration: Vec2::zero(),
                altitude_yards: 0.0,
                resistance: BallResistanceFrame::default(),
                holder: Some(attacker),
                last_touch_team: Some(Team::Home),
            });
        }
        sim.recent_learning_history
            .push_back(world_test_transition(&sim, attacker, "dribble", 238));
        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(attacker);
        sim.players[attacker].last_decision = Some(AgentDecisionTrace {
            mdp_state: snapshot.mdp_state_for_player(attacker),
            observation: observation.clone(),
            belief: belief_from_observation(&observation),
            operation_order: vec!["learned-policy".to_string(), "dribble".to_string()],
            scheduled_index: None,
            action_options: single_action_option("dribble"),
            action_target: None,
            mdp_mpc_comparison: None,
            learned_mpc_replan: None,
            behavior_policy_probability: None,
            actor_policy_probability: None,
            neural_mcts_selected: false,
            neural_mcts_candidate_count: 0,
            neural_mcts_discretized_kick_candidate_count: 0,
            neural_mcts_root_discretized_kick_candidate_count: 0,
            neural_mcts_dribble_candidate_count: 0,
            neural_mcts_root_dribble_candidate_count: 0,
            action: "dribble".to_string(),
        });

        let deferred_start = sim.deferred_reward_transitions.len();
        let episode_start = sim.episode_learning_transitions.len();
        let dribble_turnover_start = sim.stats.dribble_turnovers_home;
        sim.complete_defensive_dispossession(defender, attacker, "tackle");

        assert_eq!(sim.stats.dribble_turnovers_home, dribble_turnover_start + 1);
        let added = &sim.deferred_reward_transitions[deferred_start..];
        assert!(
            added.iter().any(|transition| {
                transition.player_id == attacker
                    && transition.tick == 238
                    && normalize_soccer_action_label(&transition.action) == "dribble"
                    && transition.reward < 0.0
            }),
            "overdribble loss must replay the original dribble decision, got {added:?}"
        );
        assert!(
            sim.episode_learning_transitions[episode_start..]
                .iter()
                .any(|transition| {
                    transition.player_id == attacker
                        && transition.tick == 238
                        && transition.reward < 0.0
                }),
            "full-game replay must see overdribble dispossession penalty"
        );
    }

    #[test]
    fn pass_role_risk_penalizes_defenders_more_than_forwards() {
        let risky = pass_role_risk_test_quality(0.35, 0.70, 0.35, 0.55, 0.40);
        let origin = Vec2::new(34.0, 58.0);
        let target = Vec2::new(38.0, 64.0);
        let defender = pass_role_risk_score_adjustment(
            PlayerRole::Defender,
            Team::Home,
            origin,
            target,
            120.0,
            6.0,
            &risky,
            0.0,
        );
        let forward = pass_role_risk_score_adjustment(
            PlayerRole::Forward,
            Team::Home,
            origin,
            target,
            120.0,
            6.0,
            &risky,
            0.0,
        );

        assert!(
            defender.penalty > forward.penalty * 2.0,
            "defender penalty {} should clearly exceed forward penalty {}",
            defender.penalty,
            forward.penalty
        );
        assert!(
            defender.safety_bonus > forward.safety_bonus,
            "defender safety bonus {} should exceed forward safety bonus {}",
            defender.safety_bonus,
            forward.safety_bonus
        );
    }

    #[test]
    fn pass_role_risk_final_third_forward_relief_is_forward_led() {
        let risky = pass_role_risk_test_quality(0.35, 0.70, 0.35, 0.55, 0.40);
        let origin = Vec2::new(40.0, 92.0);
        let forward_target = Vec2::new(42.0, 106.0);
        let backward_target = Vec2::new(42.0, 84.0);
        let attacking_forward = pass_role_risk_score_adjustment(
            PlayerRole::Forward,
            Team::Home,
            origin,
            forward_target,
            120.0,
            14.0,
            &risky,
            0.0,
        );
        let recycling_forward = pass_role_risk_score_adjustment(
            PlayerRole::Forward,
            Team::Home,
            origin,
            backward_target,
            120.0,
            -8.0,
            &risky,
            0.0,
        );
        let attacking_defender = pass_role_risk_score_adjustment(
            PlayerRole::Defender,
            Team::Home,
            origin,
            forward_target,
            120.0,
            14.0,
            &risky,
            0.0,
        );

        assert!(
            attacking_forward.forward_risk_bonus > 0.0,
            "forward final-third risk bonus should be active"
        );
        assert!(
            attacking_forward.penalty < recycling_forward.penalty,
            "forward target penalty {} should be below backward target penalty {}",
            attacking_forward.penalty,
            recycling_forward.penalty
        );
        assert!(
            attacking_defender.forward_risk_bonus < attacking_forward.forward_risk_bonus * 0.25,
            "defender bonus {} should stay much smaller than forward bonus {}",
            attacking_defender.forward_risk_bonus,
            attacking_forward.forward_risk_bonus
        );
    }

