    #[test]
    fn genome_anchor_home_positions_reanchor_only_when_gated() {
        use crate::des::general::soccer_genome::{GenomeRole, SoccerTeamGenome};

        std::env::remove_var("DD_SOCCER_ENABLE_GENOME_ANCHOR_HOME_POSITIONS");
        let config = MatchConfig::default();
        let mut sim = SoccerMatch::default_11v11(config.clone());

        let gk_id = sim
            .players
            .iter()
            .find(|p| p.team == Team::Home && p.role == PlayerRole::Goalkeeper)
            .map(|p| p.id)
            .expect("home keeper");
        let gk_home = |sim: &SoccerMatch| {
            sim.players
                .iter()
                .find(|p| p.id == gk_id)
                .unwrap()
                .home_position
        };
        let default_home = gk_home(&sim);

        // Gate OFF ⇒ installing a genome leaves home positions byte-identical.
        sim.set_team_tactical_genome(Team::Home, SoccerTeamGenome::default());
        assert_eq!(default_home, gk_home(&sim), "gate off ⇒ home unchanged");

        // Gate ON ⇒ the keeper snaps to its genome anchor's fine-cell centre.
        std::env::set_var("DD_SOCCER_ENABLE_GENOME_ANCHOR_HOME_POSITIONS", "1");
        let genome = SoccerTeamGenome::default();
        let gk_anchor = genome
            .anchors
            .iter()
            .find(|a| a.role == GenomeRole::Goalkeeper)
            .copied()
            .expect("keeper anchor");
        let expected = genome_anchor_home_position(
            gk_anchor.lane,
            gk_anchor.row,
            Team::Home,
            config.field_width_yards,
            config.field_length_yards,
        );
        sim.set_team_tactical_genome(Team::Home, genome);
        let snapped = gk_home(&sim);
        std::env::remove_var("DD_SOCCER_ENABLE_GENOME_ANCHOR_HOME_POSITIONS");

        assert!(
            (snapped.x - expected.x).abs() < 1e-9 && (snapped.y - expected.y).abs() < 1e-9,
            "gate on ⇒ keeper homed on its 12×24 anchor cell"
        );

        // Fix D: every player maps 1:1 onto an anchor cell, and the team's role counts
        // now equal the genome's per-role anchor counts (the default genome is F433 —
        // 3 mid / 3 fwd — re-roled from the 4-4-2 spawn lineup).
        let reference = SoccerTeamGenome::default();
        let anchor_cells: std::collections::HashSet<(usize, usize)> = reference
            .anchors
            .iter()
            .map(|a| (a.lane as usize, a.row as usize))
            .collect();
        let mut role_counts = std::collections::HashMap::new();
        for player in sim.players.iter().filter(|p| p.team == Team::Home) {
            let fine = pitch_grid_address(
                player.home_position,
                config.field_width_yards,
                config.field_length_yards,
            )
            .fine;
            // Away anchors mirror the row, but this is the Home team — fine cell == anchor.
            assert!(
                anchor_cells.contains(&(fine.x, fine.y)),
                "home {:?} re-anchored onto a genome cell",
                player.role
            );
            *role_counts.entry(player.role).or_insert(0usize) += 1;
        }
        let genome_role_count =
            |want: GenomeRole| reference.anchors.iter().filter(|a| a.role == want).count();
        assert_eq!(
            role_counts.get(&PlayerRole::Defender).copied().unwrap_or(0),
            genome_role_count(GenomeRole::Defender)
        );
        assert_eq!(
            role_counts
                .get(&PlayerRole::Midfielder)
                .copied()
                .unwrap_or(0),
            genome_role_count(GenomeRole::Midfielder),
            "midfielders reconciled to the genome's count"
        );
        assert_eq!(
            role_counts.get(&PlayerRole::Forward).copied().unwrap_or(0),
            genome_role_count(GenomeRole::Forward),
            "forwards reconciled to the genome's count"
        );
        assert_eq!(role_counts.values().sum::<usize>(), 11, "all 11 assigned");
    }

