    #[test]
    fn learned_plan_for_policy_preserves_ranked_pass_receiver_choice() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let actor = sim
            .players
            .iter()
            .position(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .expect("home field player");
        let actor_id = sim.players[actor].id;
        sim.players[actor].position = Vec2::new(40.0, 44.0);
        sim.ball.holder = Some(actor_id);
        sim.ball.position = sim.players[actor].position;

        for (slot, position) in [
            Vec2::new(46.0, 55.0),
            Vec2::new(34.0, 58.0),
            Vec2::new(51.0, 64.0),
        ]
        .iter()
        .enumerate()
        {
            let teammate = sim
                .players
                .iter()
                .enumerate()
                .filter(|(_, player)| {
                    player.team == Team::Home
                        && player.id != actor_id
                        && player.role != PlayerRole::Goalkeeper
                })
                .nth(slot)
                .map(|(index, _)| index)
                .expect("same-team pass target");
            sim.players[teammate].position = *position;
            sim.players[teammate].velocity = Vec2::zero();
        }

        let snapshot = WorldSnapshot::from_match(&sim);
        let ranked_targets = snapshot.ranked_visible_pass_targets(actor_id, 3);
        assert!(
            ranked_targets.len() >= 2,
            "fixture needs at least two ranked pass targets, got {:?}",
            ranked_targets
        );
        let expected_second = ranked_targets[1];
        let policy = SoccerQPolicy::default();

        let pass2 =
            SoccerMatch::learned_plan_for_policy(&policy, &snapshot, actor_id, "pass2".to_string());
        assert_eq!(pass2.target_player, Some(expected_second));
        assert_eq!(
            pass2.target_point,
            snapshot.player_position(expected_second)
        );

        let pass2_bucket = SoccerMatch::learned_plan_for_policy(
            &policy,
            &snapshot,
            actor_id,
            "pass2-kp7".to_string(),
        );
        assert_eq!(pass2_bucket.target_player, Some(expected_second));
        assert_eq!(
            SoccerMatch::learned_ranked_pass_target_for_policy(
                "aerial-pass3-kp7",
                PassFlight::Aerial,
                &[101, 202, 303],
            ),
            Some(303)
        );
    }

    #[test]
    fn mpc_replan_reselects_different_ranked_pass_target() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let actor = sim
            .players
            .iter()
            .position(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .expect("home field player");
        let actor_id = sim.players[actor].id;
        sim.players[actor].position = Vec2::new(40.0, 52.0);
        sim.ball.holder = Some(actor_id);
        sim.ball.position = sim.players[actor].position;
        sim.ball.last_touch_team = Some(Team::Home);
        for (index, player) in sim.players.iter_mut().enumerate() {
            player.velocity = Vec2::zero();
            if player.team == Team::Away {
                player.position = Vec2::new(6.0 + index as f64 * 0.4, 12.0);
            }
        }

        let targets = sim
            .players
            .iter()
            .enumerate()
            .filter(|(_, player)| {
                player.team == Team::Home
                    && player.id != actor_id
                    && player.role != PlayerRole::Goalkeeper
            })
            .map(|(index, _)| index)
            .take(2)
            .collect::<Vec<_>>();
        assert_eq!(targets.len(), 2, "need two same-team pass targets");
        for (slot, target) in targets.iter().copied().enumerate() {
            sim.players[target].position = Vec2::new(36.0 + slot as f64 * 7.0, 58.0);
        }

        let snapshot = WorldSnapshot::from_match(&sim);
        let ranked_targets = snapshot.ranked_visible_pass_targets(actor_id, 3);
        assert!(
            ranked_targets.len() >= 2,
            "fixture needs at least two ranked pass targets, got {:?}",
            ranked_targets
        );
        let expected_replacement_target = ranked_targets[1];
        let player = snapshot
            .players
            .iter()
            .find(|player| player.id == actor_id)
            .expect("actor snapshot");
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(actor_id),
            &snapshot.observation_for(actor_id),
            player.team,
            player.role,
        );
        let mut policy = SoccerQPolicy::default();
        assert!(policy.insert_q_value(
            SoccerQActionKey {
                state: state.clone(),
                action: "pass1".to_string(),
            },
            10.0,
        ));
        assert!(policy.insert_q_value(
            SoccerQActionKey {
                state: state.clone(),
                action: "pass2".to_string(),
            },
            8.0,
        ));
        let replacement_plan =
            SoccerMatch::learned_plan_for_policy(&policy, &snapshot, actor_id, "pass2".to_string());
        assert_eq!(
            replacement_plan.target_player,
            Some(expected_replacement_target)
        );
        assert!(
            !SoccerMatch::learned_plan_needs_mpc_replan(&snapshot, actor_id, &replacement_plan),
            "fixture replacement pass should be executable enough for MPC"
        );

        let rejected_pass = SoccerLearnedPlan {
            action: "pass1".to_string(),
            target_player: None,
            target_point: None,
            mpc_replan: None,
        };
        assert!(
            SoccerMatch::learned_plan_needs_mpc_replan(&snapshot, actor_id, &rejected_pass),
            "an un-targeted pass decision must kick back from MPC"
        );

        let replanned =
            SoccerMatch::mpc_reconciled_learned_plan(&policy, &snapshot, actor_id, rejected_pass);
        assert_eq!(replanned.action, "pass2");
        assert_eq!(
            replanned.target_player,
            Some(expected_replacement_target),
            "MPC rejection should return to POMDP/ranked choice, not retry pass1"
        );
        let trace = replanned.mpc_replan.expect("replacement should be traced");
        assert_eq!(trace.original_action, "pass1");
        assert_eq!(trace.replacement_action, "pass2");
        assert!(matches!(trace.source, SoccerLearnedMpcReplanSource::Mpc));
        assert_eq!(trace.candidate_count, 1);
    }

    #[test]
    fn learned_receiver_mpc_kickback_is_traced_when_head_first_choice_is_infeasible() {
        let _env_lock = soccer_world_env_lock();
        let _receiver_gate = set_test_env_var("DD_SOCCER_ENABLE_LEARNED_PASS_RECEIVER", "1");

        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let actor = sim
            .players
            .iter()
            .position(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .expect("home field player");
        let actor_id = sim.players[actor].id;
        let actor_position = Vec2::new(40.0, 52.0);
        sim.players[actor].position = actor_position;
        sim.ball.holder = Some(actor_id);
        sim.ball.position = actor_position;
        sim.ball.last_touch_team = Some(Team::Home);
        for (index, player) in sim.players.iter_mut().enumerate() {
            player.velocity = Vec2::zero();
            if player.team == Team::Away {
                player.position = Vec2::new(72.0, 12.0 + index as f64 * 0.3);
            }
        }

        let targets = sim
            .players
            .iter()
            .enumerate()
            .filter(|(_, player)| {
                player.team == Team::Home
                    && player.id != actor_id
                    && player.role != PlayerRole::Goalkeeper
            })
            .map(|(index, _)| index)
            .take(2)
            .collect::<Vec<_>>();
        assert_eq!(targets.len(), 2, "need two same-team pass targets");
        let bad_target = sim.players[targets[0]].id;
        let good_target = sim.players[targets[1]].id;
        let bad_position = Vec2::new(2.0, 118.0);
        let good_position = Vec2::new(42.0, 62.0);
        sim.players[targets[0]].position = bad_position;
        sim.players[targets[1]].position = good_position;

        let snapshot = WorldSnapshot::from_match(&sim);
        let player = snapshot
            .players
            .iter()
            .find(|player| player.id == actor_id)
            .expect("actor snapshot");
        let bad_player = snapshot
            .players
            .iter()
            .find(|player| player.id == bad_target)
            .expect("bad target snapshot");
        let good_player = snapshot
            .players
            .iter()
            .find(|player| player.id == good_target)
            .expect("good target snapshot");
        let bad_plan = SoccerLearnedPlan {
            action: "pass".to_string(),
            target_player: Some(bad_target),
            target_point: Some(bad_position),
            mpc_replan: None,
        };
        let good_plan = SoccerLearnedPlan {
            action: "pass".to_string(),
            target_player: Some(good_target),
            target_point: Some(good_position),
            mpc_replan: None,
        };
        let threshold = learned_mpc_replan_thresholds().pass_impossible_probability;
        let bad_probability = SoccerMatch::learned_pass_mpc_execution_probability(
            &snapshot,
            actor_id,
            &bad_plan,
            PassFlight::Floor,
        );
        let good_probability = SoccerMatch::learned_pass_mpc_execution_probability(
            &snapshot,
            actor_id,
            &good_plan,
            PassFlight::Floor,
        );
        assert!(
            bad_probability < threshold,
            "fixture should make the head's first receiver infeasible: {bad_probability}"
        );
        assert!(
            good_probability >= threshold,
            "fixture should leave the second receiver executable: {good_probability}"
        );

        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(actor_id),
            &snapshot.observation_for(actor_id),
            player.team,
            player.role,
        );
        let mut policy = SoccerQPolicy::default();
        let bad_descriptor = snapshot.pass_receiver_descriptor(
            actor_id,
            ReceiverKind::Teammate,
            bad_position,
            Some(bad_player.role),
        );
        let good_descriptor = snapshot.pass_receiver_descriptor(
            actor_id,
            ReceiverKind::Teammate,
            good_position,
            Some(good_player.role),
        );
        assert!(policy.set_target_value_with_receiver(
            state.clone(),
            "pass",
            pitch_grid_address(bad_position, snapshot.field_width, snapshot.field_length),
            bad_descriptor,
            4.0,
        ));
        assert!(policy.set_target_value_with_receiver(
            state,
            "pass",
            pitch_grid_address(good_position, snapshot.field_width, snapshot.field_length),
            good_descriptor,
            0.25,
        ));

        let (target_player, target_point, replan) = SoccerMatch::learned_pass_receiver_selection(
            &policy,
            &snapshot,
            actor_id,
            "pass",
            PassFlight::Floor,
            &[bad_target, good_target],
        );
        assert_eq!(target_player, Some(good_target));
        assert_eq!(target_point, Some(good_position));
        let replan = replan.expect("receiver kickback should be visible to learning");
        assert_eq!(replan.original_action, "pass");
        assert_eq!(replan.replacement_action, "pass");
        assert_eq!(replan.source, SoccerLearnedMpcReplanSource::Mpc);
        assert_eq!(replan.candidate_count, 1);
        assert!((replan.rejected_execution_probability - bad_probability).abs() < 1e-12);
    }

    #[test]
    fn learned_mpc_rejection_threshold_tracks_contextual_policy_competition() {
        // Decisive: the committed action (0.82) dominates the best alternative (0.10) ⇒
        // relax the bar below base. Competitive: alternative (0.40) ≈ original (0.42) ⇒
        // barely moves. Exercises the blend math directly, so it does not depend on the
        // `DD_SOCCER_ENABLE_MPC_CONTEXT_THRESHOLD` gate (which the wrapper applies) and
        // cannot race a parallel test on that process-global flag.
        let base = 0.18;
        let decisive_threshold = contextual_rejection_threshold_blend(base, 0.82, 0.10);
        let competitive_threshold = contextual_rejection_threshold_blend(base, 0.42, 0.40);

        assert!(decisive_threshold < base);
        assert!(competitive_threshold > decisive_threshold);
        assert!((0.0..=1.0).contains(&competitive_threshold));
    }

