    #[test]
    fn neural_mcts_expands_shoot_into_targeted_shot_variant() {
        let _env_lock = soccer_world_env_lock();
        let _gate = set_test_env_var("DD_SOCCER_ENABLE_DISCRETIZED_KICK", "1");
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            learning_enabled: true,
            ..MatchConfig::default()
        });
        let actor = sim
            .players
            .iter()
            .position(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .expect("home field player");
        let actor_id = sim.players[actor].id;
        let actor_team = sim.players[actor].team;
        sim.players[actor].position = Vec2::new(33.0, 94.0);
        sim.players[actor].skills.shooting = 8.5;
        sim.players[actor].skills.first_touch = 8.0;
        sim.players[actor].skills.right_foot_shot_power = 8.4;
        let keeper = sim
            .players
            .iter()
            .position(|player| player.team == Team::Away && player.role == PlayerRole::Goalkeeper)
            .expect("away keeper");
        sim.players[keeper].position = Vec2::new(35.0, 119.0);
        let snapshot = WorldSnapshot::from_match(&sim);
        let expanded = SoccerMatch::neural_mcts_expanded_candidate_plans(
            &snapshot, actor_id, actor_team, "shoot",
        );
        let labels = expanded
            .iter()
            .map(|plan| plan.action.as_str())
            .collect::<Vec<_>>();
        assert!(labels.contains(&"shoot"));
        assert!(
            labels.iter().any(|label| label.starts_with("shoot-kp")),
            "shoot expansion should include learnable shot-power buckets"
        );
        let goal_center = Some(Vec2::new(
            snapshot.field_width * 0.5,
            actor_team.goal_y(snapshot.field_length),
        ));
        for plan in &expanded {
            let expected_target = SoccerMatch::learned_shot_target_point_for_plan(
                &snapshot,
                actor_id,
                actor_team,
                "shoot",
                &plan.action,
            )
            .expect("shot candidate target");
            assert_eq!(plan.target_player, None);
            assert_eq!(plan.target_point, Some(expected_target));
            assert_ne!(
                plan.target_point, goal_center,
                "shot candidates should target the MPC-selected goalmouth point, not blindly centre"
            );
        }

        let exact_bucket = SoccerMatch::neural_mcts_expanded_candidate_plans(
            &snapshot,
            actor_id,
            actor_team,
            "shoot-kp7",
        );
        assert_eq!(exact_bucket.len(), 1);
        assert_eq!(exact_bucket[0].action, "shoot-kp7");
        let expected_bucket_target = SoccerMatch::learned_shot_target_point_for_plan(
            &snapshot,
            actor_id,
            actor_team,
            "shoot",
            "shoot-kp7",
        )
        .expect("bucket shot target");
        assert_eq!(exact_bucket[0].target_point, Some(expected_bucket_target));
    }

    #[test]
    fn neural_authoritative_keeps_discretized_kick_buckets_beside_plain_family() {
        let plain_shoot = SoccerLearnedActionTrace {
            label: "shoot".to_string(),
            value: 1.0,
            visits: 4,
            probability: 1.0,
            legal: true,
            level: PitchGridLevel::Fine,
        };
        let legal = vec![plain_shoot.clone()];

        assert!(
            SoccerMatch::neural_authoritative_candidate_already_present(&legal, "shoot"),
            "plain family should still dedupe by normalized action"
        );
        assert!(
            !SoccerMatch::neural_authoritative_candidate_already_present(&legal, "shoot-kp7"),
            "a plain shoot candidate must not starve the actor-owned shot-power bucket"
        );
        assert_eq!(
            SoccerMatch::neural_authoritative_candidate_label_for_policy_action("shoot-kp7"),
            "shoot-kp7"
        );

        let mut legal_with_bucket = vec![plain_shoot];
        legal_with_bucket.push(SoccerLearnedActionTrace {
            label: "shoot-kp7".to_string(),
            value: 0.0,
            visits: 0,
            probability: 0.0,
            legal: true,
            level: PitchGridLevel::WholePitch,
        });
        assert!(
            SoccerMatch::neural_authoritative_candidate_already_present(
                &legal_with_bucket,
                "shoot-kp7"
            ),
            "exact bucket labels should dedupe after they have been injected"
        );
    }

    #[test]
    fn discretized_kick_gate_expands_pass_targets_into_power_bucket_candidates() {
        let _env_lock = soccer_world_env_lock();
        let _env = set_test_env_var("DD_SOCCER_ENABLE_DISCRETIZED_KICK", "1");
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            learning_enabled: true,
            ..MatchConfig::default()
        });
        let actor = sim
            .players
            .iter()
            .position(|player| player.team == Team::Home && player.role != PlayerRole::Goalkeeper)
            .expect("home field player");
        let actor_id = sim.players[actor].id;
        let actor_team = sim.players[actor].team;
        let actor_role = sim.players[actor].role;
        sim.players[actor].position = Vec2::new(40.0, 44.0);
        sim.ball.holder = Some(actor_id);
        sim.ball.position = sim.players[actor].position;

        let target = sim
            .players
            .iter()
            .position(|player| {
                player.team == actor_team
                    && player.id != actor_id
                    && player.role != PlayerRole::Goalkeeper
            })
            .expect("same-team pass target");
        sim.players[target].position = Vec2::new(46.0, 62.0);
        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(actor_id);
        let mdp_state = snapshot.mdp_state_for_player(actor_id);
        let base = sim.neural_decision_transition(
            &snapshot,
            actor_id,
            actor_team,
            actor_role,
            &mdp_state,
            &observation,
        );

        let expanded = SoccerMatch::neural_mcts_expanded_candidate_plans(
            &snapshot, actor_id, actor_team, "pass",
        );
        let visible_targets = snapshot.ranked_visible_pass_targets(actor_id, 11);
        let learned_buckets = expanded
            .iter()
            .filter_map(|plan| {
                plan.target_player
                    .filter(|target| visible_targets.contains(target))?;
                learned_discretized_kick_speed_bucket_for_action_label(&plan.action)
                    .map(|bucket| (bucket, plan))
            })
            .collect::<Vec<_>>();
        let (learned_bucket_index, learned_bucket) = learned_buckets
            .iter()
            .max_by_key(|(bucket, _)| *bucket)
            .copied()
            .expect("learned kick bucket candidate");
        let learned_bucket_suffix = format!("-kp{learned_bucket_index}");
        let baseline_action = learned_bucket
            .action
            .strip_suffix(&learned_bucket_suffix)
            .expect("learned bucket should retain its target-specific pass label");
        assert!(
            learned_buckets.iter().any(|(bucket, _)| *bucket == 3),
            "discretized kick gate should add a soft learned pass-power candidate"
        );
        let baseline = expanded
            .iter()
            .find(|plan| plan.action == baseline_action)
            .expect("baseline target-specific pass remains available");
        let scored_baseline = sim
            .neural_decision_transition_for_plan(&base, &snapshot, actor_id, actor_team, baseline);
        let scored_bucket = sim.neural_decision_transition_for_plan(
            &base,
            &snapshot,
            actor_id,
            actor_team,
            learned_bucket,
        );
        assert_eq!(scored_bucket.action, learned_bucket.action);
        assert_eq!(
            learned_discretized_kick_speed_bucket_for_action_label(&scored_bucket.action),
            Some(learned_bucket_index)
        );
        assert!(
            scored_bucket.decision_context.action_ball_speed_yps
                > scored_baseline.decision_context.action_ball_speed_yps + 1e-6,
            "candidate features should expose the learned kick speed, not only a label hash"
        );
        let learned_power = learned_discretized_kick_power_for_action_label(&scored_bucket.action)
            .expect("learned kick power");
        let passer = snapshot
            .players
            .iter()
            .find(|player| player.id == actor_id)
            .expect("passer snapshot");
        let context_target_player = scored_bucket
            .decision_context
            .target_player
            .expect("context target player");
        let target_snapshot = snapshot
            .players
            .iter()
            .find(|player| player.id == context_target_player)
            .expect("target snapshot");
        let context_target_point = scored_bucket
            .decision_context
            .target_point
            .expect("context target point");
        let context_target_position = scored_bucket
            .decision_context
            .target_player_position
            .expect("context target player position");
        let flight = pass_like_action_flight(&scored_bucket.action).expect("pass flight");
        let context_is_cross = pass_would_be_cross(
            scored_bucket.decision_context.actor_position,
            context_target_point,
            actor_team,
            snapshot.field_width,
            snapshot.field_length,
        );
        let expected_speed =
            pass_speed_yps_from_power(learned_power, flight, context_is_cross, &passer.skills);
        assert!(
            (scored_bucket.decision_context.action_ball_speed_yps - expected_speed).abs() < 1e-9,
            "action_ball_speed_yps must come from the learned bucket: context={} expected={}",
            scored_bucket.decision_context.action_ball_speed_yps,
            expected_speed
        );
        let expected_mpc = pass_mpc_receipt_estimate_for_snapshot(
            &snapshot,
            passer,
            scored_bucket.decision_context.actor_position,
            target_snapshot,
            context_target_position,
            flight,
            scored_bucket.decision_context.action_ball_speed_yps,
            context_target_point,
        );
        assert!(
            (scored_bucket
                .decision_context
                .pass_mpc_receipt_probability
                - expected_mpc.probability)
                .abs()
                < 1e-9,
            "learned kick candidates must score receipt MPC with the selected bucket speed: context={} expected={} speed={} qp={} expected_qp={}",
            scored_bucket
                .decision_context
                .pass_mpc_receipt_probability,
            expected_mpc.probability,
            scored_bucket.decision_context.action_ball_speed_yps,
            scored_bucket.decision_context.pass_receipt_qp_accel_fit,
            expected_mpc.qp_accel_fit
        );
        let mut good_bucket = scored_bucket.clone();
        good_bucket.decision_context.pass_mpc_receipt_probability = 0.94;
        good_bucket.decision_context.pass_receipt_qp_accel_fit = 0.91;
        good_bucket.decision_context.chosen_action_mpc_feasibility = 0.93;
        good_bucket.decision_context.chosen_action_control_cost = 0.08;
        good_bucket
            .decision_context
            .pass_receipt_race_advantage_seconds = 0.80;
        good_bucket.decision_context.target_forward_yards = 18.0;
        let mut poor_bucket = scored_bucket.clone();
        poor_bucket.decision_context.pass_mpc_receipt_probability = 0.12;
        poor_bucket.decision_context.pass_receipt_qp_accel_fit = 0.08;
        poor_bucket.decision_context.chosen_action_mpc_feasibility = 0.10;
        poor_bucket.decision_context.chosen_action_control_cost = 0.92;
        poor_bucket
            .decision_context
            .pass_receipt_race_advantage_seconds = -1.20;
        poor_bucket.decision_context.target_forward_yards = -10.0;
        let good_bonus = neural_mcts_pass_mpc_candidate_bonus(&good_bucket);
        let poor_bonus = neural_mcts_pass_mpc_candidate_bonus(&poor_bucket);
        assert!(
            good_bonus > 0.0 && poor_bonus < 0.0 && good_bonus > poor_bonus,
            "MPC prior should lift feasible learned pass powers and suppress bad ones: good={good_bonus} poor={poor_bonus}"
        );
        let (action, executed_label) = sim.players[actor]
            .action_from_learned_plan(learned_bucket, &snapshot, &observation)
            .expect("learned kick bucket pass should execute");
        assert_eq!(executed_label, learned_bucket.action);
        let SoccerAction::Pass { power, .. } = action else {
            panic!("learned kick bucket should execute as a pass");
        };
        assert!(
            (power - learned_power).abs() < 1e-9,
            "execution must carry the selected discretized kick power bucket"
        );
    }

