    pub fn with_neural_network_snapshot(
        mut self,
        snapshot: SoccerNeuralNetworkSnapshot,
    ) -> Result<Self, String> {
        self.set_neural_network_snapshot(snapshot)?;
        Ok(self)
    }

    pub fn set_neural_network_snapshot(
        &mut self,
        snapshot: SoccerNeuralNetworkSnapshot,
    ) -> Result<(), String> {
        // Normally a net is only installed when learning is enabled. But under NEURAL-AUTHORITATIVE
        // serve (DD_SOCCER_NEURAL_AUTHORITATIVE_LAMBDA>0) the live server has learning OFF yet must
        // still install the net for INFERENCE so it can drive decisions — otherwise the net is
        // dropped and play silently falls back to the tabular/analytic path.
        if !self.config.neural_learning.enabled && dd_soccer_neural_authoritative_lambda() <= 0.0 {
            self.neural_learner = None;
            return Ok(());
        }
        let snapshot = widen_soccer_neural_snapshot_for_config(
            snapshot,
            &self.config.neural_learning,
            self.config.seed,
        );
        // Decode the complete serving bundle before mutating the match.  A sidecar
        // is one atomic policy generation: accepting its critic while rejecting a
        // specialist head leaves live play on an unrepeatable mixture of old and
        // new weights.
        let network = build_soccer_neural_network_from_snapshot(&snapshot)?;
        let neural_learner = Some(SoccerNeuralLearner::from_pretrained_snapshot(
            &self.config,
            network,
            &snapshot,
        ));
        let policy_head = if let Some(policy_head) = snapshot.policy_head.as_deref() {
            Some(soccer_policy_head_from_snapshot(
                policy_head,
                self.config.seed,
            )?)
        } else if self.neural_blend.actor_critic {
            Some(SoccerPolicyHead::new(self.config.seed))
        } else {
            None
        };
        let central_critic_head = if let Some(head) = snapshot.central_critic_head.as_deref() {
            Some(SoccerCentralCriticHead::from_snapshot(head)?)
        } else {
            None
        };
        let skill_policy_heads =
            if let Some(skill_policy_heads) = snapshot.skill_policy_heads.as_deref() {
                Some(soccer_skill_policy_heads_from_snapshot(
                    skill_policy_heads,
                    self.config.seed,
                )?)
            } else {
                None
            };
        let keeper_policy_head =
            if let Some(keeper_policy_head) = snapshot.keeper_policy_head.as_deref() {
                Some(soccer_keeper_policy_head_from_snapshot(
                    keeper_policy_head,
                    self.config.seed,
                )?)
            } else {
                None
            };
        let line_depth_head = if let Some(line_depth_head) = snapshot.line_depth_head.as_deref() {
            Some(std::sync::Arc::new(BackFourLineHead::from_snapshot(
                line_depth_head,
            )?))
        } else {
            None
        };
        let pass_completion_head =
            if let Some(pass_completion_head) = snapshot.pass_completion_head.as_deref() {
                Some(std::sync::Arc::new(
                    SoccerPassCompletionHead::from_snapshot(pass_completion_head)?,
                ))
            } else {
                None
            };
        let mpc_objective_head =
            if let Some(mpc_objective_head) = snapshot.mpc_objective_head.as_deref() {
                Some(std::sync::Arc::new(SoccerMpcObjectiveHead::from_snapshot(
                    mpc_objective_head,
                )?))
            } else {
                None
            };
        let attack_spacing_head =
            if let Some(attack_spacing_head) = snapshot.attack_spacing_head.as_deref() {
                Some(std::sync::Arc::new(AttackSpacingHead::from_snapshot(
                    attack_spacing_head,
                )?))
            } else {
                None
            };
        let support_scorer_head =
            if let Some(support_scorer_head) = snapshot.support_scorer_head.as_deref() {
                Some(std::sync::Arc::new(SupportScorerHead::from_snapshot(
                    support_scorer_head,
                )?))
            } else {
                None
            };

        self.neural_learner = neural_learner;
        self.policy_head = policy_head;
        self.away_policy_head = None;
        self.central_critic_head = central_critic_head;
        self.away_central_critic_head = None;
        self.skill_policy_heads = skill_policy_heads;
        self.keeper_policy_head = keeper_policy_head;
        self.away_skill_policy_heads = None;
        self.line_depth_head = line_depth_head;
        self.pass_completion_head = pass_completion_head;
        self.mpc_objective_head = mpc_objective_head;
        self.attack_spacing_head = attack_spacing_head;
        self.support_scorer_head = support_scorer_head;
        self.away_pass_completion_head = None;
        self.away_mpc_objective_head = None;
        self.away_attack_spacing_head = None;
        self.away_support_scorer_head = None;
        Ok(())
    }

    fn clear_auxiliary_heads_for(&mut self, team: Team) {
        match team {
            Team::Home => {
                self.pass_completion_head = None;
                self.mpc_objective_head = None;
                self.attack_spacing_head = None;
                self.support_scorer_head = None;
            }
            Team::Away => {
                self.away_pass_completion_head = None;
                self.away_mpc_objective_head = None;
                self.away_attack_spacing_head = None;
                self.away_support_scorer_head = None;
            }
        }
    }

    fn restore_auxiliary_heads_for(
        &mut self,
        team: Team,
        snapshot: &SoccerNeuralNetworkSnapshot,
    ) -> Result<(), String> {
        let pass_completion_head =
            if let Some(pass_completion_head) = snapshot.pass_completion_head.as_deref() {
                Some(std::sync::Arc::new(
                    SoccerPassCompletionHead::from_snapshot(pass_completion_head)?,
                ))
            } else {
                None
            };
        let mpc_objective_head =
            if let Some(mpc_objective_head) = snapshot.mpc_objective_head.as_deref() {
                Some(std::sync::Arc::new(SoccerMpcObjectiveHead::from_snapshot(
                    mpc_objective_head,
                )?))
            } else {
                None
            };
        let attack_spacing_head =
            if let Some(attack_spacing_head) = snapshot.attack_spacing_head.as_deref() {
                Some(std::sync::Arc::new(AttackSpacingHead::from_snapshot(
                    attack_spacing_head,
                )?))
            } else {
                None
            };
        let support_scorer_head =
            if let Some(support_scorer_head) = snapshot.support_scorer_head.as_deref() {
                Some(std::sync::Arc::new(SupportScorerHead::from_snapshot(
                    support_scorer_head,
                )?))
            } else {
                None
            };
        match team {
            Team::Home => {
                self.pass_completion_head = pass_completion_head;
                self.mpc_objective_head = mpc_objective_head;
                self.attack_spacing_head = attack_spacing_head;
                self.support_scorer_head = support_scorer_head;
            }
            Team::Away => {
                self.away_pass_completion_head = pass_completion_head;
                self.away_mpc_objective_head = mpc_objective_head;
                self.away_attack_spacing_head = attack_spacing_head;
                self.away_support_scorer_head = support_scorer_head;
            }
        }
        Ok(())
    }

    /// Resolve the value/critic learner serving a given team. The away team falls
    /// back to the shared `neural_learner` when it has no dedicated learner, so
    /// single-net runs behave exactly as before.
    fn neural_learner_for(&self, team: Team) -> Option<&SoccerNeuralLearner> {
        match team {
            Team::Home => self.neural_learner.as_ref(),
            Team::Away => self.away_neural_learner.as_ref().or_else(|| {
                if self.away_neural_frozen {
                    None
                } else {
                    self.neural_learner.as_ref()
                }
            }),
        }
    }

    /// Mutable counterpart to [`neural_learner_for`]. Away resolves to its
    /// dedicated learner when present, else the shared `neural_learner`.
    fn neural_learner_for_mut(&mut self, team: Team) -> Option<&mut SoccerNeuralLearner> {
        match team {
            Team::Home => self.neural_learner.as_mut(),
            Team::Away => {
                if self.away_neural_learner.is_some() {
                    self.away_neural_learner.as_mut()
                } else if self.away_neural_frozen {
                    None
                } else {
                    self.neural_learner.as_mut()
                }
            }
        }
    }

    /// Skill heads follow the same home/shared vs. dedicated-away serving shape as the neural
    /// learner. In single-brain mode Away falls back to the shared Home sidecar; once Away is
    /// dedicated or explicitly frozen, missing Away heads mean "no specialist", not "borrow Home".
    fn skill_policy_heads_for(&self, team: Team) -> Option<&SoccerSkillPolicyHeads> {
        match team {
            Team::Home => self.skill_policy_heads.as_ref(),
            Team::Away => {
                if self.away_neural_learner.is_some() || self.away_neural_frozen {
                    self.away_skill_policy_heads.as_ref()
                } else {
                    self.away_skill_policy_heads
                        .as_ref()
                        .or(self.skill_policy_heads.as_ref())
                }
            }
        }
    }

    fn pass_completion_head_for_team(
        &self,
        team: Team,
    ) -> Option<std::sync::Arc<SoccerPassCompletionHead>> {
        match team {
            Team::Home => self.pass_completion_head.clone(),
            Team::Away => {
                if self.away_neural_learner.is_some() || self.away_neural_frozen {
                    self.away_pass_completion_head.clone()
                } else {
                    self.away_pass_completion_head
                        .clone()
                        .or_else(|| self.pass_completion_head.clone())
                }
            }
        }
    }

    fn mpc_objective_head_for(&self, team: Team) -> Option<std::sync::Arc<SoccerMpcObjectiveHead>> {
        match team {
            Team::Home => self.mpc_objective_head.clone(),
            Team::Away => {
                if self.away_neural_learner.is_some() || self.away_neural_frozen {
                    self.away_mpc_objective_head.clone()
                } else {
                    self.away_mpc_objective_head
                        .clone()
                        .or_else(|| self.mpc_objective_head.clone())
                }
            }
        }
    }

    fn attack_spacing_head_for_team(
        &self,
        team: Team,
    ) -> Option<std::sync::Arc<AttackSpacingHead>> {
        match team {
            Team::Home => self.attack_spacing_head.clone(),
            Team::Away => {
                if self.away_neural_learner.is_some() || self.away_neural_frozen {
                    self.away_attack_spacing_head.clone()
                } else {
                    self.away_attack_spacing_head
                        .clone()
                        .or_else(|| self.attack_spacing_head.clone())
                }
            }
        }
    }

    fn support_scorer_head_for_team(
        &self,
        team: Team,
    ) -> Option<std::sync::Arc<SupportScorerHead>> {
        match team {
            Team::Home => self.support_scorer_head.clone(),
            Team::Away => {
                if self.away_neural_learner.is_some() || self.away_neural_frozen {
                    self.away_support_scorer_head.clone()
                } else {
                    self.away_support_scorer_head
                        .clone()
                        .or_else(|| self.support_scorer_head.clone())
                }
            }
        }
    }

    fn neural_team_frozen(&self, team: Team) -> bool {
        match team {
            Team::Home => self.home_neural_frozen,
            Team::Away => self.away_neural_frozen,
        }
    }

    /// Drop every neural brain (both teams) and clear freeze flags — used when
    /// learning is toggled off or the backend changes at runtime.
    fn clear_all_neural_learners(&mut self) {
        self.neural_learner = None;
        self.away_neural_learner = None;
        self.policy_head = None;
        self.away_policy_head = None;
        self.central_critic_head = None;
        self.away_central_critic_head = None;
        self.home_neural_frozen = false;
        self.away_neural_frozen = false;
        self.skill_policy_heads = None;
        self.away_skill_policy_heads = None;
        self.clear_auxiliary_heads_for(Team::Home);
        self.clear_auxiliary_heads_for(Team::Away);
    }

    /// True when this match runs distinct per-team neural brains (the away team
    /// has its own learner) rather than one shared net.
    pub fn has_per_team_neural_learners(&self) -> bool {
        self.away_neural_learner.is_some()
    }

    /// Latest trained value/critic snapshot for the shared/home learner. This is
    /// the small (KB-scale) artifact that is the *real* converging learner — the
    /// tabular Q-table is a weak, fast-bloating prior. Persisted to a sidecar so
    /// warm-start restores the net even when the tabular policy file exceeds the
    /// autoload byte cap.
    pub fn neural_network_snapshot(&self) -> Option<SoccerNeuralNetworkSnapshot> {
        self.neural_network_snapshot_for(Team::Home)
    }

    /// Latest trained value/critic snapshot for a specific team's brain. Used by
    /// the tournament to extract each competitor's learned net after a match.
    pub fn neural_network_snapshot_for(&self, team: Team) -> Option<SoccerNeuralNetworkSnapshot> {
        self.neural_learner_for(team).and_then(|learner| {
            learner.last_network_snapshot.clone().map(|mut snapshot| {
                // Stamp the learner's live training progress so a net loaded for inference (or
                // resumed for training) is recognised as already-warm by the decision-time value
                // blend, keeping serve consistent with train.
                snapshot.training_steps = learner.training_steps();
                snapshot.average_loss = learner.average_loss();
                if let Some(policy_head) = self.policy_head_for(team) {
                    snapshot.policy_head = Some(Box::new(soccer_policy_head_snapshot(policy_head)));
                }
                let central_critic = match team {
                    Team::Home => self.central_critic_head.as_ref(),
                    Team::Away => self.away_central_critic_head.as_ref().or_else(|| {
                        (self.away_neural_learner.is_none() && !self.away_neural_frozen)
                            .then_some(self.central_critic_head.as_ref())
                            .flatten()
                    }),
                };
                snapshot.central_critic_head =
                    central_critic.map(|head| Box::new(head.to_snapshot()));
                if let Some(skill_policy_heads) = self.skill_policy_heads_for(team) {
                    snapshot.skill_policy_heads = Some(Box::new(
                        soccer_skill_policy_heads_snapshot(skill_policy_heads),
                    ));
                }
                if let Some(keeper_policy_head) = &self.keeper_policy_head {
                    snapshot.keeper_policy_head = Some(Box::new(
                        soccer_keeper_policy_head_snapshot(keeper_policy_head),
                    ));
                }
                if let Some(line_depth_head) = &self.line_depth_head {
                    snapshot.line_depth_head = Some(Box::new(line_depth_head.to_snapshot()));
                }
                snapshot.pass_completion_head = self
                    .pass_completion_head_for_team(team)
                    .map(|head| Box::new(head.to_snapshot()));
                snapshot.mpc_objective_head = self
                    .mpc_objective_head_for(team)
                    .map(|head| Box::new(head.to_snapshot()));
                snapshot.attack_spacing_head = self
                    .attack_spacing_head_for_team(team)
                    .map(|head| Box::new(head.to_snapshot()));
                snapshot.support_scorer_head = self
                    .support_scorer_head_for_team(team)
                    .map(|head| Box::new(head.to_snapshot()));
                snapshot
            })
        })
    }

    /// Gradient steps a team's brain has taken — per-team learning progress for
    /// tournament telemetry. A frozen team stays at its inherited step count.
    pub fn neural_training_steps_for(&self, team: Team) -> usize {
        self.neural_learner_for(team)
            .map_or(0, |learner| learner.stats.training_steps)
    }

    /// Install a dedicated per-team neural brain from a snapshot, optionally
    /// frozen (served for predictions but never trained). Installing the away
    /// team's brain switches the match into per-team mode. A `None` snapshot
    /// starts that team from a fresh (untrained) net so it can learn from scratch.
    /// Install a team's evolved tactical genome. Defaults to the neutral genome
    /// (original behavior); the tournament calls this per side so engine consumers
    /// can read team-specific style (the genome rides along on `WorldSnapshot`).
    pub fn set_team_tactical_genome(&mut self, team: Team, mut genome: SoccerTeamGenome) {
        genome.sanitize();
        match team {
            Team::Home => self.home_genome = genome,
            Team::Away => self.away_genome = genome,
        }
        // Optionally let the (now-installed) genome's per-player grid anchors drive
        // each player's field-position affinity — see the gate's doc comment. Off by
        // default ⇒ home positions stay the hard-coded formation (byte-identical).
        if dd_soccer_enable_genome_anchor_home_positions() {
            self.apply_genome_anchor_home_positions(team);
        }
    }

    /// Re-anchor `team`'s players' home positions from the (sanitized, 11-slot) genome
    /// anchors on the 12×24 grid, so the grid is the single source of each player's
    /// field-position affinity — especially WIDTH, since `lane` is x and the existing
    /// role lane band keys off `home_position.x`.
    ///
    /// Two passes give a 1:1 anchor↔player mapping for ANY formation (Fix D):
    /// 1. Within each role, match same-role players to anchors left→right by lane,
    ///    preserving the natural layout (leftmost defender ↔ leftmost defender anchor).
    /// 2. Reconcile a genome whose role split differs from the spawned lineup (e.g. an
    ///    F433 genome — 3 mid / 3 fwd — against a 4-4-2 lineup): each still-unfilled
    ///    anchor takes the NEAREST unassigned outfield player and re-roles it to that
    ///    anchor's role. The keeper is always 1:1 and never reassigned. The result's
    ///    role counts therefore equal the genome's, and every anchor maps to a player.
    ///
    /// Runs at match setup (before kickoff), so it snaps current position + history to
    /// the new home too, keeping the opening shape consistent with the anchors.
    fn apply_genome_anchor_home_positions(&mut self, team: Team) {
        use crate::des::general::soccer_genome::GenomeRole;
        use std::cmp::Ordering::Equal;
        let width = self.config.field_width_yards;
        let length = self.config.field_length_yards;
        let anchors = match team {
            Team::Home => self.home_genome.anchors.clone(),
            Team::Away => self.away_genome.anchors.clone(),
        };
        let role_of = |role: GenomeRole| match role {
            GenomeRole::Goalkeeper => PlayerRole::Goalkeeper,
            GenomeRole::Defender => PlayerRole::Defender,
            GenomeRole::Midfielder => PlayerRole::Midfielder,
            GenomeRole::Forward => PlayerRole::Forward,
        };
        // Resolve each anchor to its (role, target home position) once.
        let targets: Vec<(PlayerRole, Vec2)> = anchors
            .iter()
            .map(|a| {
                (
                    role_of(a.role),
                    genome_anchor_home_position(a.lane, a.row, team, width, length),
                )
            })
            .collect();

        let mut assigned = vec![false; self.players.len()];
        let mut leftover_targets: Vec<(PlayerRole, Vec2)> = Vec::new();

        // Pass 1: same-role match, left→right by lane (target) / current home x (player).
        for role in [
            PlayerRole::Goalkeeper,
            PlayerRole::Defender,
            PlayerRole::Midfielder,
            PlayerRole::Forward,
        ] {
            let mut role_targets: Vec<Vec2> = targets
                .iter()
                .filter(|(r, _)| *r == role)
                .map(|(_, p)| *p)
                .collect();
            role_targets.sort_by(|a, b| a.x.partial_cmp(&b.x).unwrap_or(Equal));
            let mut role_players: Vec<usize> = self
                .players
                .iter()
                .enumerate()
                .filter(|(_, p)| p.team == team && p.role == role)
                .map(|(i, _)| i)
                .collect();
            role_players.sort_by(|&a, &b| {
                self.players[a]
                    .home_position
                    .x
                    .partial_cmp(&self.players[b].home_position.x)
                    .unwrap_or(Equal)
            });
            let shared = role_targets.len().min(role_players.len());
            for k in 0..shared {
                let pi = role_players[k];
                self.snap_player_home(pi, role_targets[k]);
                assigned[pi] = true;
            }
            for &target in role_targets.iter().skip(shared) {
                leftover_targets.push((role, target));
            }
        }

        // Pass 2: reconcile formation-shape differences (Fix D) — give each unfilled
        // anchor the nearest unassigned outfield player and re-role it.
        for (target_role, target_pos) in leftover_targets {
            let pick = self
                .players
                .iter()
                .enumerate()
                .filter(|(i, p)| {
                    !assigned[*i] && p.team == team && p.role != PlayerRole::Goalkeeper
                })
                .min_by(|(_, a), (_, b)| {
                    a.home_position
                        .distance(target_pos)
                        .partial_cmp(&b.home_position.distance(target_pos))
                        .unwrap_or(Equal)
                })
                .map(|(i, _)| i);
            if let Some(pi) = pick {
                self.players[pi].role = target_role;
                self.snap_player_home(pi, target_pos);
                assigned[pi] = true;
            }
        }
    }

    /// Snap a player to a new home: the affinity anchor plus the current position and
    /// history (so a setup-time re-anchor starts the player on its new home).
    fn snap_player_home(&mut self, player_index: usize, home: Vec2) {
        let player = &mut self.players[player_index];
        player.home_position = home;
        player.position = home;
        player.position_history = VecDeque::from([home]);
    }

    pub fn set_team_neural_brain(
        &mut self,
        team: Team,
        snapshot: Option<SoccerNeuralNetworkSnapshot>,
        frozen: bool,
    ) -> Result<(), String> {
        if frozen && snapshot.is_none() {
            // A frozen, net-less side is the pure analytic opponent/baseline.
            // Under neural-authoritative serving a fresh random learner would otherwise
            // own decisions, which corrupts the very parity signal the climb gates measure.
            self.disable_team_neural_brain(team);
            return Ok(());
        }
        if !self.config.neural_learning.enabled {
            // Neural inference disabled for this match: nothing to install.
            match team {
                Team::Home => self.neural_learner = None,
                Team::Away => self.away_neural_learner = None,
            }
            match team {
                Team::Home => self.policy_head = None,
                Team::Away => self.away_policy_head = None,
            }
            match team {
                Team::Home => self.skill_policy_heads = None,
                Team::Away => self.away_skill_policy_heads = None,
            }
            return Ok(());
        }
        let mut restored_skill_policy_heads = None;
        let mut restored_central_critic_head = None;
        // Reinstalling a team brain is replacement, not overlay: a checkpoint without an actor
        // must not silently inherit that team's previously installed actor.
        match team {
            Team::Home => self.policy_head = None,
            Team::Away => self.away_policy_head = None,
        }
        let learner = match snapshot {
            Some(snapshot) => {
                let network = build_soccer_neural_network_from_snapshot(&snapshot)?;
                // Restore the actor into the deciding TEAM's sidecar. This prevents an away
                // champion from overwriting and then driving the home actor in self-play.
                if let Some(policy_head_snapshot) = snapshot.policy_head.as_deref() {
                    let restored =
                        soccer_policy_head_from_snapshot(policy_head_snapshot, self.config.seed)?;
                    match team {
                        Team::Home => self.policy_head = Some(restored),
                        Team::Away => self.away_policy_head = Some(restored),
                    }
                }
                restored_central_critic_head = snapshot
                    .central_critic_head
                    .as_deref()
                    .map(SoccerCentralCriticHead::from_snapshot)
                    .transpose()?;
                if let Some(keeper_policy_head_snapshot) = snapshot.keeper_policy_head.as_deref() {
                    self.keeper_policy_head = Some(soccer_keeper_policy_head_from_snapshot(
                        keeper_policy_head_snapshot,
                        self.config.seed,
                    )?);
                }
                self.restore_auxiliary_heads_for(team, &snapshot)?;
                restored_skill_policy_heads = if let Some(skill_policy_heads_snapshot) =
                    snapshot.skill_policy_heads.as_deref()
                {
                    Some(soccer_skill_policy_heads_from_snapshot(
                        skill_policy_heads_snapshot,
                        self.config.seed,
                    )?)
                } else {
                    None
                };
                // Symmetric with `set_neural_network_snapshot`: install the serialized EXECUTION /
                // auxiliary heads so frozen-eval brains loaded via THIS setter (tournaments / eval
                // gate / soccer_proof) actually APPLY the trained mpc-objective aim, pass-completion,
                // attack-spacing and support-scorer — not just the critic. Without this the heads
                // are dropped at eval and head-ON/OFF is byte-identical. Never clears an existing
                // head when the snapshot lacks one.
                if let Some(pass_completion_head) = snapshot.pass_completion_head.as_deref() {
                    self.pass_completion_head = Some(std::sync::Arc::new(
                        SoccerPassCompletionHead::from_snapshot(pass_completion_head)?,
                    ));
                }
                if let Some(mpc_objective_head) = snapshot.mpc_objective_head.as_deref() {
                    self.mpc_objective_head = Some(std::sync::Arc::new(
                        SoccerMpcObjectiveHead::from_snapshot(mpc_objective_head)?,
                    ));
                }
                if let Some(attack_spacing_head) = snapshot.attack_spacing_head.as_deref() {
                    self.attack_spacing_head = Some(std::sync::Arc::new(
                        AttackSpacingHead::from_snapshot(attack_spacing_head)?,
                    ));
                }
                if let Some(support_scorer_head) = snapshot.support_scorer_head.as_deref() {
                    self.support_scorer_head = Some(std::sync::Arc::new(
                        SupportScorerHead::from_snapshot(support_scorer_head)?,
                    ));
                }
                SoccerNeuralLearner::from_pretrained_snapshot(&self.config, network, &snapshot)
            }
            None if self.config.learning_enabled => {
                self.clear_auxiliary_heads_for(team);
                SoccerNeuralLearner::new(&self.config)
            }
            None => {
                match team {
                    Team::Home => {
                        self.neural_learner = None;
                        self.policy_head = None;
                        self.central_critic_head = None;
                        self.skill_policy_heads = None;
                        self.clear_auxiliary_heads_for(Team::Home);
                    }
                    Team::Away => {
                        self.away_neural_learner = None;
                        self.away_policy_head = None;
                        self.away_central_critic_head = None;
                        self.away_skill_policy_heads = None;
                        self.clear_auxiliary_heads_for(Team::Away);
                    }
                }
                return Ok(());
            }
        };
        match team {
            Team::Home => {
                self.neural_learner = Some(learner);
                self.home_neural_frozen = frozen;
                self.central_critic_head = restored_central_critic_head;
                self.skill_policy_heads = restored_skill_policy_heads;
            }
            Team::Away => {
                self.away_neural_learner = Some(learner);
                self.away_neural_frozen = frozen;
                self.away_central_critic_head = restored_central_critic_head;
                self.away_skill_policy_heads = restored_skill_policy_heads;
            }
        }
        if !frozen && dd_soccer_enable_skill_policy_heads() {
            self.ensure_skill_policy_heads_for_training(team);
        }
        Ok(())
    }

    /// Explicitly keep a team on the analytic decision stack. For Away this also
    /// suppresses the shared-home neural fallback used by legacy single-net runs.
    pub fn disable_team_neural_brain(&mut self, team: Team) {
        match team {
            Team::Home => {
                self.neural_learner = None;
                self.home_neural_frozen = true;
                self.policy_head = None;
                self.central_critic_head = None;
                self.skill_policy_heads = None;
                self.clear_auxiliary_heads_for(Team::Home);
            }
            Team::Away => {
                self.away_neural_learner = None;
                self.away_neural_frozen = true;
                self.away_policy_head = None;
                self.away_central_critic_head = None;
                self.away_skill_policy_heads = None;
                self.clear_auxiliary_heads_for(Team::Away);
            }
        }
    }

    pub fn set_team_policies(&mut self, team_policies: SoccerTeamQPolicies) {
        self.team_policies = Some(team_policies);
    }

    pub fn clear_team_policies(&mut self) {
        self.team_policies = None;
    }

    pub fn team_policies(&self) -> Option<&SoccerTeamQPolicies> {
        self.team_policies.as_ref()
    }

    pub fn team_policies_mut(&mut self) -> Option<&mut SoccerTeamQPolicies> {
        self.team_policies.as_mut()
    }

    fn sanitized_adversarial_moment_memory_limit(&self) -> usize {
        self.config
            .adversarial_embedding_memory_limit
            .min(MAX_ADVERSARIAL_MOMENT_MEMORY_LIMIT)
    }

    pub fn adversarial_moment_memory_len(&self) -> usize {
        self.adversarial_moment_memory.len()
    }

    pub fn remember_adversarial_moment_window(&mut self, window: SoccerMomentWindow) {
        if !self.config.adversarial_embedding_exploitation_enabled {
            return;
        }
        let limit = self.sanitized_adversarial_moment_memory_limit();
        let moment_id = window.summary.id.trim();
        if limit == 0 || window.feature_vector.is_empty() {
            return;
        }
        if moment_id.is_empty() {
            return;
        }
        if window.embedder_version != SOCCER_MOMENT_EMBEDDER_VERSION
            || !soccer_moment_feature_vector_is_valid(&window.feature_vector)
        {
            return;
        }
        self.adversarial_moment_memory
            .retain(|existing| existing.summary.id.trim() != moment_id);
        self.adversarial_moment_memory.push_back(window);
        while self.adversarial_moment_memory.len() > limit {
            self.adversarial_moment_memory.pop_front();
        }
        *self.adversarial_moment_index_cache.get_mut() = None;
        *self.adversarial_embedding_signal_cache.get_mut() = None;
        self.retrieved_action_prior_cache.get_mut().clear();
    }

    fn remember_adversarial_moment_records(&mut self, records: &[SoccerMomentStorageRecord]) {
        for record in records {
            self.remember_adversarial_moment_window(record.window.clone());
        }
    }

    fn adversarial_embedding_exploitation_active(&self) -> bool {
        // Exploiting a retrieved moment corpus to bias decisions is a DECISION-time
        // feature, gated by its own flag — it is independent of online TRAINING
        // (`learning_enabled`), so a live game running a frozen snapshot still uses it.
        self.config.adversarial_embedding_exploitation_enabled
            && self.sanitized_adversarial_moment_memory_limit() > 0
            && !self.adversarial_moment_memory.is_empty()
    }

    fn learned_policy_inference_enabled(&self) -> bool {
        self.config.learning_enabled
            || self.team_policies.is_some()
            || self.learned_policy.is_some()
    }

    fn learned_policy_inference_enabled_for_team(&self, team: Team) -> bool {
        if self.neural_team_frozen(team) && self.neural_learner_for(team).is_none() {
            return false;
        }
        self.learned_policy_inference_enabled()
    }

    fn neural_blend_readiness_for_learner(&self, learner: &SoccerNeuralLearner) -> f64 {
        let readiness = self
            .neural_blend
            .readiness(learner.training_steps(), learner.average_loss());
        if readiness > 0.0 {
            return readiness;
        }
        if !self.config.learning_enabled && learner.has_prediction_network() {
            1.0
        } else {
            0.0
        }
    }

    fn neural_blend_lambda_for_learner(&self, learner: &SoccerNeuralLearner) -> f64 {
        // NEURAL-AUTHORITATIVE experiment: when DD_SOCCER_NEURAL_AUTHORITATIVE_LAMBDA > 0, the
        // neural value head OWNS the per-player action decision. Return a large fixed weight so
        // `candidate.value + λ·V_net` is dominated by V_net (the coarse tabular Q becomes a
        // negligible tie-break floor), bypassing the 0.5 nudge AND the warm-up ramp. Requires a
        // usable prediction network so a net-less run still falls back to tabular.
        let authoritative = dd_soccer_neural_authoritative_lambda();
        if authoritative > 0.0 && learner.has_prediction_network() {
            return authoritative;
        }
        if !self.neural_blend.lambda.is_finite() || self.neural_blend.lambda <= 0.0 {
            return 0.0;
        }
        self.neural_blend.lambda * self.neural_blend_readiness_for_learner(learner)
    }

    fn with_adversarial_moment_index<R>(
        &self,
        f: impl FnOnce(&SoccerMomentVectorIndex) -> R,
    ) -> Option<R> {
        if !self.adversarial_embedding_exploitation_active() {
            *self.adversarial_moment_index_cache.borrow_mut() = None;
            return None;
        }
        let mut cache = self.adversarial_moment_index_cache.borrow_mut();
        if cache.is_none() {
            *cache = Some(SoccerMomentVectorIndex::from_window_iter(
                self.adversarial_moment_memory.iter(),
            ));
        }
        let index = cache.as_ref()?;
        if index.status().entries == 0 {
            return None;
        }
        Some(f(index))
    }

    fn adversarial_embedding_signals(&self) -> Option<SoccerAdversarialEmbeddingSignals> {
        if !self.adversarial_embedding_exploitation_active() {
            *self.adversarial_embedding_signal_cache.borrow_mut() = None;
            return None;
        }

        if let Some(cached) = *self.adversarial_embedding_signal_cache.borrow() {
            if self.tick.saturating_sub(cached.tick) < ADVERSARIAL_EMBEDDING_SIGNAL_REFRESH_TICKS {
                return cached.signals;
            }
        }

        let computed = self
            .with_adversarial_moment_index(|index| {
                let frame = tracking_frame_from_match(self);
                let mut signals = SoccerAdversarialEmbeddingSignals::default();
                for perspective_team in [Team::Home, Team::Away] {
                    let feature_vector = soccer_moment_feature_vector(
                        std::slice::from_ref(&frame),
                        perspective_team,
                        &self.config,
                    );
                    if feature_vector.is_empty() {
                        continue;
                    }
                    let bucket = soccer_moment_bucket_key(
                        "current_shape",
                        perspective_team,
                        &frame,
                        &self.config,
                    );
                    let response = index.search(&SoccerMomentIndexSearchRequest {
                        bucket,
                        feature_vector,
                        limit: ADVERSARIAL_EMBEDDING_SEARCH_LIMIT,
                        max_candidates: ADVERSARIAL_EMBEDDING_MAX_CANDIDATES
                            .min(self.adversarial_moment_memory.len().max(1)),
                        bucket_radius: ADVERSARIAL_EMBEDDING_BUCKET_RADIUS,
                        same_label_only: false,
                    });
                    for hit in response.results {
                        if hit.score < ADVERSARIAL_EMBEDDING_MIN_SCORE {
                            continue;
                        }
                        let score = ((hit.score - ADVERSARIAL_EMBEDDING_MIN_SCORE)
                            / (1.0 - ADVERSARIAL_EMBEDDING_MIN_SCORE))
                            .clamp(0.0, 1.0) as f64;
                        let contribution =
                            score * soccer_moment_adversarial_label_weight(&hit.summary.label);
                        if contribution <= 1e-9 {
                            continue;
                        }

                        let attack_signal = signals.signal_for_mut(perspective_team);
                        attack_signal.attack_score =
                            (attack_signal.attack_score + contribution).clamp(0.0, 1.0);
                        attack_signal.hits = attack_signal.hits.saturating_add(1);

                        let defense_signal = signals.signal_for_mut(perspective_team.other());
                        defense_signal.defense_score =
                            (defense_signal.defense_score + contribution).clamp(0.0, 1.0);
                        defense_signal.hits = defense_signal.hits.saturating_add(1);
                    }
                }

                if signals.home.hits == 0 && signals.away.hits == 0 {
                    None
                } else {
                    Some(signals)
                }
            })
            .flatten();

        *self.adversarial_embedding_signal_cache.borrow_mut() =
            Some(CachedAdversarialEmbeddingSignals {
                tick: self.tick,
                signals: computed,
            });
        computed
    }

    fn compute_retrieved_action_priors_for_team(&self, team: Team) -> Option<HashMap<String, f64>> {
        self.with_adversarial_moment_index(|index| {
            let frame = tracking_frame_from_match(self);
            let feature_vector =
                soccer_moment_feature_vector(std::slice::from_ref(&frame), team, &self.config);
            if feature_vector.is_empty() {
                return None;
            }
            let bucket = soccer_moment_bucket_key("current_shape", team, &frame, &self.config);
            let response = index.search(&SoccerMomentIndexSearchRequest {
                bucket,
                feature_vector,
                limit: ADVERSARIAL_EMBEDDING_ACTION_PRIOR_SEARCH_LIMIT,
                max_candidates: ADVERSARIAL_EMBEDDING_ACTION_PRIOR_MAX_CANDIDATES
                    .min(self.adversarial_moment_memory.len().max(1)),
                bucket_radius: ADVERSARIAL_EMBEDDING_BUCKET_RADIUS,
                same_label_only: false,
            });
            let mut weighted: HashMap<String, (f64, f64)> = HashMap::new();
            for hit in response.results {
                if hit.score < ADVERSARIAL_EMBEDDING_MIN_SCORE {
                    continue;
                }
                let similarity = ((hit.score - ADVERSARIAL_EMBEDDING_MIN_SCORE)
                    / (1.0 - ADVERSARIAL_EMBEDDING_MIN_SCORE))
                    .clamp(0.0, 1.0) as f64;
                if similarity <= 1e-9 {
                    continue;
                }
                let Some(window) = self
                    .adversarial_moment_memory
                    .iter()
                    .find(|window| window.summary.id == hit.summary.id)
                else {
                    continue;
                };
                for marker in &window.actions {
                    let action = normalize_soccer_action_label(&marker.action).to_string();
                    if action.is_empty() {
                        continue;
                    }
                    if !marker.reward.is_finite() {
                        continue;
                    }
                    let outcome =
                        (marker.reward / SOCCER_MOMENT_REPLAY_SHOT_REWARD).clamp(-1.0, 1.0);
                    let entry = weighted.entry(action).or_insert((0.0, 0.0));
                    entry.0 += similarity * outcome;
                    entry.1 += similarity;
                }
            }

            let priors = weighted
                .into_iter()
                .filter_map(|(action, (sum, weight))| {
                    (weight > 1e-9)
                        .then_some((action, (sum / weight) * SOCCER_RETRIEVAL_ACTION_PRIOR_SCALE))
                })
                .collect::<HashMap<_, _>>();
            (!priors.is_empty()).then_some(priors)
        })
        .flatten()
    }

    fn retrieved_action_priors_for_team(&self, team: Team) -> Option<HashMap<String, f64>> {
        if !self.adversarial_embedding_exploitation_active() {
            self.retrieved_action_prior_cache.borrow_mut().clear();
            return None;
        }

        let tick = self.tick;
        if let Some(priors) = {
            let mut cache = self.retrieved_action_prior_cache.borrow_mut();
            cache.reset_for_tick(tick);
            cache.slot(team).get()
        } {
            return priors;
        }

        let priors = self.compute_retrieved_action_priors_for_team(team);
        {
            let mut cache = self.retrieved_action_prior_cache.borrow_mut();
            cache.reset_for_tick(tick);
            cache.slot_mut(team).store(priors.clone());
        }
        priors
    }

    /// NN → LP coupling. Scores each team's most-recent transition with the
    /// gradient-trained critic and squashes the value into an attack/defense
    /// contribution. A positive critic value for a team's latest action-in-
    /// state means that team is well placed: it nudges *that* team's attack
    /// embedding up and the opponent's defense embedding up. The contribution
    /// is capped at [`SOCCER_NEURAL_LP_SIGNAL_CAP`] so a half-trained or noisy
    /// net can only ever apply a small, bounded bias to the whole-field LP.
    pub(crate) fn neural_lp_embedding_signals(&self) -> Option<SoccerAdversarialEmbeddingSignals> {
        if !self.config.neural_learning.enabled || !self.config.neural_learning.lp_coupling_enabled
        {
            return None;
        }
        let target_scale = self.config.neural_learning.sanitized_target_scale();
        let mut signals = SoccerAdversarialEmbeddingSignals::default();
        let mut any = false;
        for team in [Team::Home, Team::Away] {
            // Each team is scored by its own brain (away falls back to the shared
            // net in single-net runs).
            let Some(learner) = self.neural_learner_for(team) else {
                continue;
            };
            let Some(transition) = self
                .episode_learning_transitions
                .iter()
                .rev()
                .find(|transition| transition.team == team)
            else {
                continue;
            };
            let features = soccer_neural_transition_features(transition);
            let Some(value) = learner.predict_value(&features) else {
                continue;
            };
            // Squash into (-1, 1) about the critic's natural target scale, then
            // keep only the positive (favourable) half and cap it.
            let squashed = (value / target_scale).tanh();
            let favourable = squashed.max(0.0) * SOCCER_NEURAL_LP_SIGNAL_CAP;
            if favourable <= 1e-9 {
                continue;
            }
            let attack = signals.signal_for_mut(team);
            attack.attack_score = (attack.attack_score + favourable).clamp(0.0, 1.0);
            attack.hits = attack.hits.saturating_add(1);
            let defense = signals.signal_for_mut(team.other());
            defense.defense_score = (defense.defense_score + favourable).clamp(0.0, 1.0);
            defense.hits = defense.hits.saturating_add(1);
            any = true;
        }
        any.then_some(signals)
    }

    pub fn set_coach_set_play_hint(&mut self, mut hint: SoccerSetPlayVectorHint) {
        if !hint.score.is_finite() {
            return;
        }
        let Some(restart) = canonical_set_play_restart_label(&hint.restart) else {
            return;
        };
        hint.restart = restart.to_string();
        self.coach_set_play_hints.insert(hint.team, hint);
    }

    pub fn clear_coach_set_play_hint(&mut self, team: Team) {
        self.coach_set_play_hints.remove(&team);
    }

    pub fn stage_set_play_restart(
        &mut self,
        restart: SoccerSetPlayRestartKind,
        team: Team,
        spot: Vec2,
    ) {
        let (field_width, field_length) = sane_pitch_dimensions(
            self.config.field_width_yards,
            self.config.field_length_yards,
        );
        let center = Vec2::new(field_width * 0.5, field_length * 0.5);
        let spot = finite_pitch_point(spot, field_width, field_length, center);
        if let Some(kind) = restart.ball_restart_kind() {
            self.apply_restart_with_label(kind, team, spot, restart.as_label());
            return;
        }

        let kickoff = self
            .players
            .iter()
            .filter(|player| player.team == team)
            .min_by(|a, b| {
                a.position
                    .distance(center)
                    .partial_cmp(&b.position.distance(center))
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|player| player.id);
        self.arrange_kickoff_shape(team, kickoff, center);
        self.activate_set_play_for_restart(restart.as_label(), None, team, center, kickoff);
        self.ball.position = center;
        self.ball.velocity = Vec2::zero();
        self.ball.acceleration = Vec2::zero();
        self.ball.jerk = Vec2::zero();
        self.ball.curl_acceleration = Vec2::zero();
        self.ball.altitude_yards = 0.0;
        self.ball.holder = kickoff;
        self.ball.last_touch_team = Some(team);
        self.finish_possession_progress_chain(false);
        self.possession_chain.clear();
        self.possession_chain_previous_touch_team = None;
        self.completed_pass_chain.clear();
        if let Some(holder_id) = kickoff {
            self.mark_ball_received(holder_id);
            self.record_possession_touch(holder_id);
            // The kickoff taker may not touch the ball twice in a row: they must
            // play it to a teammate (held-restart release) before touching again.
            // Set AFTER record_possession_touch, which would otherwise clear it.
            self.restart_double_touch_guard = Some(holder_id);
        }
        self.ball.record_decision(self.tick, "kickoff", None);
        self.pending_pass = None;
        self.pending_shot = None;
        self.shared_positions.sync_from_players_and_ball(
            &self.players,
            &self.officials,
            &self.ball,
            self.tick,
            self.clock_seconds,
        );
        let taker = kickoff
            .and_then(|id| self.players.iter().find(|player| player.id == id))
            .map(|player| player.name.as_str())
            .unwrap_or("Kickoff");
        self.events.push(MatchEvent {
            tick: self.tick,
            clock_seconds: self.clock_seconds,
            kind: "kickoff".to_string(),
            team: Some(team),
            player_id: kickoff,
            description: format!("{taker} kickoff for {}", team.label()),
            ..MatchEvent::default()
        });
    }

    /// Read-only world snapshot for external tooling (possession-chain / EPV export).
    /// Constructs the same agent-decision snapshot the engine uses internally; pure read,
    /// no mutation, so calling it is byte-identical to not calling it. Off any hot path.
    pub fn export_world_snapshot(&self) -> WorldSnapshot {
        WorldSnapshot::from_match_for_agent_decision(self)
    }

    pub fn summary(&self) -> MatchSummary {
        // Include the still-open consecutive-pass chain (if any) so the final sequence of the
        // match is counted, without mutating live state — `summary` is a read-only view.
        let mut stats = self.stats.clone();
        stats.fold_pass_chain(&self.pass_chain_meter);
        MatchSummary {
            score_home: self.score_home,
            score_away: self.score_away,
            ticks: self.tick,
            simulated_seconds: self.clock_seconds,
            stats,
        }
    }

    pub fn match_clock(&self) -> SoccerMatchClock {
        let total_ticks = self.config.total_ticks();
        let total_seconds = self.config.effective_duration_seconds().max(0.0);
        let elapsed_seconds = self
            .clock_seconds
            .clamp(0.0, total_seconds.max(self.clock_seconds));
        let remaining_ticks = total_ticks.saturating_sub(self.tick);
        let remaining_seconds = (total_seconds - elapsed_seconds).max(0.0);
        let progress = if total_ticks > 0 {
            (self.tick as f64 / total_ticks as f64).clamp(0.0, 1.0)
        } else if total_seconds > 0.0 {
            (elapsed_seconds / total_seconds).clamp(0.0, 1.0)
        } else {
            1.0
        };
        SoccerMatchClock {
            tick: self.tick,
            total_ticks,
            dt_seconds: self.config.dt_seconds,
            elapsed_seconds,
            total_seconds,
            remaining_ticks,
            remaining_seconds,
            progress,
            done: self.is_done(),
        }
    }

    pub fn drain_neural_learning(&mut self, max_wait: Duration) {
        if let Some(learner) = &mut self.neural_learner {
            learner.drain_results_until_idle(max_wait);
        }
        if let Some(learner) = &mut self.away_neural_learner {
            learner.drain_results_until_idle(max_wait);
        }
    }

    pub fn learning_snapshot(&self) -> SoccerLearningSnapshot {
        self.learning_snapshot_with_neural_network(true)
    }

    pub fn learning_stats_snapshot(&self) -> SoccerLearningSnapshot {
        self.learning_snapshot_with_neural_network(false)
    }

    fn learning_snapshot_with_neural_network(
        &self,
        include_neural_network: bool,
    ) -> SoccerLearningSnapshot {
        let (
            shared_policy_entries,
            shared_policy_visits,
            shared_policy_target_entries,
            shared_policy_target_visits,
        ) = self
            .learned_policy
            .as_ref()
            .map(|policy| {
                (
                    policy.q_values.len(),
                    policy.visit_count(),
                    policy.target_values.len(),
                    policy.target_visit_count(),
                )
            })
            .unwrap_or((0, 0, 0, 0));
        let (
            home_policy_entries,
            home_policy_visits,
            home_policy_target_entries,
            home_policy_target_visits,
            away_policy_entries,
            away_policy_visits,
            away_policy_target_entries,
            away_policy_target_visits,
        ) = self
            .team_policies
            .as_ref()
            .map(|policies| {
                (
                    policies.home.q_values.len(),
                    policies.home.visit_count(),
                    policies.home.target_values.len(),
                    policies.home.target_visit_count(),
                    policies.away.q_values.len(),
                    policies.away.visit_count(),
                    policies.away.target_values.len(),
                    policies.away.target_visit_count(),
                )
            })
            .unwrap_or((0, 0, 0, 0, 0, 0, 0, 0));
        let neural_stats = self.neural_learner.as_ref().map(|learner| &learner.stats);

        SoccerLearningSnapshot {
            total_transitions: self.learning_transitions.len(),
            learning_enabled: self.config.learning_enabled,
            learning_logging_enabled: self.config.learning_logging_enabled,
            learning_interval_ticks: self.config.learning_interval_ticks.max(1),
            policy_train_max_transitions_per_tick: self
                .config
                .policy_train_max_transitions_per_tick,
            deferred_reward_transitions: self.deferred_reward_transitions.len(),
            full_game_learning_enabled: self.config.full_game_learning_enabled,
            full_game_learning_applied: self.full_game_learning_applied,
            full_game_learning_episode_transitions: self.episode_learning_transitions.len(),
            full_game_learning_replay_transitions: self.full_game_learning_replay_transitions,
            shared_policy_enabled: self.learned_policy.is_some(),
            shared_policy_entries,
            shared_policy_visits,
            shared_policy_target_entries,
            shared_policy_target_visits,
            team_policies_enabled: self.team_policies.is_some(),
            adversarial_learning_enabled: self.config.learning_enabled
                && self.team_policies.is_some(),
            adversarial_embedding_exploitation_enabled: self.config.learning_enabled
                && self.config.adversarial_embedding_exploitation_enabled,
            adversarial_embedding_memory_size: self.adversarial_moment_memory.len(),
            home_policy_entries,
            home_policy_visits,
            home_policy_target_entries,
            home_policy_target_visits,
            away_policy_entries,
            away_policy_visits,
            away_policy_target_entries,
            away_policy_target_visits,
            neural_learning_enabled: self.config.learning_enabled
                && self.config.neural_learning.enabled,
            neural_learning_backend: self.config.neural_learning.backend.as_str().to_string(),
            neural_learning_training_steps: neural_stats
                .map(|stats| stats.training_steps)
                .unwrap_or(0),
            neural_learning_samples: neural_stats.map(|stats| stats.samples).unwrap_or(0),
            neural_learning_pending_batches: neural_stats
                .map(|stats| stats.pending_batches)
                .unwrap_or(0),
            neural_learning_dropped_batches: neural_stats
                .map(|stats| stats.dropped_batches)
                .unwrap_or(0),
            neural_learning_replay_samples: neural_stats
                .map(|stats| stats.replay_samples)
                .unwrap_or(0),
            neural_learning_replay_capacity: neural_stats
                .map(|stats| stats.replay_capacity)
                .unwrap_or(0),
            neural_learning_parameter_count: neural_stats
                .map(|stats| stats.parameter_count)
                .unwrap_or(0),
            marl_learning_enabled: self.config.learning_enabled
                && self.config.neural_learning.marl_enabled(),
            marl_algorithm: self
                .config
                .neural_learning
                .marl_algorithm
                .as_str()
                .to_string(),
            marl_team_reward_weight: self
                .config
                .neural_learning
                .sanitized_marl_team_reward_weight(),
            marl_intermediate_reward_weight: self
                .config
                .neural_learning
                .sanitized_marl_intermediate_reward_weight(),
            mappo_enabled: self.config.learning_enabled
                && self.config.neural_learning.mappo_enabled()
                && self.neural_blend.actor_critic,
            mappo_clip_epsilon: self.config.neural_learning.sanitized_mappo_clip_epsilon(),
            mappo_team_reward_share: self
                .config
                .neural_learning
                .sanitized_mappo_team_reward_share(),
            neural_learning_target_clip: self.config.neural_learning.sanitized_target_clip(),
            neural_learning_snapshot_every_batches: self
                .config
                .neural_learning
                .sanitized_snapshot_every_batches(),
            neural_learning_last_loss: neural_stats.and_then(|stats| stats.last_loss),
            neural_learning_average_loss: neural_stats.and_then(|stats| stats.average_loss()),
            neural_network: if include_neural_network {
                self.neural_network_snapshot()
            } else {
                None
            },
        }
    }

    pub fn team_policy_artifact(&self) -> SoccerTeamPolicyArtifact {
        let (
            home_options,
            away_options,
            home_entries,
            home_target_entries,
            home_action_probabilities,
            away_entries,
            away_target_entries,
            away_action_probabilities,
        ) = if let Some(policies) = &self.team_policies {
            (
                Some(policies.home.options.clone()),
                Some(policies.away.options.clone()),
                policies.home.entries(),
                policies.home.target_entries(),
                policies.home.action_probability_summaries(
                    SOCCER_POLICY_PROBABILITY_STATE_LIMIT,
                    SOCCER_POLICY_PROBABILITY_ACTION_LIMIT,
                ),
                policies.away.entries(),
                policies.away.target_entries(),
                policies.away.action_probability_summaries(
                    SOCCER_POLICY_PROBABILITY_STATE_LIMIT,
                    SOCCER_POLICY_PROBABILITY_ACTION_LIMIT,
                ),
            )
        } else {
            (
                None,
                None,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
            )
        };

        SoccerTeamPolicyArtifact {
            config: self.config.clone(),
            summary: self.summary(),
            learning: self.learning_snapshot(),
            tactical_summary: self.tactical_summary.clone(),
            adversarial: self.team_policies.is_some(),
            home_options,
            away_options,
            home_entries,
            home_target_entries,
            home_action_probabilities,
            away_entries,
            away_target_entries,
            away_action_probabilities,
            events: self.events.clone(),
        }
    }

    pub fn team_policy_probability_summary(&self) -> SoccerPolicyProbabilitySummaryStatus {
        let Some(policies) = &self.team_policies else {
            return SoccerPolicyProbabilitySummaryStatus::default();
        };
        let home = policies.home.action_probability_summaries(
            SOCCER_POLICY_PROBABILITY_STATE_LIMIT,
            SOCCER_POLICY_PROBABILITY_ACTION_LIMIT,
        );
        let away = policies.away.action_probability_summaries(
            SOCCER_POLICY_PROBABILITY_STATE_LIMIT,
            SOCCER_POLICY_PROBABILITY_ACTION_LIMIT,
        );
        SoccerPolicyProbabilitySummaryStatus {
            home_states: home.len(),
            home_actions: home.iter().map(|summary| summary.actions.len()).sum(),
            away_states: away.len(),
            away_actions: away.iter().map(|summary| summary.actions.len()).sum(),
            home_top_action: home.first().and_then(|summary| summary.best_action.clone()),
            away_top_action: away.first().and_then(|summary| summary.best_action.clone()),
        }
    }

    pub fn team_policy_artifact_for_disk_request(
        &self,
        request: Option<&SoccerTeamPolicyDiskRequest>,
    ) -> SoccerTeamPolicyArtifact {
        let mut artifact = self.team_policy_artifact();
        let Some(request) = request.filter(|request| request.has_prune_limits()) else {
            return artifact;
        };
        let Some(mut policies) = self.team_policies.clone() else {
            return artifact;
        };

        policies.prune(
            request.max_action_entries_per_team,
            request.max_target_entries_per_team,
            request.min_visits,
        );

        artifact.home_options = Some(policies.home.options.clone());
        artifact.away_options = Some(policies.away.options.clone());
        artifact.home_entries = policies.home.entries();
        artifact.home_target_entries = policies.home.target_entries();
        artifact.home_action_probabilities = policies.home.action_probability_summaries(
            SOCCER_POLICY_PROBABILITY_STATE_LIMIT,
            SOCCER_POLICY_PROBABILITY_ACTION_LIMIT,
        );
        artifact.away_entries = policies.away.entries();
        artifact.away_target_entries = policies.away.target_entries();
        artifact.away_action_probabilities = policies.away.action_probability_summaries(
            SOCCER_POLICY_PROBABILITY_STATE_LIMIT,
            SOCCER_POLICY_PROBABILITY_ACTION_LIMIT,
        );
        artifact.learning.home_policy_entries = artifact.home_entries.len();
        artifact.learning.home_policy_visits = policies.home.visit_count();
        artifact.learning.home_policy_target_entries = artifact.home_target_entries.len();
        artifact.learning.home_policy_target_visits = policies.home.target_visit_count();
        artifact.learning.away_policy_entries = artifact.away_entries.len();
        artifact.learning.away_policy_visits = policies.away.visit_count();
        artifact.learning.away_policy_target_entries = artifact.away_target_entries.len();
        artifact.learning.away_policy_target_visits = policies.away.target_visit_count();
        artifact
    }

