    pub fn import_tracking_for_team_policy(
        &mut self,
        request: SoccerTrackingImportRequest,
    ) -> Result<SoccerTrackingImportResponse, String> {
        let source = if request.source.trim().is_empty() {
            "live-upload".to_string()
        } else {
            request.source.clone()
        };
        let format = tracking_import_format(&request);
        let tracking = match format.as_str() {
            "json" => soccer_tracking_dataset_from_json(&request.content),
            "jsonl" => {
                soccer_tracking_dataset_from_jsonl(&request.content, self.config.clone(), &source)
            }
            "csv" => {
                soccer_tracking_dataset_from_csv(&request.content, self.config.clone(), &source)
            }
            other => Err(format!("unsupported tracking import format {other}")),
        }?;
        let physics_smoke = soccer_tracking_physics_smoke_report(&tracking);
        if physics_smoke.violation_count > 0 && !request.allow_physics_warnings {
            let (
                imported_home_entries,
                imported_away_entries,
                imported_home_target_entries,
                imported_away_target_entries,
            ) = self
                .team_policies
                .as_ref()
                .map(|policies| {
                    (
                        policies.home.q_values.len(),
                        policies.away.q_values.len(),
                        policies.home.target_values.len(),
                        policies.away.target_values.len(),
                    )
                })
                .unwrap_or((0, 0, 0, 0));
            return Ok(SoccerTrackingImportResponse {
                learning: self.learning_stats_snapshot(),
                policy_probability: self.team_policy_probability_summary(),
                tracking_tactical_summary: SoccerTacticalLearningSummary::default(),
                source: tracking.source.clone(),
                format,
                frames: tracking.frames.len(),
                imported_transitions: 0,
                imported_home_entries,
                imported_away_entries,
                imported_home_target_entries,
                imported_away_target_entries,
                imported_neural_samples: 0,
                physics_smoke,
                training_skipped: true,
                physics_rejected: true,
                rejection_reason: Some(
                    "tracking physics warnings blocked policy training".to_string(),
                ),
            });
        }
        let dataset = tracking.to_learning_dataset()?;
        let tracking_tactical_summary =
            SoccerTacticalLearningSummary::from_transitions(&dataset.transitions);
        let (
            imported_home_entries,
            imported_away_entries,
            imported_home_target_entries,
            imported_away_target_entries,
        ) = {
            let policies = self
                .team_policies
                .get_or_insert_with(|| SoccerTeamQPolicies::new(SoccerQPolicyOptions::default()));
            policies.train_adversarial(&dataset.transitions);
            (
                policies.home.q_values.len(),
                policies.away.q_values.len(),
                policies.home.target_values.len(),
                policies.away.target_values.len(),
            )
        };
        let imported_neural_samples =
            if self.config.learning_enabled && self.config.neural_learning.enabled {
                let neural_samples = self.neural_training_samples_for(&dataset.transitions);
                let imported_neural_samples = neural_samples.len();
                self.train_neural_value_model(neural_samples);
                imported_neural_samples
            } else {
                0
            };
        let learning = self.learning_stats_snapshot();

        Ok(SoccerTrackingImportResponse {
            learning,
            policy_probability: self.team_policy_probability_summary(),
            tracking_tactical_summary,
            source: tracking.source.clone(),
            format,
            frames: tracking.frames.len(),
            imported_transitions: dataset.transitions.len(),
            imported_home_entries,
            imported_away_entries,
            imported_home_target_entries,
            imported_away_target_entries,
            imported_neural_samples,
            physics_smoke,
            training_skipped: false,
            physics_rejected: false,
            rejection_reason: None,
        })
    }

    pub fn import_moment_replay_records_for_team_policy(
        &mut self,
        source: String,
        raw_jsonl: &str,
        request: &SoccerMomentReplayImportRequest,
    ) -> Result<SoccerMomentReplayImportResponse, String> {
        let mut records = soccer_moment_records_from_jsonl(raw_jsonl)?;
        if request.limit > 0 && records.len() > request.limit {
            records = records.split_off(records.len() - request.limit);
        }
        let reward_scale = request
            .reward_scale
            .filter(|scale| scale.is_finite())
            .unwrap_or(1.0)
            .max(0.0);
        let replay_passes = request.passes.max(1);
        let dataset =
            soccer_moment_records_to_learning_dataset(&records, self.config.clone(), reward_scale)?;
        self.remember_adversarial_moment_records(&records);
        let policies = self
            .team_policies
            .get_or_insert_with(|| SoccerTeamQPolicies::new(SoccerQPolicyOptions::default()));
        for _ in 0..replay_passes {
            policies.train_adversarial(&dataset.transitions);
        }
        let imported_home_entries = policies.home.q_values.len();
        let imported_away_entries = policies.away.q_values.len();
        let imported_home_target_entries = policies.home.target_values.len();
        let imported_away_target_entries = policies.away.target_values.len();
        let learning = self.learning_stats_snapshot();

        Ok(SoccerMomentReplayImportResponse {
            learning,
            policy_probability: self.team_policy_probability_summary(),
            source,
            records: records.len(),
            imported_transitions: dataset.transitions.len(),
            replay_passes,
            reward_scale,
            imported_home_entries,
            imported_away_entries,
            imported_home_target_entries,
            imported_away_target_entries,
        })
    }

    pub fn is_done(&self) -> bool {
        self.tick >= self.config.total_ticks()
    }

    pub fn start_new_period(&mut self, period_number: usize, kickoff_team: Team) {
        let recovery_seconds = self.config.period_break_recovery_seconds.max(0.0);
        if recovery_seconds > 0.0 {
            for player in &mut self.players {
                let recovery =
                    MovementGait::Stand.fatigue_delta(player.skills.stamina, recovery_seconds);
                player.add_fatigue(recovery);
            }
        }
        self.events.push(MatchEvent {
            tick: self.tick,
            clock_seconds: self.clock_seconds,
            kind: "period-break".to_string(),
            team: None,
            player_id: None,
            description: format!("period {} complete", period_number.saturating_sub(1)),
            ..MatchEvent::default()
        });
        self.reset_after_goal(kickoff_team);
        self.events.push(MatchEvent {
            tick: self.tick,
            clock_seconds: self.clock_seconds,
            kind: "period-start".to_string(),
            team: Some(kickoff_team),
            player_id: self.ball.holder,
            description: format!(
                "period {period_number} kickoff for {}",
                kickoff_team.label()
            ),
            ..MatchEvent::default()
        });
    }

    pub fn controller_assignments(&self) -> Vec<ControllerAssignment> {
        let mut assignments = self
            .players
            .iter()
            .filter_map(|p| {
                p.controller_slot
                    .map(|controller_slot| ControllerAssignment {
                        controller_slot,
                        player_id: p.id,
                        player_name: p.name.clone(),
                        team: p.team,
                    })
            })
            .collect::<Vec<_>>();
        assignments.sort_by_key(|a| a.controller_slot);
        assignments
    }

    fn assigned_player_for_controller_slot(&self, controller_slot: usize) -> Option<usize> {
        self.players
            .iter()
            .find(|player| player.controller_slot == Some(controller_slot))
            .map(|player| player.id)
    }

    pub fn assign_controller_slot(
        &mut self,
        controller_slot: usize,
        player_id: Option<usize>,
    ) -> Result<bool, String> {
        let slot_count = self.config.human_slots();
        if controller_slot >= slot_count {
            let range = if slot_count == 0 {
                "no configured slots".to_string()
            } else {
                format!("configured slots 0..{}", slot_count - 1)
            };
            return Err(format!(
                "controller slot {controller_slot} is outside {range}"
            ));
        }

        let (target_idx, previous_target_slot) = if let Some(player_id) = player_id {
            let target_idx = self
                .players
                .iter()
                .position(|p| p.id == player_id)
                .ok_or_else(|| format!("player {player_id} does not exist"))?;
            (Some(target_idx), self.players[target_idx].controller_slot)
        } else {
            (None, None)
        };

        let current_slot_player = self.assigned_player_for_controller_slot(controller_slot);
        let changed = current_slot_player != player_id
            || previous_target_slot.is_some_and(|slot| slot != controller_slot);
        if !changed {
            return Ok(false);
        }

        for player in &mut self.players {
            if player.controller_slot == Some(controller_slot) {
                player.controller_slot = None;
            }
        }

        if let Some(target_idx) = target_idx {
            self.players[target_idx].controller_slot = Some(controller_slot);
        }
        self.human_inputs.clear_slot(controller_slot);
        self.latched_human_inputs.remove(&controller_slot);
        if let Some(previous_slot) = previous_target_slot.filter(|slot| *slot != controller_slot) {
            self.human_inputs.clear_slot(previous_slot);
            self.latched_human_inputs.remove(&previous_slot);
        }

        Ok(true)
    }

    pub fn clear_controller_assignments(&mut self) {
        for player in &mut self.players {
            player.controller_slot = None;
        }
        for controller_slot in 0..self.config.human_slots() {
            self.human_inputs.clear_slot(controller_slot);
        }
        self.latched_human_inputs.clear();
    }

    pub fn update_ball_surface(&mut self, request: SoccerBallSurfaceRequest) -> Result<(), String> {
        validate_ball_surface(
            request.ball_drag_per_tick,
            request.ball_air_resistance,
            request.ball_grass_resistance_yps2,
            request.ball_stop_speed_yps,
        )?;
        self.config.ball_drag_per_tick = request.ball_drag_per_tick;
        self.config.ball_air_resistance = request.ball_air_resistance;
        self.config.ball_grass_resistance_yps2 = request.ball_grass_resistance_yps2;
        self.config.ball_stop_speed_yps = request.ball_stop_speed_yps;
        Ok(())
    }

    pub fn update_learning_runtime(
        &mut self,
        request: SoccerLearningRuntimeRequest,
    ) -> Result<SoccerLearningRuntimeResponse, String> {
        if let Some(enabled) = request.learning_enabled {
            if self.config.learning_enabled != enabled {
                self.retrieved_action_prior_cache.get_mut().clear();
            }
            self.config.learning_enabled = enabled;
            if !enabled {
                self.config.neural_learning.enabled = false;
                self.clear_all_neural_learners();
            }
        }
        if let Some(enabled) = request.learning_logging_enabled {
            self.config.learning_logging_enabled = enabled;
        }
        if let Some(interval) = request.learning_interval_ticks {
            if interval == 0 {
                return Err("learningIntervalTicks must be at least 1".to_string());
            }
            self.config.learning_interval_ticks = interval;
        }
        if let Some(max_transitions) = request.policy_train_max_transitions_per_tick {
            if max_transitions == 0 {
                return Err("policyTrainMaxTransitionsPerTick must be at least 1".to_string());
            }
            self.config.policy_train_max_transitions_per_tick = max_transitions;
        }
        if let Some(enabled) = request.neural_learning_enabled {
            self.config.neural_learning.enabled = enabled && self.config.learning_enabled;
            if !self.config.neural_learning.enabled {
                self.clear_all_neural_learners();
            }
        }
        if let Some(backend) = request.neural_learning_backend {
            if self.config.neural_learning.backend != backend {
                self.config.neural_learning.backend = backend;
                self.clear_all_neural_learners();
            }
        }
        Ok(SoccerLearningRuntimeResponse {
            config: self.config.clone(),
            learning: self.learning_stats_snapshot(),
        })
    }

    pub(crate) fn learned_action_for_player(
        &self,
        snapshot: &WorldSnapshot,
        player_id: usize,
    ) -> Option<SoccerLearnedPlan> {
        let mdp_state = snapshot.mdp_state_for_player(player_id);
        let observation = snapshot.observation_for(player_id);
        self.learned_action_for_player_with_context(snapshot, player_id, &mdp_state, &observation)
            .map(|decision| decision.plan)
    }

    fn policy_rank_selection_draw(
        &self,
        snapshot: &WorldSnapshot,
        player_id: usize,
        salt: u64,
    ) -> f64 {
        soccer_policy_rank_draw(self.config.seed, snapshot.tick, player_id, salt)
    }

    fn weighted_ranked_action_choice(
        ranked: &[SoccerLearnedActionTrace],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        let candidate_count = ranked
            .iter()
            .filter(|action| action.legal)
            .take(POLICY_SELECTION_TOP_RANK_LIMIT)
            .count();
        if candidate_count == 0 {
            return None;
        }
        let selected_rank = soccer_policy_weighted_rank_index(candidate_count, draw);
        ranked
            .iter()
            .filter(|action| action.legal)
            .nth(selected_rank)
            .map(|action| SoccerPolicyActionChoice {
                label: action.label.clone(),
                plan: None,
                behavior_probability: soccer_policy_rank_probability(
                    candidate_count,
                    selected_rank,
                ),
                neural_mcts_selected: false,
                neural_mcts_candidate_count: 0,
                neural_mcts_discretized_kick_candidate_count: 0,
                neural_mcts_root_discretized_kick_candidate_count: 0,
                neural_mcts_dribble_candidate_count: 0,
                neural_mcts_root_dribble_candidate_count: 0,
            })
    }

    fn weighted_replan_safe_ranked_action_choice(
        policy: &SoccerQPolicy,
        snapshot: &WorldSnapshot,
        player_id: usize,
        ranked: &[SoccerLearnedActionTrace],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        let candidates = ranked
            .iter()
            .filter(|action| action.legal)
            .filter_map(|action| {
                let plan = Self::learned_plan_for_policy(
                    policy,
                    snapshot,
                    player_id,
                    action.label.clone(),
                );
                Self::neural_mcts_candidate_plan_is_executable(snapshot, player_id, &plan)
                    .then_some((action, plan))
            })
            .take(POLICY_SELECTION_TOP_RANK_LIMIT)
            .collect::<Vec<_>>();
        let candidate_count = candidates.len();
        if candidate_count == 0 {
            return None;
        }
        let selected_rank = soccer_policy_weighted_rank_index(candidate_count, draw);
        candidates
            .get(selected_rank)
            .map(|(action, plan)| SoccerPolicyActionChoice {
                label: action.label.clone(),
                plan: Some(plan.clone()),
                behavior_probability: soccer_policy_rank_probability(
                    candidate_count,
                    selected_rank,
                ),
                neural_mcts_selected: false,
                neural_mcts_candidate_count: 0,
                neural_mcts_discretized_kick_candidate_count: 0,
                neural_mcts_root_discretized_kick_candidate_count: 0,
                neural_mcts_dribble_candidate_count: 0,
                neural_mcts_root_dribble_candidate_count: 0,
            })
    }

    fn weighted_scored_candidate_choice(
        candidates: &[SoccerNeuralMctsCandidate],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        let candidate_count = candidates.len().min(POLICY_SELECTION_TOP_RANK_LIMIT);
        if candidate_count == 0 {
            return None;
        }
        let selected_rank = soccer_policy_weighted_rank_index(candidate_count, draw);
        candidates.get(selected_rank).map(|candidate| {
            Self::scored_candidate_policy_choice(
                candidate,
                candidates,
                soccer_policy_rank_probability(candidate_count, selected_rank),
                false,
            )
        })
    }

    fn scored_candidate_counts(
        candidates: &[SoccerNeuralMctsCandidate],
    ) -> (u32, u32, u32, u32, u32) {
        let candidate_count = candidates.len().min(u32::MAX as usize) as u32;
        let discretized_kick_candidate_count = candidates
            .iter()
            .filter(|candidate| {
                learned_discretized_kick_speed_bucket_for_action_label(&candidate.label).is_some()
            })
            .count()
            .min(u32::MAX as usize) as u32;
        let dribble_candidate_count = candidates
            .iter()
            .filter(|candidate| is_dribble_action_label(&candidate.label))
            .count()
            .min(u32::MAX as usize) as u32;
        // Outside tree-search, every scored candidate is a root candidate.
        (
            candidate_count,
            discretized_kick_candidate_count,
            discretized_kick_candidate_count,
            dribble_candidate_count,
            dribble_candidate_count,
        )
    }

    fn scored_candidate_policy_choice(
        candidate: &SoccerNeuralMctsCandidate,
        candidates: &[SoccerNeuralMctsCandidate],
        behavior_probability: f64,
        neural_mcts_selected: bool,
    ) -> SoccerPolicyActionChoice {
        let (
            neural_mcts_candidate_count,
            neural_mcts_discretized_kick_candidate_count,
            neural_mcts_root_discretized_kick_candidate_count,
            neural_mcts_dribble_candidate_count,
            neural_mcts_root_dribble_candidate_count,
        ) = Self::scored_candidate_counts(candidates);
        SoccerPolicyActionChoice {
            label: candidate.label.clone(),
            plan: candidate.plan.clone(),
            behavior_probability,
            neural_mcts_selected,
            neural_mcts_candidate_count,
            neural_mcts_discretized_kick_candidate_count,
            neural_mcts_root_discretized_kick_candidate_count,
            neural_mcts_dribble_candidate_count,
            neural_mcts_root_dribble_candidate_count,
        }
    }

    fn top_scored_candidate_choice(
        candidates: &[SoccerNeuralMctsCandidate],
    ) -> Option<SoccerPolicyActionChoice> {
        candidates.first().map(|candidate| {
            Self::scored_candidate_policy_choice(candidate, candidates, 1.0, false)
        })
    }

    fn finishing_scored_candidate_floor_choice(
        candidates: &[SoccerNeuralMctsCandidate],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        Self::finishing_scored_candidate_floor_choice_with_boost(candidates, draw, 0.0)
    }

    fn finishing_scored_candidate_floor_choice_with_boost(
        candidates: &[SoccerNeuralMctsCandidate],
        draw: f64,
        floor_boost: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        let floor = neural_finishing_selection_effective_floor(floor_boost);
        if floor <= 1e-9 || !draw.is_finite() || draw >= floor {
            return None;
        }
        let candidate_count = candidates.len();
        if candidate_count == 0 {
            return None;
        }
        let best_score = candidates
            .iter()
            .map(|candidate| candidate.score)
            .fold(f64::NEG_INFINITY, f64::max);
        if !best_score.is_finite() {
            return None;
        }
        let max_regression = neural_finishing_selection_max_score_regression();
        if max_regression <= 0.0 || !max_regression.is_finite() {
            return None;
        }
        let rank_weights = soccer_policy_top_rank_weights();
        let tail_weight = rank_weights[POLICY_SELECTION_TOP_RANK_LIMIT - 1].max(1e-6);
        let mut eligible = Vec::new();
        let mut total = 0.0;
        for rank in 0..candidate_count {
            let candidate = &candidates[rank];
            if !candidate.score.is_finite() {
                continue;
            }
            let label = normalize_soccer_action_label(&candidate.label);
            if !matches!(label, "shoot" | "first-time-shot" | "first-time-header") {
                continue;
            }
            let prior = candidate.prior.max(0.0);
            let score_eligible = candidate.score + max_regression >= best_score;
            let quality_eligible = prior >= NEURAL_FINISHING_SELECTION_QUALITY_PRIOR_MIN;
            if !score_eligible && !quality_eligible {
                continue;
            }
            let raw_rank_weight = rank_weights.get(rank).copied().unwrap_or_else(|| {
                tail_weight * (POLICY_SELECTION_TOP_RANK_LIMIT as f64 / (rank + 1) as f64)
            });
            let rank_weight = raw_rank_weight.max(0.0).sqrt().max(0.02);
            let quality_weight = if quality_eligible {
                prior.clamp(0.0, 2.0).powi(3)
            } else {
                0.0
            };
            let score_weight = if score_eligible { 0.08 } else { 0.0 };
            let weight = (rank_weight * (quality_weight + score_weight)).max(0.0);
            if weight <= 0.0 {
                continue;
            }
            eligible.push((rank, weight));
            total += weight;
        }
        if eligible.is_empty() || !total.is_finite() || total <= 1e-9 {
            return None;
        }
        eligible.sort_by(|(left_rank, left_weight), (right_rank, right_weight)| {
            right_weight
                .total_cmp(left_weight)
                .then_with(|| left_rank.cmp(right_rank))
        });
        let mut threshold = (draw / floor).clamp(0.0, 1.0 - f64::EPSILON) * total;
        for (rank, weight) in eligible.iter().copied() {
            if threshold < weight {
                return candidates.get(rank).map(|candidate| {
                    let behavior_probability = (floor * weight / total).clamp(1e-6, 1.0);
                    Self::scored_candidate_policy_choice(
                        candidate,
                        candidates,
                        behavior_probability,
                        false,
                    )
                });
            }
            threshold -= weight;
        }
        let (rank, weight) = *eligible.last()?;
        candidates.get(rank).map(|candidate| {
            let behavior_probability = (floor * weight / total).clamp(1e-6, 1.0);
            Self::scored_candidate_policy_choice(candidate, candidates, behavior_probability, false)
        })
    }

    fn forward_creation_scored_candidate_floor_choice(
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        observation: &SoccerPomdpObservation,
        candidates: &[SoccerNeuralMctsCandidate],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        let floor = neural_forward_creation_selection_floor();
        if floor <= 1e-9 || !draw.is_finite() || draw >= floor {
            return None;
        }
        if observation.visible_forward_pass_options == 0 {
            return None;
        }
        let option_quality = observation
            .best_forward_pass_option_quality
            .max(observation.best_forward_pass_receiver_openness)
            .clamp(0.0, 1.0);
        let expected_completion = observation.expected_pass_completion.clamp(0.0, 1.0);
        if option_quality < neural_forward_creation_min_quality()
            || expected_completion < neural_forward_creation_min_completion()
        {
            return None;
        }
        if candidates.is_empty() {
            return None;
        }
        let best_score = candidates
            .iter()
            .map(|candidate| candidate.score)
            .fold(f64::NEG_INFINITY, f64::max);
        if !best_score.is_finite() {
            return None;
        }
        let max_regression = neural_forward_creation_selection_max_score_regression();
        if max_regression <= 0.0 || !max_regression.is_finite() {
            return None;
        }
        let min_forward_yards = neural_forward_creation_min_forward_yards();
        let state_quality = (option_quality * expected_completion).clamp(0.0, 1.0);
        let quality_bypass = option_quality >= neural_forward_creation_bypass_min_quality()
            && expected_completion >= neural_forward_creation_bypass_min_completion();
        let rank_weights = soccer_policy_top_rank_weights();
        let tail_weight = rank_weights[POLICY_SELECTION_TOP_RANK_LIMIT - 1].max(1e-6);
        let mut eligible = Vec::new();
        let mut total = 0.0;
        for (rank, candidate) in candidates.iter().enumerate() {
            if !candidate.score.is_finite()
                || !Self::soccer_candidate_is_forward_pass(snapshot, player_id, team, candidate)
            {
                continue;
            }
            let Some(plan) = candidate.plan.as_ref() else {
                continue;
            };
            let Some(forward_yards) =
                soccer_plan_target_forward_yards(plan, snapshot, player_id, team)
            else {
                continue;
            };
            if forward_yards < min_forward_yards {
                continue;
            }
            let score_delta = best_score - candidate.score;
            if !score_delta.is_finite() {
                continue;
            }
            let score_eligible = score_delta <= max_regression;
            if !score_eligible && !quality_bypass {
                continue;
            }
            let raw_rank_weight = rank_weights.get(rank).copied().unwrap_or_else(|| {
                tail_weight * (POLICY_SELECTION_TOP_RANK_LIMIT as f64 / (rank + 1) as f64)
            });
            let rank_weight = raw_rank_weight.max(0.0).sqrt().max(0.02);
            let score_fit = if score_eligible {
                (1.0 - score_delta.max(0.0) / max_regression).clamp(0.05, 1.0)
            } else {
                0.08
            };
            let gain_weight = (forward_yards / 18.0).clamp(0.35, 1.35);
            let prior_weight = 0.35 + candidate.prior.max(0.0).clamp(0.0, 1.5).sqrt();
            let weight = rank_weight * score_fit * gain_weight * prior_weight * state_quality;
            if weight <= 0.0 || !weight.is_finite() {
                continue;
            }
            eligible.push((rank, weight));
            total += weight;
        }
        if eligible.is_empty() || !total.is_finite() || total <= 1e-9 {
            return None;
        }
        eligible.sort_by(|(left_rank, left_weight), (right_rank, right_weight)| {
            right_weight
                .total_cmp(left_weight)
                .then_with(|| left_rank.cmp(right_rank))
        });
        let mut threshold = (draw / floor).clamp(0.0, 1.0 - f64::EPSILON) * total;
        for (rank, weight) in eligible.iter().copied() {
            if threshold < weight {
                return candidates.get(rank).map(|candidate| {
                    let behavior_probability = (floor * weight / total).clamp(1e-6, 1.0);
                    Self::scored_candidate_policy_choice(
                        candidate,
                        candidates,
                        behavior_probability,
                        false,
                    )
                });
            }
            threshold -= weight;
        }
        let (rank, weight) = *eligible.last()?;
        candidates.get(rank).map(|candidate| {
            let behavior_probability = (floor * weight / total).clamp(1e-6, 1.0);
            Self::scored_candidate_policy_choice(candidate, candidates, behavior_probability, false)
        })
    }

    fn finishing_selection_shot_drought_boost_for_team(&self, team: Team) -> f64 {
        let boost = neural_finishing_selection_shot_drought_boost();
        if boost <= 1e-9 {
            return 0.0;
        }
        let (own_shots, opp_shots) = match team {
            Team::Home => (self.stats.shots_home, self.stats.shots_away),
            Team::Away => (self.stats.shots_away, self.stats.shots_home),
        };
        if own_shots > opp_shots {
            return 0.0;
        }
        let zero_shot_fit: f64 = if own_shots == 0 { 1.0 } else { 0.0 };
        let deficit_fit = (opp_shots.saturating_sub(own_shots) as f64 / 3.0).clamp(0.0, 1.0) * 0.65;
        boost * zero_shot_fit.max(deficit_fit)
    }

    fn neural_authoritative_dp_safety_choice(
        candidates: &[SoccerNeuralMctsCandidate],
        legal: &[SoccerLearnedActionTrace],
    ) -> Option<SoccerPolicyActionChoice> {
        if !soccer_neural_authoritative_dp_safety_enabled() {
            return None;
        }
        let top = candidates.first()?;
        let top_key = normalize_soccer_action_label(&top.label);
        let min_best = soccer_neural_authoritative_dp_safety_min_best_value();
        let min_margin = soccer_neural_authoritative_dp_safety_min_margin();
        let min_ratio = soccer_neural_authoritative_dp_safety_min_ratio();
        let dp_value_for = |label: &str| -> Option<f64> {
            let key = normalize_soccer_action_label(label);
            legal
                .iter()
                .filter(|action| action.legal)
                .filter(|action| normalize_soccer_action_label(&action.label) == key)
                .map(|action| action.value)
                .filter(|value| value.is_finite())
                .max_by(|a, b| a.total_cmp(b))
        };
        let top_dp_value = dp_value_for(&top.label).unwrap_or(0.0);
        let mut ranked_dp = legal
            .iter()
            .filter(|action| action.legal && action.value.is_finite())
            .collect::<Vec<_>>();
        ranked_dp.sort_by(|a, b| {
            b.value
                .total_cmp(&a.value)
                .then_with(|| a.label.cmp(&b.label))
        });
        for fallback in ranked_dp {
            let fallback_key = normalize_soccer_action_label(&fallback.label);
            if fallback_key == top_key {
                return None;
            }
            if fallback.value < min_best {
                return None;
            }
            let margin = fallback.value - top_dp_value;
            if margin < min_margin {
                continue;
            }
            if top_dp_value >= fallback.value * min_ratio {
                continue;
            }
            if let Some(candidate) = candidates
                .iter()
                .find(|candidate| normalize_soccer_action_label(&candidate.label) == fallback_key)
            {
                return Some(Self::scored_candidate_policy_choice(
                    candidate, candidates, 1.0, false,
                ));
            }
        }
        None
    }

    fn technical_scored_candidate_floor_choice(
        candidates: &[SoccerNeuralMctsCandidate],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        let floor = neural_mcts_technical_selection_floor();
        if floor <= 1e-9 || !draw.is_finite() || draw >= floor {
            return None;
        }
        let candidate_count = candidates.len().min(POLICY_SELECTION_TOP_RANK_LIMIT);
        if candidate_count == 0 {
            return None;
        }
        let best_score = candidates[..candidate_count]
            .iter()
            .map(|candidate| candidate.score)
            .fold(f64::NEG_INFINITY, f64::max);
        if !best_score.is_finite() {
            return None;
        }
        let max_regression = neural_mcts_technical_selection_max_score_regression();
        if max_regression <= 0.0 || !max_regression.is_finite() {
            return None;
        }
        let rank_weights = soccer_policy_top_rank_weights();
        let mut eligible = [(0usize, 0.0f64); POLICY_SELECTION_TOP_RANK_LIMIT];
        let mut eligible_count = 0usize;
        let mut total = 0.0;
        for rank in 0..candidate_count {
            let candidate = &candidates[rank];
            if !candidate.score.is_finite() || candidate.score + max_regression < best_score {
                continue;
            }
            let label = normalize_soccer_action_label(&candidate.label);
            if !is_dribble_action_label(label)
                && learned_discretized_kick_speed_bucket_for_action_label(&candidate.label)
                    .is_none()
                && !matches!(label, "first-time-shot" | "first-time-header")
            {
                continue;
            }
            let weight = rank_weights[rank].max(0.0);
            if weight <= 0.0 {
                continue;
            }
            eligible[eligible_count] = (rank, weight);
            eligible_count += 1;
            total += weight;
        }
        if eligible_count == 0 || !total.is_finite() || total <= 1e-9 {
            return None;
        }
        let mut threshold = (draw / floor).clamp(0.0, 1.0 - f64::EPSILON) * total;
        for (rank, weight) in eligible[..eligible_count].iter().copied() {
            if threshold < weight {
                return candidates.get(rank).map(|candidate| {
                    Self::scored_candidate_policy_choice(
                        candidate,
                        candidates,
                        soccer_policy_rank_probability(candidate_count, rank),
                        false,
                    )
                });
            }
            threshold -= weight;
        }
        candidates
            .get(eligible[eligible_count - 1].0)
            .map(|candidate| {
                Self::scored_candidate_policy_choice(
                    candidate,
                    candidates,
                    soccer_policy_rank_probability(candidate_count, eligible[eligible_count - 1].0),
                    false,
                )
            })
    }

    fn apply_retrieval_prior_to_policy_actions(
        ranked: &mut [SoccerLearnedActionTrace],
        retrieval_prior: Option<(&std::collections::HashMap<String, f64>, f64)>,
    ) {
        if let Some((prior, weight)) =
            retrieval_prior.filter(|(p, w)| !p.is_empty() && w.is_finite() && *w != 0.0)
        {
            for candidate in ranked.iter_mut().filter(|candidate| candidate.legal) {
                candidate.value += weight
                    * prior
                        .get(normalize_soccer_action_label(&candidate.label))
                        .copied()
                        .unwrap_or(0.0);
            }
            ranked.sort_by(|a, b| {
                b.legal
                    .cmp(&a.legal)
                    .then_with(|| b.value.total_cmp(&a.value))
                    .then_with(|| b.visits.cmp(&a.visits))
                    .then_with(|| a.label.cmp(&b.label))
            });
        }
    }

    fn weighted_policy_action_probability_for_player(
        &self,
        policy: &SoccerQPolicy,
        snapshot: &WorldSnapshot,
        player_id: usize,
        mdp_state: &SoccerMdpState,
        observation: &SoccerPomdpObservation,
        retrieval_prior: Option<(&std::collections::HashMap<String, f64>, f64)>,
        action_label: &str,
    ) -> f64 {
        let Some((_, mut ranked)) = policy.ranked_action_values_for_snapshot(
            snapshot,
            player_id,
            SOCCER_RETRIEVAL_PRIOR_RERANK_LIMIT.max(POLICY_SELECTION_TOP_RANK_LIMIT),
        ) else {
            return policy
                .best_action_for_state_observation_with_prior(
                    snapshot,
                    player_id,
                    mdp_state,
                    observation,
                    retrieval_prior,
                )
                .filter(|label| {
                    normalize_soccer_action_label(label)
                        == normalize_soccer_action_label(action_label)
                })
                .map(|_| 1.0)
                .unwrap_or(0.0);
        };
        Self::apply_retrieval_prior_to_policy_actions(&mut ranked, retrieval_prior);
        let probability = soccer_policy_rank_probability_for_label(&ranked, action_label);
        if probability > 0.0 {
            return probability;
        }
        policy
            .best_action_for_state_observation_with_prior(
                snapshot,
                player_id,
                mdp_state,
                observation,
                retrieval_prior,
            )
            .filter(|label| {
                normalize_soccer_action_label(label) == normalize_soccer_action_label(action_label)
            })
            .map(|_| 1.0)
            .unwrap_or(0.0)
    }

    fn weighted_policy_action_for_player(
        &self,
        policy: &SoccerQPolicy,
        snapshot: &WorldSnapshot,
        player_id: usize,
        mdp_state: &SoccerMdpState,
        observation: &SoccerPomdpObservation,
        retrieval_prior: Option<(&std::collections::HashMap<String, f64>, f64)>,
        salt: u64,
    ) -> Option<SoccerPolicyActionChoice> {
        let draw = self.policy_rank_selection_draw(snapshot, player_id, salt);
        let (_, mut ranked) = policy.ranked_action_values_for_snapshot(
            snapshot,
            player_id,
            SOCCER_RETRIEVAL_PRIOR_RERANK_LIMIT.max(POLICY_SELECTION_TOP_RANK_LIMIT),
        )?;
        Self::apply_retrieval_prior_to_policy_actions(&mut ranked, retrieval_prior);
        Self::weighted_replan_safe_ranked_action_choice(policy, snapshot, player_id, &ranked, draw)
            .or_else(|| Self::weighted_ranked_action_choice(&ranked, draw))
            .or_else(|| {
                policy
                    .best_action_for_state_observation_with_prior(
                        snapshot,
                        player_id,
                        mdp_state,
                        observation,
                        retrieval_prior,
                    )
                    .map(|label| SoccerPolicyActionChoice {
                        label,
                        plan: None,
                        behavior_probability: 1.0,
                        neural_mcts_selected: false,
                        neural_mcts_candidate_count: 0,
                        neural_mcts_discretized_kick_candidate_count: 0,
                        neural_mcts_root_discretized_kick_candidate_count: 0,
                        neural_mcts_dribble_candidate_count: 0,
                        neural_mcts_root_dribble_candidate_count: 0,
                    })
            })
    }

    fn external_nn_pomdp_sidecar_action_for_player(
        &self,
        _policy: &SoccerQPolicy,
        snapshot: &WorldSnapshot,
        player_id: usize,
        _retrieval_prior: Option<(&std::collections::HashMap<String, f64>, f64)>,
    ) -> Option<SoccerPolicyActionChoice> {
        if !soccer_external_nn_pomdp_sidecar_enabled() {
            return None;
        }
        // On-ball-only lever: let the strong analytic MPC keep off-ball positioning; the learned net
        // only owns the ball-carrier's decision. Recovers score when the net's off-ball play is weak.
        //
        // SELECTIVE SUPPORT-OUTLET lever (gated SOCCER_BURN_SIDECAR_SUPPORT_OUTLET): in addition to
        // the carrier, also let the net drive exactly ONE off-ball support runner when our side has
        // possession — restricted (below) to support-family actions only. Everyone else stays MPC.
        // Rationale: the on-ball policy can't CREATE a receiving option; one learned support runner
        // changes the next on-ball decision surface, which the analytic pass machinery can exploit.
        let is_carrier = snapshot.ball.holder == Some(player_id);
        let mut support_only_mask = false;
        if std::env::var("SOCCER_BURN_SIDECAR_ON_BALL_ONLY")
            .ok()
            .as_deref()
            == Some("1")
            && !is_carrier
        {
            let support_outlet = std::env::var("SOCCER_BURN_SIDECAR_SUPPORT_OUTLET")
                .ok()
                .as_deref()
                == Some("1");
            // MULTI-ROLE possession scope (Codex): drive the K nearest mid/fwd support runners
            // (K = SOCCER_BURN_SIDECAR_SUPPORT_ACTORS, default 3), each support-masked — a coordinated
            // receiver SET creates options for the carrier, where one runner (0.479) could not.
            if support_outlet
                && self
                    .designated_support_actor_set(snapshot)
                    .contains(&player_id)
            {
                support_only_mask = true; // serve this actor, but support-family actions only
            } else {
                return None;
            }
        }
        {
            use std::sync::atomic::{AtomicUsize, Ordering};
            static N: AtomicUsize = AtomicUsize::new(0);
            let n = N.fetch_add(1, Ordering::Relaxed) + 1;
            if n <= 3 || n % 250 == 0 {
                eprintln!(
                    "SIDECAR_DBG reached={n} tick={} player={player_id}",
                    snapshot.tick
                );
            }
        }
        let player = snapshot.players.iter().find(|p| p.id == player_id)?;
        let Some(mut legal_action_mask) =
            soccer_policy_legal_action_mask_for_snapshot(snapshot, player_id)
        else {
            eprintln!("SIDECAR_DBG bail=mask_none player={player_id}");
            return None;
        };
        if support_only_mask {
            // Support runner learns timing/FAMILY only; analytic target-gen + shape/offside/spacing
            // guards + MPC handle execution. Restrict its legal mask to support-family actions.
            fn is_support_family(index: usize) -> bool {
                matches!(
                    SOCCER_POLICY_ACTIONS.get(index).copied(),
                    Some("support-shape")
                        | Some("support-roam")
                        | Some("support-screen")
                        | Some("check-to-ball")
                        | Some("run-in-behind")
                        | Some("exploit-space-run")
                        | Some("wide-outlet")
                        | Some("shot-creation-run")
                        | Some("pinch-cross-arrival")
                        | Some("overlap-run")
                        | Some("one-two-run")
                        | Some("support-push-up")
                        | Some("hold-up-flank")
                        | Some("wait-for-support")
                        | Some("open-passing-lane")
                        | Some("open-pass-lane")
                        | Some("buildup-receive")
                )
            }
            for (i, ok) in legal_action_mask.iter_mut().enumerate() {
                if *ok && !is_support_family(i) {
                    *ok = false;
                }
            }
            if !legal_action_mask.iter().any(|&ok| ok) {
                return None; // no legal support action this tick ⇒ fall back to MPC
            }
        }
        let entities = soccer_field_player_motion_block(snapshot, player_id, player.team);
        if entities.len() != SOCCER_NEURAL_FIELD_MOTION_DIM {
            return None;
        }
        let request = SoccerExternalNnPomdpSidecarRequest {
            kind: "soccer-external-nn-pomdp-sidecar-inference",
            version: SOCCER_EXTERNAL_NN_POMDP_SIDECAR_CONTRACT_VERSION,
            tick: snapshot.tick,
            player_id,
            team: player.team,
            role: player.role,
            entity_shape: [
                SOCCER_NEURAL_FIELD_MOTION_PLAYERS + SOCCER_NEURAL_FIELD_MOTION_BALLS,
                SOCCER_NEURAL_FIELD_MOTION_PER_PLAYER,
            ],
            entities: entities.as_slice(),
            legal_action_mask: legal_action_mask.as_slice(),
            action_labels: SOCCER_POLICY_ACTIONS,
        };
        let SoccerExternalNnPomdpSidecarResponse {
            logits,
            value: _value,
            behavior_policy_probability,
            action_index: sidecar_action_index,
        } = soccer_external_nn_pomdp_sidecar_infer(&request)?;
        // Prefer the sidecar's OWN sampled action (so the logged action matches the reported prob),
        // but only if it is legal for this snapshot; otherwise fall back to the legal argmax.
        let action_index = sidecar_action_index
            .filter(|&i| legal_action_mask.get(i).copied().unwrap_or(false))
            .or_else(|| {
                soccer_external_nn_pomdp_select_legal_argmax(&logits, &legal_action_mask)
            })?;
        let label = SOCCER_POLICY_ACTIONS.get(action_index)?.to_string();
        // Stamp the TRUE sampled probability when the sidecar provided one (finite, >0); else 1.0
        // (deterministic argmax). This gives the offline trainer a real old-policy prob for
        // clipped-PPO importance weighting instead of a constant 1.0.
        let behavior_probability = match behavior_policy_probability {
            Some(p) => {
                let p = finite_unit_interval(p);
                if p > 0.0 {
                    p
                } else {
                    1.0
                }
            }
            None => 1.0,
        };
        Some(SoccerPolicyActionChoice {
            label,
            plan: None,
            behavior_probability,
            neural_mcts_selected: false,
            neural_mcts_candidate_count: 0,
            neural_mcts_discretized_kick_candidate_count: 0,
            neural_mcts_root_discretized_kick_candidate_count: 0,
            neural_mcts_dribble_candidate_count: 0,
            neural_mcts_root_dribble_candidate_count: 0,
        })
    }

    /// The SET of off-ball support runners the net may drive under the multi-role support-outlet
    /// lever: the K nearest Midfielder/Forward teammates to the ball carrier (K =
    /// SOCCER_BURN_SIDECAR_SUPPORT_ACTORS, default 3, clamped 1..=4; excludes carrier + GK/defenders),
    /// while our side has possession. Deterministic (distance-sorted, `total_cmp`). Empty ⇒ all-MPC.
    fn designated_support_actor_set(&self, snapshot: &WorldSnapshot) -> Vec<usize> {
        let Some(holder) = snapshot.ball.holder else {
            return Vec::new();
        };
        let Some(carrier) = snapshot.players.iter().find(|p| p.id == holder) else {
            return Vec::new();
        };
        let cpos = carrier.position;
        let k = std::env::var("SOCCER_BURN_SIDECAR_SUPPORT_ACTORS")
            .ok()
            .and_then(|s| s.trim().parse::<usize>().ok())
            .unwrap_or(3)
            .clamp(1, 4);
        let mut cands: Vec<(usize, f64)> = snapshot
            .players
            .iter()
            .filter(|p| {
                p.team == carrier.team
                    && p.id != holder
                    && matches!(p.role, PlayerRole::Midfielder | PlayerRole::Forward)
            })
            .map(|p| {
                let d = (p.position.x - cpos.x).powi(2) + (p.position.y - cpos.y).powi(2);
                (p.id, d)
            })
            .collect();
        cands.sort_by(|a, b| a.1.total_cmp(&b.1));
        cands.truncate(k);
        cands.into_iter().map(|(id, _)| id).collect()
    }

    fn learned_action_for_player_with_context(
        &self,
        snapshot: &WorldSnapshot,
        player_id: usize,
        mdp_state: &SoccerMdpState,
        observation: &SoccerPomdpObservation,
    ) -> Option<SoccerLearnedDecisionPlan> {
        let player = snapshot.players.iter().find(|p| p.id == player_id)?;
        if !self.learned_policy_inference_enabled_for_team(player.team) {
            return None;
        }
        // Retrieval action prior for this player's team (empty/None unless the
        // consumer installed one and `decision_prior_enabled`). `Option<(&map, w)>`
        // is `Copy`, so the same prior is shared by both decision branches below.
        let retrieval_prior = if self.config.retrieval.decision_prior_enabled {
            self.retrieval_action_prior
                .get(&player.team)
                .filter(|map| !map.is_empty())
                .map(|map| (map, self.config.retrieval.prior_weight))
        } else {
            None
        };
        if let Some(team_policies) = &self.team_policies {
            let policy = team_policies.policy(player.team);
            if let Some(choice) = self
                .external_nn_pomdp_sidecar_action_for_player(
                    policy,
                    snapshot,
                    player_id,
                    retrieval_prior,
                )
                .or_else(|| {
                    self.neural_blended_action(
                        policy,
                        snapshot,
                        player_id,
                        mdp_state,
                        observation,
                        player.team,
                        player.role,
                        SOCCER_POLICY_RANK_SALT_TEAM_NEURAL,
                    )
                })
                .or_else(|| {
                    self.exploration_action_for_player(
                        policy,
                        snapshot,
                        player_id,
                        mdp_state,
                        observation,
                        retrieval_prior,
                    )
                })
                .or_else(|| {
                    self.weighted_policy_action_for_player(
                        policy,
                        snapshot,
                        player_id,
                        mdp_state,
                        observation,
                        retrieval_prior,
                        SOCCER_POLICY_RANK_SALT_TEAM_TABULAR,
                    )
                })
            {
                let SoccerPolicyActionChoice {
                    label,
                    plan,
                    behavior_probability,
                    neural_mcts_selected,
                    neural_mcts_candidate_count,
                    neural_mcts_discretized_kick_candidate_count,
                    neural_mcts_root_discretized_kick_candidate_count,
                    neural_mcts_dribble_candidate_count,
                    neural_mcts_root_dribble_candidate_count,
                } = choice;
                if net_influence_diag_enabled() {
                    // Net-influence (Codex-corrected baseline): the counterfactual is the ACTUAL
                    // tabular-only decision path (rank-weighted + replan-safe filter, blend off),
                    // not raw argmax. `label` is what the net/sidecar/exploration chain selected;
                    // if it differs from the tabular choice, the neural stack flipped the decision
                    // the engine would otherwise have committed. `neural_mcts_selected` marks the
                    // subset where the neural MCTS actually owned the pick.
                    if let Some(tabular) = self.weighted_policy_action_for_player(
                        policy,
                        snapshot,
                        player_id,
                        mdp_state,
                        observation,
                        retrieval_prior,
                        SOCCER_POLICY_RANK_SALT_TEAM_TABULAR,
                    ) {
                        record_net_influence_diag(
                            normalize_soccer_action_label(&tabular.label),
                            normalize_soccer_action_label(&label),
                            &tabular.label,
                            &label,
                            observation.has_ball,
                            neural_mcts_selected,
                        );
                    }
                }
                let plan = plan.unwrap_or_else(|| {
                    Self::learned_plan_for_policy(policy, snapshot, player_id, label.clone())
                });
                let plan = Self::mpc_reconciled_learned_plan(policy, snapshot, player_id, plan);
                record_pass_space_scored_plan_diag(snapshot, &plan);
                return Some(SoccerLearnedDecisionPlan {
                    label,
                    plan,
                    behavior_probability,
                    neural_mcts_selected,
                    neural_mcts_candidate_count,
                    neural_mcts_discretized_kick_candidate_count,
                    neural_mcts_root_discretized_kick_candidate_count,
                    neural_mcts_dribble_candidate_count,
                    neural_mcts_root_dribble_candidate_count,
                });
            }
        }
        let learned_policy = self.learned_policy.as_ref()?;
        self.external_nn_pomdp_sidecar_action_for_player(
            learned_policy,
            snapshot,
            player_id,
            retrieval_prior,
        )
        .or_else(|| {
            self.neural_blended_action(
                learned_policy,
                snapshot,
                player_id,
                mdp_state,
                observation,
                player.team,
                player.role,
                SOCCER_POLICY_RANK_SALT_SHARED_NEURAL,
            )
        })
        .or_else(|| {
            self.exploration_action_for_player(
                learned_policy,
                snapshot,
                player_id,
                mdp_state,
                observation,
                retrieval_prior,
            )
        })
        .or_else(|| {
            self.weighted_policy_action_for_player(
                learned_policy,
                snapshot,
                player_id,
                mdp_state,
                observation,
                retrieval_prior,
                SOCCER_POLICY_RANK_SALT_SHARED_TABULAR,
            )
        })
        .map(|choice| {
            let SoccerPolicyActionChoice {
                label,
                plan,
                behavior_probability,
                neural_mcts_selected,
                neural_mcts_candidate_count,
                neural_mcts_discretized_kick_candidate_count,
                neural_mcts_root_discretized_kick_candidate_count,
                neural_mcts_dribble_candidate_count,
                neural_mcts_root_dribble_candidate_count,
            } = choice;
            let plan = plan.unwrap_or_else(|| {
                Self::learned_plan_for_policy(learned_policy, snapshot, player_id, label.clone())
            });
            let plan = Self::mpc_reconciled_learned_plan(learned_policy, snapshot, player_id, plan);
            record_pass_space_scored_plan_diag(snapshot, &plan);
            SoccerLearnedDecisionPlan {
                label,
                plan,
                behavior_probability,
                neural_mcts_selected,
                neural_mcts_candidate_count,
                neural_mcts_discretized_kick_candidate_count,
                neural_mcts_root_discretized_kick_candidate_count,
                neural_mcts_dribble_candidate_count,
                neural_mcts_root_dribble_candidate_count,
            }
        })
    }

    fn stamp_learned_policy_behavior_probability(
        player: &mut PlayerAgent,
        behavior_probability: f64,
    ) {
        let Some(decision) = player.last_decision.as_mut() else {
            return;
        };
        stamp_learned_policy_behavior_probability_on_decision(decision, behavior_probability);
    }

    fn actor_policy_probability_for_action(
        &self,
        snapshot: &WorldSnapshot,
        player_id: usize,
        mdp_state: &SoccerMdpState,
        observation: &SoccerPomdpObservation,
        label: &str,
    ) -> Option<f64> {
        let player = snapshot
            .players
            .iter()
            .find(|player| player.id == player_id)?;
        let mut transition = self.neural_decision_transition(
            snapshot,
            player_id,
            player.team,
            player.role,
            mdp_state,
            observation,
        );
        transition.action.clear();
        let state_features = self.policy_state_features(&transition);
        let action_index = soccer_policy_action_index(label)?;
        let legal_action_mask = soccer_policy_legal_action_mask_for_snapshot(snapshot, player_id)?;
        self.policy_head_for(player.team)?
            .action_distribution_for_role_with_mask(
                &state_features,
                player.role,
                &legal_action_mask,
            )?
            .get(action_index)
            .copied()
            .map(finite_unit_interval)
            .filter(|probability| *probability > 0.0)
    }

    fn stamp_neural_mcts_selection(
        player: &mut PlayerAgent,
        selected: bool,
        selected_action: Option<&str>,
        candidate_count: u32,
        discretized_kick_candidate_count: u32,
        root_discretized_kick_candidate_count: u32,
        dribble_candidate_count: u32,
        root_dribble_candidate_count: u32,
    ) {
        let Some(decision) = player.last_decision.as_mut() else {
            return;
        };
        let selected_matches_executed = selected
            && selected_action
                .map(|label| {
                    normalize_soccer_action_label(label)
                        == normalize_soccer_action_label(&decision.action)
                })
                .unwrap_or(false);
        decision.neural_mcts_selected = selected_matches_executed;
        if candidate_count > 0 {
            decision.neural_mcts_candidate_count = candidate_count;
            decision.neural_mcts_discretized_kick_candidate_count =
                discretized_kick_candidate_count;
            decision.neural_mcts_root_discretized_kick_candidate_count =
                root_discretized_kick_candidate_count;
            decision.neural_mcts_dribble_candidate_count = dribble_candidate_count;
            decision.neural_mcts_root_dribble_candidate_count = root_dribble_candidate_count;
        } else {
            decision.neural_mcts_candidate_count = 0;
            decision.neural_mcts_discretized_kick_candidate_count = 0;
            decision.neural_mcts_root_discretized_kick_candidate_count = 0;
            decision.neural_mcts_dribble_candidate_count = 0;
            decision.neural_mcts_root_dribble_candidate_count = 0;
        }
    }

    fn stamp_learned_pass_receiver_descriptor(player: &mut PlayerAgent, snapshot: &WorldSnapshot) {
        if !dd_soccer_enable_learned_pass_receiver() {
            return;
        }
        let Some(decision) = player.last_decision.as_mut() else {
            return;
        };
        let normalized_action = normalize_soccer_action_label(&decision.action);
        if pass_like_action_flight(&normalized_action).is_none() {
            return;
        }
        let Some(action_target) = decision.action_target.as_mut() else {
            return;
        };
        let Some(point) = action_target.point else {
            return;
        };
        let Some(target_id) = action_target.player_id else {
            return;
        };
        let Some(target) = snapshot.players.iter().find(|p| p.id == target_id) else {
            return;
        };
        if target.team != player.team {
            return;
        }
        let receiver_position = snapshot
            .player_position(target_id)
            .unwrap_or(target.position);
        let kind = if point.distance(receiver_position) > 1.0 {
            ReceiverKind::Space
        } else {
            ReceiverKind::Teammate
        };
        action_target.receiver_descriptor =
            Some(snapshot.pass_receiver_descriptor(player.id, kind, point, Some(target.role)));
    }

    /// Build a feature-only decision-time transition: the player's real
    /// state/observation/team/role, with neutral defaults for the post-action
    /// fields the value-head feature builder reads (those sit at the same
    /// fallbacks the training path uses when a field is absent). `action` is left
    /// empty for the caller to set per candidate; `belief` and `next_*` are not
    /// read by the feature builder and carry placeholders.
    fn neural_decision_transition(
        &self,
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        role: PlayerRole,
        mdp_state: &SoccerMdpState,
        observation: &SoccerPomdpObservation,
    ) -> SoccerLearningTransition {
        SoccerLearningTransition {
            tick: snapshot.tick,
            player_id,
            team,
            role,
            state: mdp_state.clone(),
            observation: observation.clone(),
            belief: BeliefState {
                possession_confidence: 0.0,
                pressure: 0.0,
                pass_lane_open: 0.0,
                shot_quality: 0.0,
            },
            action: String::new(),
            action_target: None,
            decision_context: soccer_decision_context_for(
                player_id, team, "", None, snapshot, snapshot,
            ),
            tactical_trace: SoccerTacticalLearningTrace::default(),
            reward: 0.0,
            next_state: mdp_state.clone(),
            next_observation: observation.clone(),
            done: false,
        }
    }

    fn learned_plan_action_target_trace(
        snapshot: &WorldSnapshot,
        player_id: usize,
        plan: &SoccerLearnedPlan,
    ) -> Option<AgentActionTargetTrace> {
        let point = plan
            .target_point
            .or_else(|| {
                plan.target_player
                    .and_then(|id| snapshot.player_position(id))
            })?
            .clamp_to_pitch(snapshot.field_width, snapshot.field_length);
        let actor_position = snapshot.player_position(player_id).unwrap_or(point);
        // Credit the learned pass-receiver head per-receiver only when the gate is on; otherwise
        // leave it None so training folds in RECEIVER_DESCRIPTOR_UNSPECIFIED (grid-only parity).
        let receiver_descriptor = if dd_soccer_enable_learned_pass_receiver()
            && pass_like_action_flight(normalize_soccer_action_label(&plan.action)).is_some()
        {
            let (kind, role) = match plan.target_player {
                Some(target_id) => {
                    let target = snapshot.players.iter().find(|p| p.id == target_id);
                    let receiver_position = target
                        .and_then(|p| snapshot.player_position(p.id))
                        .or_else(|| target.map(|p| p.position));
                    let kind = if receiver_position
                        .map(|receiver_position| point.distance(receiver_position) > 1.0)
                        .unwrap_or(false)
                    {
                        ReceiverKind::Space
                    } else {
                        ReceiverKind::Teammate
                    };
                    (kind, target.map(|p| p.role))
                }
                None => (ReceiverKind::Space, None),
            };
            Some(snapshot.pass_receiver_descriptor(player_id, kind, point, role))
        } else {
            None
        };
        Some(AgentActionTargetTrace {
            point: Some(point),
            player_id: plan.target_player,
            grid: Some(pitch_grid_address(
                point,
                snapshot.field_width,
                snapshot.field_length,
            )),
            facing: facing_bucket_from_vector(point - actor_position),
            dribble_touch: None,
            receiver_descriptor,
        })
    }

    fn neural_decision_transition_for_plan(
        &self,
        base: &SoccerLearningTransition,
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        plan: &SoccerLearnedPlan,
    ) -> SoccerLearningTransition {
        let action = learned_mpc_action_label_key(&plan.action);
        let action_target = Self::learned_plan_action_target_trace(snapshot, player_id, plan);
        let mut transition = base.clone();
        transition.action = action.clone();
        transition.action_target = action_target.clone();
        transition.decision_context = soccer_decision_context_for(
            player_id,
            team,
            &action,
            action_target.as_ref(),
            snapshot,
            snapshot,
        );
        transition
    }

    fn neural_mcts_expanded_candidate_plans(
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        candidate_label: &str,
    ) -> Vec<SoccerLearnedPlan> {
        let normalized = normalize_soccer_action_label(candidate_label);
        let exact_learned_kick =
            learned_discretized_kick_speed_bucket_for_action_label(candidate_label).is_some();
        if candidate_label != normalized && !exact_learned_kick {
            return Vec::new();
        }
        if normalized == "dribble" {
            return Self::neural_mcts_dribble_variant_candidate_plans(snapshot, player_id);
        }
        if matches!(normalized, "shoot" | "first-time-shot") {
            return Self::neural_mcts_shot_variant_candidate_plans(
                snapshot,
                player_id,
                team,
                normalized,
                candidate_label,
            );
        }
        let (prefix, targets) = match normalized {
            "pass" => {
                let mut targets = snapshot.ranked_visible_pass_targets(player_id, 11);
                for target in snapshot.ranked_threaded_pass_candidates(player_id, 11) {
                    if !targets.contains(&target) {
                        targets.push(target);
                    }
                }
                ("pass", targets)
            }
            "aerial-pass" => (
                "aerial-pass",
                snapshot.ranked_visible_aerial_pass_targets(player_id, 11),
            ),
            _ => return Vec::new(),
        };
        let limit = neural_mcts_pass_target_candidate_limit();
        record_mcts_pass_target_diag(snapshot, player_id, team, prefix, &targets, limit);
        if pass_cand_diag_enabled() {
            if let Some(passer_pos) = snapshot.player_position(player_id) {
                let dir = team.attack_dir();
                let (mut fwd_pre, mut lat_pre, mut back_pre, mut fwd_post) = (0, 0, 0, 0);
                let (mut fwd_open, mut fwd_marked) = (0, 0);
                for (i, tp) in targets.iter().enumerate() {
                    if let Some(p) = snapshot.player_position(*tp) {
                        let forward = (p.y - passer_pos.y) * dir;
                        if forward > 1.25 {
                            fwd_pre += 1;
                            if i < limit {
                                fwd_post += 1;
                            }
                            // Openness proxy: nearest opponent distance to the target's feet.
                            // A marked forward target (defender within ~4yd) is a pass-to-feet trap;
                            // an open one is a receivable progressive option. Codex round-20.
                            let nearest_opp = snapshot
                                .players
                                .iter()
                                .filter(|op| op.team != team)
                                .filter_map(|op| snapshot.player_position(op.id))
                                .fold(f64::INFINITY, |acc, opp| acc.min(p.distance(opp)));
                            if nearest_opp >= 4.0 {
                                fwd_open += 1;
                            } else {
                                fwd_marked += 1;
                            }
                        } else if forward < -1.25 {
                            back_pre += 1;
                        } else {
                            lat_pre += 1;
                        }
                    }
                }
                record_pass_candidate_diag(
                    fwd_pre, lat_pre, back_pre, fwd_post, fwd_open, fwd_marked,
                );
            }
        }
        targets
            .into_iter()
            .take(limit)
            .enumerate()
            .flat_map(|(index, target_player)| {
                let base_action = format!("{}{}", prefix, index + 1);
                Self::neural_mcts_pass_target_candidate_plans(
                    snapshot,
                    player_id,
                    team,
                    prefix,
                    base_action,
                    target_player,
                )
            })
            .collect()
    }

    fn neural_mcts_pass_target_candidate_plans(
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        prefix: &str,
        base_action: String,
        target_player: usize,
    ) -> Vec<SoccerLearnedPlan> {
        let mut plans = Vec::with_capacity(
            1 + if dd_soccer_enable_discretized_kick() {
                neural_mcts_kick_power_candidate_limit()
            } else {
                0
            },
        );
        plans.push(SoccerLearnedPlan {
            action: base_action.clone(),
            target_player: Some(target_player),
            target_point: snapshot.player_position(target_player),
            mpc_replan: None,
        });
        // Pass-to-space variant (gated, Codex round-10 shape): same receiver, but the ball
        // is led into the anticipated reception point ahead of them, so the CRITIC scores
        // feet-vs-run-onto and owns that spatial choice. Keeps `target_player` bound so pass
        // MPC/receipt/concede-veto logic is unchanged. Skipped when the lead coincides with
        // the feet target (no distinct candidate to score). Default OFF ⇒ byte-identical.
        if dd_soccer_enable_neural_pass_space() {
            if let (Some(passer), Some(receiver_position)) = (
                snapshot.players.iter().find(|p| p.id == player_id),
                snapshot.player_position(target_player),
            ) {
                let flight = pass_like_action_flight(prefix).unwrap_or(PassFlight::Floor);
                let passer_position = snapshot
                    .player_position(player_id)
                    .unwrap_or(receiver_position);
                let is_cross = pass_would_be_cross(
                    passer_position,
                    receiver_position,
                    team,
                    snapshot.field_width,
                    snapshot.field_length,
                );
                let nominal_speed =
                    pass_speed_yps_from_power(0.68, flight, is_cross, &passer.skills);
                let space_point = snapshot.anticipated_pass_reception_point(
                    player_id,
                    target_player,
                    flight,
                    nominal_speed,
                );
                let distinct = space_point
                    .map(|sp| sp.distance(receiver_position) > 1.0)
                    .unwrap_or(false);
                if pass_space_diag_enabled() {
                    record_pass_space_source_diag(space_point.is_some(), distinct);
                }
                if let Some(space_point) = space_point {
                    if distinct {
                        plans.push(SoccerLearnedPlan {
                            action: base_action.clone(),
                            target_player: Some(target_player),
                            target_point: Some(space_point),
                            mpc_replan: None,
                        });
                    }
                }
            }
        }
        if dd_soccer_enable_discretized_kick() {
            let buckets = if prefix == "aerial-pass" {
                &NEURAL_MCTS_AERIAL_KICK_POWER_BUCKETS[..]
            } else {
                &NEURAL_MCTS_FLOOR_KICK_POWER_BUCKETS[..]
            };
            plans.extend(
                buckets
                    .iter()
                    .copied()
                    .take(neural_mcts_kick_power_candidate_limit())
                    .filter_map(|bucket| {
                        learned_discretized_kick_candidate_label(&base_action, bucket).map(
                            |action| SoccerLearnedPlan {
                                action,
                                target_player: Some(target_player),
                                target_point: snapshot.player_position(target_player),
                                mpc_replan: None,
                            },
                        )
                    }),
            );
        }
        plans
    }

    fn neural_mcts_expanded_candidate_plans_for_policy(
        policy: &SoccerQPolicy,
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        candidate_label: &str,
    ) -> Vec<SoccerLearnedPlan> {
        let mut plans =
            Self::neural_mcts_expanded_candidate_plans(snapshot, player_id, team, candidate_label);
        if !dd_soccer_enable_neural_pass_space() {
            return plans;
        }
        let normalized = normalize_soccer_action_label(candidate_label);
        let Some(flight) = pass_like_action_flight(normalized) else {
            return plans;
        };
        let Some((_, runner, space_point)) =
            Self::learned_pass_space_option(policy, snapshot, player_id, normalized)
        else {
            return plans;
        };
        let duplicate = plans.iter().any(|plan| {
            plan.target_player == Some(runner)
                && plan
                    .target_point
                    .is_some_and(|point| point.distance(space_point) <= 1.0)
        });
        if duplicate {
            return plans;
        }
        let action = if flight.is_aerial() {
            "aerial-pass"
        } else {
            "pass"
        }
        .to_string();
        plans.push(SoccerLearnedPlan {
            action,
            target_player: Some(runner),
            target_point: Some(space_point),
            mpc_replan: None,
        });
        plans
    }

    fn neural_mcts_dribble_variant_candidate_plans(
        snapshot: &WorldSnapshot,
        player_id: usize,
    ) -> Vec<SoccerLearnedPlan> {
        const DRIBBLE_VARIANTS: &[&str] = &[
            "carry-forward",
            "carry-out-left",
            "carry-out-right",
            "left-cut",
            "right-cut",
            "side-step",
            "protect-ball",
            "open-passing-lane",
            "nutmeg",
            "xavi-turn",
            "fake-left-cut-right",
            "fake-right-cut-left",
        ];
        let Some(player) = snapshot
            .players
            .iter()
            .find(|player| player.id == player_id)
        else {
            return Vec::new();
        };
        DRIBBLE_VARIANTS
            .iter()
            .filter_map(|action| {
                let kind = dribble_move_kind_for_action_label(action)?;
                let touch = snapshot.deterministic_dribble_touch_decision_for(player_id, kind);
                let target = snapshot.dribble_move_target_for_touch(
                    player_id,
                    player.home_position,
                    kind,
                    touch,
                );
                Some(SoccerLearnedPlan {
                    action: (*action).to_string(),
                    target_player: None,
                    target_point: Some(target),
                    mpc_replan: None,
                })
            })
            .collect()
    }

    fn learned_shot_target_point_for_plan(
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        label: &str,
        action_label: &str,
    ) -> Option<Vec2> {
        let player = snapshot
            .players
            .iter()
            .find(|player| player.id == player_id)?;
        let position = snapshot
            .player_position(player_id)
            .unwrap_or(player.position);
        let velocity = snapshot
            .player_velocity(player_id)
            .unwrap_or(player.velocity);
        let normalized = normalize_soccer_action_label(label);
        let first_time = matches!(normalized, "first-time-shot" | "first-time-header");
        let finish_skill = if normalized == "first-time-header" {
            aerial_duel_skill_from_snapshot(player)
        } else {
            (ability01(
                player
                    .skills
                    .right_foot_shot_power
                    .max(player.skills.left_foot_shot_power),
            ) * 0.62
                + ability01(player.skills.shooting) * 0.26
                + ability01(player.skills.first_touch) * 0.12)
                .clamp(0.0, 1.0)
        };
        let power =
            learned_discretized_kick_power_for_action_label(action_label).unwrap_or_else(|| {
                if first_time {
                    shot_power_for_finish_skill(finish_skill)
                } else {
                    shot_power_for_skill(ability01(player.skills.shooting))
                }
            });
        let shot_speed = shot_speed_yps_from_power(power, &player.skills);
        let nearest_opponent_distance = snapshot
            .players
            .iter()
            .filter(|opponent| opponent.team == team.other())
            .map(|opponent| {
                snapshot
                    .player_position(opponent.id)
                    .unwrap_or(opponent.position)
                    .distance(position)
            })
            .fold(f64::INFINITY, f64::min);
        Some(
            shot_mpc_accuracy_estimate_for_snapshot(
                snapshot,
                player.id,
                team,
                &player.skills,
                player.fatigue,
                position,
                velocity,
                shot_speed,
                first_time,
                pressure_from_nearest_distance(nearest_opponent_distance),
                None,
            )
            .target_point
            .clamp_to_pitch(snapshot.field_width, snapshot.field_length),
        )
    }

    fn neural_mcts_shot_variant_candidate_plans(
        snapshot: &WorldSnapshot,
        player_id: usize,
        team: Team,
        label: &str,
        candidate_label: &str,
    ) -> Vec<SoccerLearnedPlan> {
        let fallback_target = Some(Vec2::new(
            snapshot.field_width * 0.5,
            team.goal_y(snapshot.field_length),
        ));
        let target_point = Self::learned_shot_target_point_for_plan(
            snapshot,
            player_id,
            team,
            label,
            candidate_label,
        )
        .or_else(|| fallback_target);
        let mut plans = Vec::with_capacity(
            1 + if dd_soccer_enable_discretized_kick() {
                neural_mcts_kick_power_candidate_limit()
            } else {
                0
            },
        );
        let exact_bucket =
            learned_discretized_kick_speed_bucket_for_action_label(candidate_label).is_some();
        plans.push(SoccerLearnedPlan {
            action: if exact_bucket {
                candidate_label.to_string()
            } else {
                label.to_string()
            },
            target_player: None,
            target_point,
            mpc_replan: None,
        });
        if dd_soccer_enable_discretized_kick() && !exact_bucket {
            plans.extend(
                NEURAL_MCTS_SHOT_POWER_BUCKETS
                    .iter()
                    .copied()
                    .take(neural_mcts_kick_power_candidate_limit())
                    .filter_map(|bucket| {
                        learned_discretized_kick_candidate_label(label, bucket).map(|action| {
                            let target_point = Self::learned_shot_target_point_for_plan(
                                snapshot, player_id, team, label, &action,
                            )
                            .or_else(|| fallback_target);
                            SoccerLearnedPlan {
                                action,
                                target_player: None,
                                target_point,
                                mpc_replan: None,
                            }
                        })
                    }),
            );
        }
        // ACTOR-OWNED SHOT PLACEMENT (default-OFF, byte-identical when off): fan the shot into one
        // sibling plan per goal-mouth spot so the learned critic SCORES each aim independently and the
        // actor selects the placement it values most (honored at execution). Off ⇒ no extra plans ⇒
        // identical candidate set. Siblings share the "shoot" label (the scorer ranks per-plan, not
        // per-label) and differ only by `target_point`.
        if dd_soccer_enable_actor_shot_placement() {
            let goalmouth = shot_goalmouth_target_points(
                snapshot.field_width,
                snapshot.field_length,
                snapshot.goal_width,
                team,
            );
            plans.reserve(goalmouth.len());
            for aim in goalmouth {
                plans.push(SoccerLearnedPlan {
                    action: label.to_string(),
                    target_player: None,
                    target_point: Some(aim),
                    mpc_replan: None,
                });
            }
            if std::env::var("DD_SOCCER_SHOTPLACE_DIAG").is_ok() {
                eprintln!(
                    "SHOTPLACE_DIAG label={label} added_placement_variants={} total_plans={}",
                    goalmouth.len(),
                    plans.len()
                );
            }
        }
        plans
    }

    fn neural_mcts_technical_action_label(action: &str) -> bool {
        if learned_discretized_kick_speed_bucket_for_action_label(action).is_some() {
            return true;
        }
        let normalized = normalize_soccer_action_label(action);
        matches!(normalized, "first-time-shot")
            || (normalized != "dribble" && is_dribble_action_label(normalized))
    }

    fn neural_authoritative_allows_player(
        mode: SoccerNeuralBlendMode,
        snapshot: &WorldSnapshot,
        player_id: usize,
    ) -> bool {
        if mode != SoccerNeuralBlendMode::Authoritative
            || !neural_authoritative_on_ball_only_enabled()
        {
            return true;
        }
        snapshot.ball.holder == Some(player_id)
    }

    fn neural_mcts_technical_mpc_execution_bonus(
        snapshot: &WorldSnapshot,
        player_id: usize,
        plan: &SoccerLearnedPlan,
    ) -> f64 {
        let label = normalize_soccer_action_label(&plan.action);
        if pass_like_action_flight(label).is_some()
            || !Self::neural_mcts_technical_action_label(label)
        {
            return 0.0;
        }
        let weight = neural_mcts_technical_mpc_execution_weight();
        if weight <= 0.0 {
            return 0.0;
        }
        Self::learned_plan_mpc_execution_probability(snapshot, player_id, plan)
            .map(|probability| neural_mcts_mpc_execution_probability_bonus(probability, weight))
            .unwrap_or(0.0)
    }

    fn neural_mcts_candidate_mpc_bonus(
        snapshot: &WorldSnapshot,
        player_id: usize,
        plan: &SoccerLearnedPlan,
        transition: &SoccerLearningTransition,
    ) -> f64 {
        neural_mcts_pass_mpc_candidate_bonus(transition)
            + neural_mcts_shot_mpc_candidate_bonus(transition)
            + Self::neural_mcts_technical_mpc_execution_bonus(snapshot, player_id, plan)
            + neural_mcts_pitch_value_candidate_bonus(snapshot, transition)
    }

    fn neural_mcts_candidate_plan_is_executable(
        snapshot: &WorldSnapshot,
        player_id: usize,
        plan: &SoccerLearnedPlan,
    ) -> bool {
        if Self::learned_plan_needs_mpc_replan(snapshot, player_id, plan) {
            return false;
        }
        let label = normalize_soccer_action_label(&plan.action);
        if matches!(label, "shoot" | "first-time-shot" | "first-time-header") {
            return true;
        }
        let Some(probability) =
            Self::learned_plan_mpc_execution_probability(snapshot, player_id, plan)
        else {
            return true;
        };
        neural_mcts_replan_safe_execution_probability(label, probability)
    }

    fn neural_mcts_transition_context_is_executable(transition: &SoccerLearningTransition) -> bool {
        let label = normalize_soccer_action_label(&transition.action);
        if pass_like_action_flight(label).is_some() {
            return Self::neural_mcts_pass_transition_context_is_executable(transition);
        }
        if is_dribble_action_label(label) {
            return Self::neural_mcts_dribble_transition_context_is_executable(transition);
        }
        if learned_discretized_kick_speed_bucket_for_action_label(&transition.action).is_some()
            && matches!(label, "shoot" | "first-time-shot")
        {
            return neural_mcts_shot_bucket_has_quality_prior(transition);
        }
        true
    }

    fn neural_mcts_pass_transition_context_is_executable(
        transition: &SoccerLearningTransition,
    ) -> bool {
        let label = normalize_soccer_action_label(&transition.action);
        if !neural_mcts_replan_safe_execution_probability(
            label,
            transition.decision_context.chosen_action_mpc_feasibility,
        ) {
            return false;
        }
        if label == "aerial-pass" && !neural_mcts_aerial_pass_candidates_enabled() {
            return false;
        }
        match neural_mcts_pass_mpc_candidate_margin(transition) {
            Some(margin) => margin > 0.0,
            None => false,
        }
    }

    fn neural_mcts_dribble_transition_context_is_executable(
        transition: &SoccerLearningTransition,
    ) -> bool {
        let label = normalize_soccer_action_label(&transition.action);
        if !neural_mcts_replan_safe_execution_probability(
            label,
            transition.decision_context.chosen_action_mpc_feasibility,
        ) {
            return false;
        }
        soccer_actor_mcts_distillation_technical_trace(transition)
    }

    fn neural_mcts_candidate_is_pass_like(candidate: &SoccerNeuralMctsCandidate) -> bool {
        pass_like_action_flight(&candidate.label).is_some()
    }

    fn neural_mcts_candidate_is_dribble_like(candidate: &SoccerNeuralMctsCandidate) -> bool {
        is_dribble_action_label(&candidate.label)
    }

    fn neural_mcts_pass_like_floor_cutoff(
        candidates: &[SoccerNeuralMctsCandidate],
        best_non_pass_score: f64,
    ) -> Option<f64> {
        let min_pass_like = neural_mcts_min_pass_like_root_candidates();
        if min_pass_like == 0 || !best_non_pass_score.is_finite() {
            return None;
        }
        let max_regression = neural_mcts_family_floor_max_score_regression();
        if max_regression <= 0.0 || !max_regression.is_finite() {
            return None;
        }
        let mut scores = candidates
            .iter()
            .filter(|candidate| Self::neural_mcts_candidate_is_pass_like(candidate))
            .filter_map(|candidate| {
                (candidate.score.is_finite()
                    && candidate.score + max_regression >= best_non_pass_score)
                    .then_some(candidate.score)
            })
            .collect::<Vec<_>>();
        if scores.len() < min_pass_like {
            return None;
        }
        scores.sort_by(|a, b| b.total_cmp(a));
        scores.get(min_pass_like - 1).copied()
    }

    fn apply_neural_mcts_pass_like_margin_gate(candidates: &mut Vec<SoccerNeuralMctsCandidate>) {
        let margin = neural_mcts_pass_like_non_pass_margin();
        if margin <= 0.0 || candidates.len() < 2 {
            return;
        }
        let best_non_pass_score = candidates
            .iter()
            .filter(|candidate| !Self::neural_mcts_candidate_is_pass_like(candidate))
            .map(|candidate| candidate.score)
            .fold(f64::NEG_INFINITY, f64::max);
        if !best_non_pass_score.is_finite() {
            return;
        }
        let required_score = best_non_pass_score + margin;
        let floor_cutoff =
            Self::neural_mcts_pass_like_floor_cutoff(candidates, best_non_pass_score);
        candidates.retain(|candidate| {
            !Self::neural_mcts_candidate_is_pass_like(candidate)
                || candidate.score >= required_score
                || floor_cutoff.is_some_and(|cutoff| candidate.score >= cutoff)
        });
    }

    fn apply_neural_mcts_pass_like_margin_gate_for_blend(
        blend: SoccerNeuralBlendConfig,
        candidates: &mut Vec<SoccerNeuralMctsCandidate>,
    ) {
        if blend.mcts_enabled {
            Self::apply_neural_mcts_pass_like_margin_gate(candidates);
        }
    }

    fn neural_mcts_action_from_candidates(
        blend: SoccerNeuralBlendConfig,
        candidates: &[SoccerNeuralMctsCandidate],
        draw: f64,
    ) -> Option<SoccerPolicyActionChoice> {
        if !blend.mcts_enabled {
            return None;
        }
        let candidate_count = blend.sanitized_mcts_candidates().min(candidates.len());
        if candidate_count < 2 {
            return None;
        }
        let simulations = blend.sanitized_mcts_simulations();
        let exploration = blend.sanitized_mcts_exploration();
        let all_candidates = candidates;
        let neural_mcts_candidate_count = all_candidates.len().min(u32::MAX as usize) as u32;
        let neural_mcts_discretized_kick_candidate_count = all_candidates
            .iter()
            .filter(|candidate| {
                learned_discretized_kick_speed_bucket_for_action_label(&candidate.label).is_some()
            })
            .count()
            .min(u32::MAX as usize)
            as u32;
        let neural_mcts_dribble_candidate_count = all_candidates
            .iter()
            .filter(|candidate| Self::neural_mcts_candidate_is_dribble_like(candidate))
            .count()
            .min(u32::MAX as usize) as u32;
        let candidates = Self::neural_mcts_root_candidates(all_candidates, candidate_count);
        let neural_mcts_root_discretized_kick_candidate_count = candidates
            .iter()
            .filter(|candidate| {
                learned_discretized_kick_speed_bucket_for_action_label(&candidate.label).is_some()
            })
            .count()
            .min(u32::MAX as usize)
            as u32;
        let neural_mcts_root_dribble_candidate_count = candidates
            .iter()
            .filter(|candidate| Self::neural_mcts_candidate_is_dribble_like(candidate))
            .count()
            .min(u32::MAX as usize) as u32;
        let min_score = candidates
            .iter()
            .map(|candidate| candidate.score)
            .fold(f64::INFINITY, f64::min);
        let max_score = candidates
            .iter()
            .map(|candidate| candidate.score)
            .fold(f64::NEG_INFINITY, f64::max);
        if !min_score.is_finite() || !max_score.is_finite() {
            return None;
        }
        let score_span = (max_score - min_score).abs();
        let mut raw_priors = Vec::with_capacity(candidate_count);
        let mut prior_sum = 0.0;
        for (index, candidate) in candidates.iter().enumerate() {
            let rank_floor = 0.05 / (index as f64 + 1.0);
            let candidate_prior = if candidate.prior.is_finite() {
                candidate.prior.max(0.0)
            } else {
                0.0
            };
            let raw = candidate_prior + rank_floor;
            raw_priors.push(raw);
            prior_sum += raw;
        }
        let uniform_prior = 1.0 / candidate_count as f64;
        let mut nodes = candidates
            .iter()
            .zip(raw_priors.iter())
            .map(|(candidate, raw_prior)| {
                let value_estimate = if score_span > 1e-9 {
                    (((candidate.score - min_score) / score_span) * 2.0 - 1.0).clamp(-1.0, 1.0)
                } else {
                    0.0
                };
                SoccerNeuralMctsNode {
                    label: candidate.label.clone(),
                    plan: candidate.plan.clone(),
                    raw_score: candidate.score,
                    value_estimate,
                    prior: if prior_sum > 1e-9 {
                        raw_prior / prior_sum
                    } else {
                        uniform_prior
                    },
                    q_visits: candidate.q_visits,
                    search_visits: 0,
                    total_value: 0.0,
                }
            })
            .collect::<Vec<_>>();

        for _ in 0..simulations {
            let total_visits = nodes
                .iter()
                .map(|node| f64::from(node.search_visits))
                .sum::<f64>()
                .max(1.0);
            let sqrt_total = total_visits.sqrt();
            let mut best_index = 0usize;
            let mut best_puct = f64::NEG_INFINITY;
            for (index, node) in nodes.iter().enumerate() {
                let exploit = node.mean_value();
                let explore =
                    exploration * node.prior * sqrt_total / (1.0 + f64::from(node.search_visits));
                let puct = exploit + explore;
                let replace = puct
                    .total_cmp(&best_puct)
                    .then_with(|| node.raw_score.total_cmp(&nodes[best_index].raw_score))
                    .then_with(|| nodes[best_index].q_visits.cmp(&node.q_visits))
                    .is_gt();
                if replace {
                    best_index = index;
                    best_puct = puct;
                }
            }
            let rollout_value = nodes[best_index].value_estimate;
            nodes[best_index].total_value += rollout_value;
            nodes[best_index].search_visits = nodes[best_index].search_visits.saturating_add(1);
        }

        nodes.sort_by(|a, b| {
            b.search_visits
                .cmp(&a.search_visits)
                .then_with(|| b.mean_value().total_cmp(&a.mean_value()))
                .then_with(|| b.raw_score.total_cmp(&a.raw_score))
                .then_with(|| a.q_visits.cmp(&b.q_visits))
                .then_with(|| a.label.cmp(&b.label))
        });
        let sampleable_count = nodes.len().min(POLICY_SELECTION_TOP_RANK_LIMIT);
        Self::ensure_sampleable_discretized_kick_nodes(&mut nodes, sampleable_count);
        let candidate_count = nodes.len().min(POLICY_SELECTION_TOP_RANK_LIMIT);
        if candidate_count == 0 {
            return None;
        }
        let selection_floor = neural_mcts_discretized_kick_selection_floor();
        let dribble_floor_rank = Self::dribble_selection_floor_rank(&nodes, candidate_count, draw);
        let discretized_floor_rank =
            Self::discretized_kick_selection_floor_rank(&nodes, candidate_count, draw);
        let technical_floor_rank =
            Self::technical_selection_floor_rank(&nodes, candidate_count, draw);
        let selected_rank = dribble_floor_rank
            .or(discretized_floor_rank)
            .or(technical_floor_rank)
            .unwrap_or_else(|| {
                let adjusted_draw = if selection_floor > 1e-9
                    && draw.is_finite()
                    && draw >= selection_floor
                    && Self::has_selectable_discretized_kick_node(&nodes, candidate_count)
                {
                    ((draw - selection_floor) / (1.0 - selection_floor)).clamp(0.0, 1.0)
                } else {
                    draw
                };
                soccer_policy_weighted_rank_index(candidate_count, adjusted_draw)
            });
        Self::maybe_log_neural_mcts_dribble_diagnostic(
            all_candidates,
            &candidates,
            &nodes,
            candidate_count,
            dribble_floor_rank,
            selected_rank,
        );
        nodes.get(selected_rank).map(|node| {
            let mut plan = node.plan.clone();
            if selected_rank == 0 {
                if let (Some(original), Some(plan)) = (candidates.first(), plan.as_mut()) {
                    if plan.mpc_replan.is_none() {
                        plan.mpc_replan = Self::neural_mcts_policy_improvement_replan(
                            original,
                            node,
                            candidate_count,
                        );
                    }
                }
            }
            SoccerPolicyActionChoice {
                label: node.label.clone(),
                plan,
                behavior_probability: soccer_policy_rank_probability(
                    candidate_count,
                    selected_rank,
                ),
                neural_mcts_selected: true,
                neural_mcts_candidate_count,
                neural_mcts_discretized_kick_candidate_count,
                neural_mcts_root_discretized_kick_candidate_count,
                neural_mcts_dribble_candidate_count,
                neural_mcts_root_dribble_candidate_count,
            }
        })
    }

    fn maybe_log_neural_mcts_dribble_diagnostic(
        all_candidates: &[SoccerNeuralMctsCandidate],
        root_candidates: &[SoccerNeuralMctsCandidate],
        nodes: &[SoccerNeuralMctsNode],
        candidate_count: usize,
        dribble_floor_rank: Option<usize>,
        selected_rank: usize,
    ) {
        let interval = neural_mcts_dribble_diagnostic_interval();
        if interval == 0 {
            return;
        }
        #[cfg(not(test))]
        let sample_index = {
            use std::sync::atomic::{AtomicU64, Ordering};
            static SAMPLE: AtomicU64 = AtomicU64::new(0);
            SAMPLE.fetch_add(1, Ordering::Relaxed).saturating_add(1)
        };
        #[cfg(test)]
        let sample_index = 1;
        if sample_index != 1 && sample_index % interval != 0 {
            return;
        }

        let best_score = root_candidates
            .iter()
            .filter_map(|candidate| candidate.score.is_finite().then_some(candidate.score))
            .max_by(|a, b| a.total_cmp(b));
        let best_dribble_score = all_candidates
            .iter()
            .filter(|candidate| Self::neural_mcts_candidate_is_dribble_like(candidate))
            .filter_map(|candidate| candidate.score.is_finite().then_some(candidate.score))
            .max_by(|a, b| a.total_cmp(b));
        let best_root_dribble_score = root_candidates
            .iter()
            .filter(|candidate| Self::neural_mcts_candidate_is_dribble_like(candidate))
            .filter_map(|candidate| candidate.score.is_finite().then_some(candidate.score))
            .max_by(|a, b| a.total_cmp(b));
        let max_regression = neural_mcts_dribble_selection_max_score_regression();
        let eligible_root_dribbles = nodes
            .iter()
            .take(candidate_count.min(nodes.len()))
            .filter(|node| {
                best_score.is_some_and(|best| {
                    Self::dribble_selection_floor_eligible_node(node, best, max_regression)
                })
            })
            .count();
        let selected_label = nodes
            .get(selected_rank)
            .map(|node| node.label.as_str())
            .unwrap_or("none");
        let selected_is_dribble =
            is_dribble_action_label(normalize_soccer_action_label(selected_label));
        let score_text = |score: Option<f64>| {
            score
                .map(|value| format!("{value:.4}"))
                .unwrap_or_else(|| "none".to_string())
        };
        let dribble_gap = match (best_score, best_dribble_score) {
            (Some(best), Some(dribble)) => format!("{:.4}", best - dribble),
            _ => "none".to_string(),
        };

        println!(
            "neural_mcts_dribble_diagnostic sample={} candidates={} dribble_candidates={} root_candidates={} root_dribble_candidates={} eligible_root_dribbles={} best_score={} best_dribble_score={} best_root_dribble_score={} dribble_score_gap={} dribble_floor_rank={} selected_rank={} selected_label={} selected_is_dribble={}",
            sample_index,
            all_candidates.len(),
            all_candidates
                .iter()
                .filter(|candidate| Self::neural_mcts_candidate_is_dribble_like(candidate))
                .count(),
            root_candidates.len(),
            root_candidates
                .iter()
                .filter(|candidate| Self::neural_mcts_candidate_is_dribble_like(candidate))
                .count(),
            eligible_root_dribbles,
            score_text(best_score),
            score_text(best_dribble_score),
            score_text(best_root_dribble_score),
            dribble_gap,
            dribble_floor_rank
                .map(|rank| rank.to_string())
                .unwrap_or_else(|| "none".to_string()),
            selected_rank,
            selected_label,
            selected_is_dribble as u8,
        );
    }

    fn dribble_selection_floor_rank(
        nodes: &[SoccerNeuralMctsNode],
        candidate_count: usize,
        draw: f64,
    ) -> Option<usize> {
        let floor = neural_mcts_dribble_selection_floor();
        if floor <= 1e-9 || !draw.is_finite() || draw >= floor {
            return None;
        }
        let candidate_count = candidate_count.min(nodes.len());
        if candidate_count == 0 {
            return None;
        }
        let best_score = nodes[..candidate_count]
            .iter()
            .map(|node| node.raw_score)
            .fold(f64::NEG_INFINITY, f64::max);
        if !best_score.is_finite() {
            return None;
        }
        let max_regression = neural_mcts_dribble_selection_max_score_regression();
        if max_regression <= 0.0 || !max_regression.is_finite() {
            return None;
        }
        let rank_weights = soccer_policy_top_rank_weights();
        let mut eligible = [(0usize, 0.0f64); POLICY_SELECTION_TOP_RANK_LIMIT];
        let mut eligible_count = 0usize;
        let mut total = 0.0;
        for rank in 0..candidate_count
            .min(nodes.len())
            .min(POLICY_SELECTION_TOP_RANK_LIMIT)
        {
            let node = &nodes[rank];
            if !Self::dribble_selection_floor_eligible_node(node, best_score, max_regression) {
                continue;
            }
            let weight = rank_weights[rank].max(0.0);
            if weight <= 0.0 {
                continue;
            }
            eligible[eligible_count] = (rank, weight);
            eligible_count += 1;
            total += weight;
        }
        if eligible_count == 0 || !total.is_finite() || total <= 1e-9 {
            return None;
        }
        let mut threshold = (draw / floor).clamp(0.0, 1.0 - f64::EPSILON) * total;
        for (rank, weight) in eligible[..eligible_count].iter().copied() {
            if threshold < weight {
                return Some(rank);
            }
            threshold -= weight;
        }
        Some(eligible[eligible_count - 1].0)
    }

    fn dribble_selection_floor_eligible_node(
        node: &SoccerNeuralMctsNode,
        best_score: f64,
        max_regression: f64,
    ) -> bool {
        if !node.raw_score.is_finite()
            || !best_score.is_finite()
            || !max_regression.is_finite()
            || max_regression < 0.0
            || node.raw_score + max_regression < best_score
        {
            return false;
        }
        is_dribble_action_label(normalize_soccer_action_label(&node.label))
    }

