    /// Record the realized reception direction separately from launch intent.
    /// This exposes under-hit forward balls while the dedicated intent counters
    /// retain a valid completed/attempted rate for each launch direction.
    fn stat_pass_completed_direction(&mut self, team: Team, completed_forward_yards: f64) {
        if completed_forward_yards > 1.25 {
            match team {
                Team::Home => self.stats.passes_completed_forward_home += 1,
                Team::Away => self.stats.passes_completed_forward_away += 1,
            }
        } else if completed_forward_yards < -1.25 {
            match team {
                Team::Home => self.stats.passes_completed_backward_home += 1,
                Team::Away => self.stats.passes_completed_backward_away += 1,
            }
        } else {
            match team {
                Team::Home => self.stats.passes_completed_lateral_home += 1,
                Team::Away => self.stats.passes_completed_lateral_away += 1,
            }
        }
        self.accumulate_pass_chain_metrics(team, completed_forward_yards);
    }

    fn stat_intentional_pass_completed_direction(
        &mut self,
        team: Team,
        intended_forward_yards: f64,
        completed_forward_yards: f64,
    ) {
        if intended_forward_yards > 1.25 {
            match team {
                Team::Home => self.stats.intentional_passes_completed_forward_home += 1,
                Team::Away => self.stats.intentional_passes_completed_forward_away += 1,
            }
        } else if intended_forward_yards < -1.25 {
            match team {
                Team::Home => self.stats.intentional_passes_completed_backward_home += 1,
                Team::Away => self.stats.intentional_passes_completed_backward_away += 1,
            }
        } else {
            match team {
                Team::Home => self.stats.intentional_passes_completed_lateral_home += 1,
                Team::Away => self.stats.intentional_passes_completed_lateral_away += 1,
            }
        }
        match team {
            Team::Home => {
                self.stats.intentional_completed_pass_gain_yards_home += completed_forward_yards
            }
            Team::Away => {
                self.stats.intentional_completed_pass_gain_yards_away += completed_forward_yards
            }
        }
    }

    /// Fold one COMPLETED pass into the learning-progress metrics: add its forward yards to the
    /// running gain total and extend the current consecutive-pass chain. A pass by a different
    /// team finalises the previous chain first (a turnover between the two completions).
    fn accumulate_pass_chain_metrics(&mut self, team: Team, forward_yards: f64) {
        match team {
            Team::Home => self.stats.completed_pass_gain_yards_home += forward_yards,
            Team::Away => self.stats.completed_pass_gain_yards_away += forward_yards,
        }
        if self.pass_chain_meter.team != Some(team) {
            self.finalize_pass_chain_metrics();
            self.pass_chain_meter.team = Some(team);
        }
        self.pass_chain_meter.passes += 1;
        self.pass_chain_meter.gain_yards += forward_yards;
    }

    /// Finalise the current consecutive-pass chain into [`MatchStats`]: a chain of two or more
    /// completed passes counts once, contributes its total gained yards, and is flagged if it
    /// ended in a NET yards loss. Idempotent — resets the meter, so calling it again (from
    /// another end signal) is a no-op.
    pub(crate) fn finalize_pass_chain_metrics(&mut self) {
        let meter = std::mem::take(&mut self.pass_chain_meter);
        self.stats.fold_pass_chain(&meter);
    }

    /// Whether a pass played from `origin` by `team` started in that team's OWN half.
    fn pass_from_own_half(&self, team: Team, origin: Vec2) -> bool {
        pass_origin_in_own_half(team, origin, self.config.field_length_yards)
    }

    /// Whether the pass just played by `player_id` (from `origin` toward `target`) is the panicked
    /// backward/square ball of an isolated attacking carrier — a Forward / winger in the ATTACKING
    /// half with NO teammate ahead who recycled backward instead of driving / holding up. This is
    /// the world-state analogue of [`isolated_attacking_carrier_drive_mode`]'s precondition, used
    /// to emit the [`SoccerRewardEventKind::IsolatedCarrierPanicBackPass`] training penalty.
    pub(crate) fn isolated_carrier_panic_back_pass(
        &self,
        player_id: usize,
        origin: Vec2,
        target: Vec2,
        attempt_own_half: bool,
    ) -> bool {
        if attempt_own_half {
            return false;
        }
        let Some(passer) = self.players.get(player_id) else {
            return false;
        };
        let field_width = self.config.field_width_yards;
        let is_attacker = passer.role == PlayerRole::Forward
            || is_outside_midfielder_role(passer.role, passer.home_position.x, field_width);
        if !is_attacker {
            return false;
        }
        let attack_dir = passer.team.attack_dir();
        // Meaningfully backward (not a flat square ball within the dead-band).
        let forward_yards = (target.y - origin.y) * attack_dir;
        if forward_yards >= -BACKWARD_PASS_MIN_FORWARD_YARDS {
            return false;
        }
        // No teammate was ahead of the ball — the isolated picture.
        let teammate_ahead = self.players.iter().any(|other| {
            other.team == passer.team
                && other.id != player_id
                && other.role != PlayerRole::Goalkeeper
                && (other.position.y - origin.y) * attack_dir > 0.0
        });
        !teammate_ahead
    }

