/// A quick, progressive GROUND pass into an advanced, open teammate is most valuable in a
/// short band of 5-15 yards. This is the "knock it forward to feet, keep the ball moving"
/// distance: long enough to break a line, short enough to be a high-percentage one/two-touch ball.
/// The forward-open value peaks across this band and tapers outside it.
const QUICK_FORWARD_PASS_MIN_YARDS: f64 = 5.0;
const QUICK_FORWARD_PASS_IDEAL_YARDS: f64 = 10.0;
const QUICK_FORWARD_PASS_MAX_YARDS: f64 = 15.0;
/// Soft taper (yards) applied to distances outside the [min, max] band so a 3 yd or 18 yd
/// forward ball still carries some value rather than dropping to a hard zero.
const QUICK_FORWARD_PASS_BAND_FALLOFF_YARDS: f64 = 5.0;

/// In-band distance fit [0,1] for the quick forward ground-pass value: 1.0 across the
/// 5-15 yd sweet spot, tapering linearly to 0 over [`QUICK_FORWARD_PASS_BAND_FALLOFF_YARDS`]
/// on either side. A pass shorter than the band or much longer is worth progressively less.
pub(crate) fn quick_forward_pass_band_fit(distance_yards: f64) -> f64 {
    if distance_yards >= QUICK_FORWARD_PASS_MIN_YARDS
        && distance_yards <= QUICK_FORWARD_PASS_MAX_YARDS
    {
        return 1.0;
    }
    let shortfall = (QUICK_FORWARD_PASS_MIN_YARDS - distance_yards).max(0.0);
    let overshoot = (distance_yards - QUICK_FORWARD_PASS_MAX_YARDS).max(0.0);
    let outside = shortfall.max(overshoot);
    (1.0 - outside / QUICK_FORWARD_PASS_BAND_FALLOFF_YARDS).clamp(0.0, 1.0)
}

pub(crate) fn pass_completion_primary_score_penalty(
    expected_completion: f64,
    forward_yards: f64,
    yards_to_goal: f64,
    field_length: f64,
) -> f64 {
    let completion = expected_completion.clamp(0.0, 1.0);
    let shortfall = (PASS_COMPLETION_PRIMARY_SCORE_FLOOR - completion).max(0.0);
    if shortfall <= 0.0 {
        return 0.0;
    }
    let final_third_forward =
        forward_yards > 1.25 && yards_to_goal <= (field_length / 3.0).max(1.0);
    let relief = if final_third_forward {
        PASS_COMPLETION_PRIMARY_FINAL_THIRD_RELIEF
    } else {
        1.0
    };
    (shortfall / PASS_COMPLETION_PRIMARY_SCORE_FLOOR.max(1e-6))
        * PASS_COMPLETION_PRIMARY_MAX_SCORE_PENALTY
        * relief
}

pub(crate) fn safe_progressive_pass_score_bonus(
    expected_completion: f64,
    forward_yards: f64,
    distance_yards: f64,
) -> f64 {
    let completion_fit = ((expected_completion.clamp(0.0, 1.0)
        - SAFE_PROGRESSIVE_PASS_COMPLETION_FLOOR)
        / (SAFE_PROGRESSIVE_PASS_COMPLETION_FULL - SAFE_PROGRESSIVE_PASS_COMPLETION_FLOOR)
            .max(1e-6))
    .clamp(0.0, 1.0);
    let forward_fit = ((forward_yards - PROGRESSIVE_FLOOR_OUTLET_MIN_FORWARD_YARDS)
        / (SAFE_PROGRESSIVE_PASS_FORWARD_FULL_YARDS - PROGRESSIVE_FLOOR_OUTLET_MIN_FORWARD_YARDS)
            .max(1e-6))
    .clamp(0.0, 1.0);
    completion_fit
        * forward_fit
        * quick_forward_pass_band_fit(distance_yards)
        * SAFE_PROGRESSIVE_PASS_SCORE_BONUS
}

fn retained_forward_target_utility_scale() -> f64 {
    #[cfg(test)]
    {
        retained_forward_target_utility_scale_from_env()
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<f64> = OnceLock::new();
        *V.get_or_init(retained_forward_target_utility_scale_from_env)
    }
}

fn retained_forward_target_utility_scale_from_env() -> f64 {
    std::env::var("DD_SOCCER_RETAINED_FORWARD_TARGET_UTILITY_SCALE")
        .ok()
        .and_then(|raw| raw.trim().parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.0)
        .clamp(0.0, 8.0)
}

pub(crate) fn retained_forward_target_utility_bonus(
    quality: &PassTargetQuality,
    forward_yards: f64,
    distance_yards: f64,
) -> f64 {
    let scale = retained_forward_target_utility_scale();
    if scale <= 1e-9 || forward_yards <= COMPLETED_FORWARD_PASS_COUNT_MIN_YARDS {
        return 0.0;
    }
    let completion = quality.expected_completion.clamp(0.0, 1.0);
    let receipt = quality.mpc_receipt_probability.clamp(0.0, 1.0);
    let safe_receipt = completion * 0.68 + receipt * 0.32;
    let retention_fit = ((safe_receipt - 0.44) / 0.34).clamp(0.0, 1.0);
    if retention_fit <= 0.0 {
        return 0.0;
    }
    let lane_safety = (1.0 - quality.lane_interception_risk.clamp(0.0, 1.0)).clamp(0.0, 1.0);
    let lane_fit = ((lane_safety - 0.34) / 0.46).clamp(0.0, 1.0);
    if lane_fit <= 0.0 {
        return 0.0;
    }
    let forward_fit =
        ((forward_yards - COMPLETED_FORWARD_PASS_COUNT_MIN_YARDS) / 16.0).clamp(0.0, 1.0);
    let distance_fit = quick_forward_pass_band_fit(distance_yards)
        .max((1.0 - ((distance_yards - 18.0).max(0.0) / 28.0)).clamp(0.0, 0.75));
    scale * forward_fit * retention_fit * lane_fit * distance_fit
}

const FORWARD_OPTION_RECOGNITION_LATERAL_THRESHOLD: f64 = 0.58;
const FORWARD_OPTION_RECOGNITION_LATERAL_DEMOTION: f64 = 4.0;
const FORWARD_OPTION_LATERAL_PRESSURE_ESCAPE_MIN_PRESSURE: f64 = 0.70;
const FORWARD_OPTION_LATERAL_PRESSURE_ESCAPE_MIN_COMPLETION: f64 = 0.72;
const FORWARD_OPTION_LATERAL_PRESSURE_ESCAPE_MAX_DISTANCE: f64 = 14.0;
const FORWARD_OPTION_LATERAL_FINAL_THIRD_MAX_DISTANCE: f64 = 10.0;
const FORWARD_OPTION_LATERAL_FINAL_THIRD_MIN_COMPLETION: f64 = 0.66;

fn forward_option_lateral_demotion_enabled() -> bool {
    #[cfg(test)]
    {
        soccer_env_flag_enabled("DD_SOCCER_ENABLE_FORWARD_OPTION_RECOGNITION_LATERAL_DEMOTION")
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| {
            soccer_env_flag_enabled("DD_SOCCER_ENABLE_FORWARD_OPTION_RECOGNITION_LATERAL_DEMOTION")
        })
    }
}

pub(crate) fn forward_option_lateral_demotion_penalty(
    forward_yards: f64,
    best_forward_option_quality: f64,
    passer_pressure: f64,
    expected_completion: f64,
    distance_yards: f64,
    yards_to_goal: f64,
    field_length: f64,
    enabled: bool,
) -> f64 {
    if !enabled
        || !forward_yards.is_finite()
        || forward_yards.abs() > COMPLETED_FORWARD_PASS_COUNT_MIN_YARDS
        || best_forward_option_quality < FORWARD_OPTION_RECOGNITION_LATERAL_THRESHOLD
    {
        return 0.0;
    }
    let pressure_escape = passer_pressure >= FORWARD_OPTION_LATERAL_PRESSURE_ESCAPE_MIN_PRESSURE
        && expected_completion >= FORWARD_OPTION_LATERAL_PRESSURE_ESCAPE_MIN_COMPLETION
        && distance_yards <= FORWARD_OPTION_LATERAL_PRESSURE_ESCAPE_MAX_DISTANCE;
    if pressure_escape {
        return 0.0;
    }
    let final_third_combination = yards_to_goal <= field_length / 3.0
        && distance_yards <= FORWARD_OPTION_LATERAL_FINAL_THIRD_MAX_DISTANCE
        && expected_completion >= FORWARD_OPTION_LATERAL_FINAL_THIRD_MIN_COMPLETION;
    if final_third_combination {
        return 0.0;
    }
    (best_forward_option_quality - FORWARD_OPTION_RECOGNITION_LATERAL_THRESHOLD)
        * FORWARD_OPTION_RECOGNITION_LATERAL_DEMOTION
}

#[derive(Clone, Copy, Debug, Default)]
struct ForwardFloorOutletAssessment {
    actionable: bool,
    receiver_openness_for_score: f64,
    expected_completion_for_score: f64,
    quality_fit: f64,
    distance_fit: f64,
}

fn forward_floor_outlet_assessment(
    forward_yards: f64,
    distance_yards: f64,
    quality: &PassTargetQuality,
    require_reception_won: bool,
) -> ForwardFloorOutletAssessment {
    let half_open_forward = forward_yards >= HALF_OPEN_FORWARD_PASS_MIN_FORWARD_YARDS
        && quality.receiver_openness >= HALF_OPEN_FORWARD_PASS_MIN_OPENNESS;
    let lane_safe =
        !require_reception_won || quality.lane_interception_risk < PASS_LANE_DYNAMIC_RISK_HIGH;
    let receiver_openness_for_score = if half_open_forward {
        quality
            .receiver_openness
            .max(HALF_OPEN_FORWARD_PASS_SCORE_OPENNESS_FLOOR)
    } else {
        quality.receiver_openness
    };
    let expected_completion_for_score = if half_open_forward && lane_safe {
        quality
            .expected_completion
            .max(HALF_OPEN_FORWARD_PASS_COMPLETION_FLOOR)
    } else {
        quality.expected_completion
    };
    let upfield_fit = (forward_yards / QUICK_FORWARD_PASS_IDEAL_YARDS).clamp(0.0, 1.0);
    let quality_fit = (receiver_openness_for_score.clamp(0.0, 1.0) * 0.46
        + expected_completion_for_score.clamp(0.0, 1.0) * 0.32
        + quality.stride_fit.clamp(0.0, 1.0) * 0.12
        + upfield_fit * 0.10)
        .clamp(0.0, 1.0);
    let progressive_floor_outlet = forward_yards >= PROGRESSIVE_FLOOR_OUTLET_MIN_FORWARD_YARDS
        && distance_yards >= PROGRESSIVE_FLOOR_OUTLET_MIN_DISTANCE_YARDS;
    let completion_or_stride_fit = quality.expected_completion
        >= GOOD_FORWARD_OUTLET_MIN_RAW_COMPLETION
        || quality.stride_fit >= GOOD_FORWARD_OUTLET_MIN_STRIDE_FIT
        || expected_completion_for_score >= HALF_OPEN_FORWARD_PASS_COMPLETION_FLOOR;
    let actionable = progressive_floor_outlet
        && lane_safe
        && receiver_openness_for_score >= HALF_OPEN_FORWARD_PASS_MIN_OPENNESS
        && completion_or_stride_fit
        && quality_fit >= GOOD_FORWARD_OUTLET_MIN_QUALITY_FIT;

    if std::env::var("DBG_OUTLET").is_ok() && forward_yards > 10.0 && forward_yards < 14.0 {
        eprintln!("DBG_OUTLET fwd={forward_yards:.2} dist={distance_yards:.2} open={:.3} compl={:.3} lane_risk={:.3} stride={:.3} | lane_safe={lane_safe} half_open={half_open_forward} progressive={progressive_floor_outlet} open_for_score={receiver_openness_for_score:.3}>=0.30?{} compl_or_stride={completion_or_stride_fit} quality_fit={quality_fit:.3}>=0.34?{} => actionable={actionable}",
            quality.receiver_openness, quality.expected_completion, quality.lane_interception_risk, quality.stride_fit,
            receiver_openness_for_score >= HALF_OPEN_FORWARD_PASS_MIN_OPENNESS,
            quality_fit >= GOOD_FORWARD_OUTLET_MIN_QUALITY_FIT);
    }
    ForwardFloorOutletAssessment {
        actionable,
        receiver_openness_for_score,
        expected_completion_for_score,
        quality_fit,
        distance_fit: quick_forward_pass_band_fit(distance_yards),
    }
}

const PASS_TARGET_RISK_COMPLETION_WEIGHT: f64 = 0.34;
const PASS_TARGET_RISK_LANE_WEIGHT: f64 = 0.30;
const PASS_TARGET_RISK_MPC_RECEIPT_WEIGHT: f64 = 0.18;
const PASS_TARGET_RISK_BACKWARD_TRAFFIC_WEIGHT: f64 = 0.12;
const PASS_TARGET_RISK_AERIAL_BOUNDS_WEIGHT: f64 = 0.06;
const PASS_ROLE_RISK_DEFENDER_PENALTY_WEIGHT: f64 = 3.35;
const PASS_ROLE_RISK_MIDFIELDER_PENALTY_WEIGHT: f64 = 2.05;
const PASS_ROLE_RISK_FORWARD_PENALTY_WEIGHT: f64 = 1.15;
const PASS_ROLE_RISK_GOALKEEPER_PENALTY_WEIGHT: f64 = 3.85;
const PASS_ROLE_RISK_TACTICAL_RELIEF_MAX: f64 = 0.22;
const PASS_ROLE_RISK_FINAL_THIRD_RELIEF_MAX: f64 = 0.55;
const PASS_ROLE_RISK_FINAL_THIRD_PROGRESS_YARDS: f64 = 18.0;
const PASS_ROLE_RISK_FINAL_THIRD_BLEND_YARDS: f64 = 18.0;
const PASS_ROLE_RISK_FINAL_THIRD_ENTRY_BUFFER_YARDS: f64 = 6.0;
const PASS_ROLE_RISK_FINAL_THIRD_FORWARD_BONUS_WEIGHT: f64 = 1.35;
const PASS_ROLE_SAFETY_DEFENDER_BONUS_WEIGHT: f64 = 0.30;
const PASS_ROLE_SAFETY_MIDFIELDER_BONUS_WEIGHT: f64 = 0.18;
const PASS_ROLE_SAFETY_FORWARD_BONUS_WEIGHT: f64 = 0.07;
const PASS_ROLE_SAFETY_GOALKEEPER_BONUS_WEIGHT: f64 = 0.34;

#[derive(Clone, Copy, Debug, Default)]
struct PassRoleRiskScoreAdjustment {
    safety_bonus: f64,
    penalty: f64,
    forward_risk_bonus: f64,
}

fn pass_quality_unit_interval(value: f64) -> f64 {
    if value.is_finite() {
        value.clamp(0.0, 1.0)
    } else {
        0.0
    }
}

fn pass_target_risk_from_quality(quality: &PassTargetQuality) -> f64 {
    let completion_risk = 1.0 - pass_quality_unit_interval(quality.expected_completion);
    let mpc_receipt_risk = 1.0 - pass_quality_unit_interval(quality.mpc_receipt_probability);
    (completion_risk * PASS_TARGET_RISK_COMPLETION_WEIGHT
        + pass_quality_unit_interval(quality.lane_interception_risk) * PASS_TARGET_RISK_LANE_WEIGHT
        + mpc_receipt_risk * PASS_TARGET_RISK_MPC_RECEIPT_WEIGHT
        + pass_quality_unit_interval(quality.backward_path_traffic_risk)
            * PASS_TARGET_RISK_BACKWARD_TRAFFIC_WEIGHT
        + pass_quality_unit_interval(quality.long_aerial_bounds_risk)
            * PASS_TARGET_RISK_AERIAL_BOUNDS_WEIGHT)
        .clamp(0.0, 1.0)
}

fn pass_target_safety_from_quality(quality: &PassTargetQuality) -> f64 {
    1.0 - pass_target_risk_from_quality(quality)
}

fn pass_lane_dynamic_risk_score_penalty(
    lane_interception_risk: f64,
    appetite_risk_penalty_mult: f64,
    own_half: bool,
) -> f64 {
    let own_half_mult = if own_half {
        OWN_HALF_PASS_LANE_DYNAMIC_RISK_SCORE_MULT
    } else {
        1.0
    };
    pass_quality_unit_interval(lane_interception_risk)
        * PASS_LANE_DYNAMIC_RISK_SCORE_PENALTY
        * appetite_risk_penalty_mult.max(0.0)
        * own_half_mult
}

fn pass_role_risk_penalty_weight(role: PlayerRole) -> f64 {
    match role {
        PlayerRole::Goalkeeper => PASS_ROLE_RISK_GOALKEEPER_PENALTY_WEIGHT,
        PlayerRole::Defender => PASS_ROLE_RISK_DEFENDER_PENALTY_WEIGHT,
        PlayerRole::Midfielder => PASS_ROLE_RISK_MIDFIELDER_PENALTY_WEIGHT,
        PlayerRole::Forward => PASS_ROLE_RISK_FORWARD_PENALTY_WEIGHT,
    }
}

fn pass_role_safety_bonus_weight(role: PlayerRole) -> f64 {
    match role {
        PlayerRole::Goalkeeper => PASS_ROLE_SAFETY_GOALKEEPER_BONUS_WEIGHT,
        PlayerRole::Defender => PASS_ROLE_SAFETY_DEFENDER_BONUS_WEIGHT,
        PlayerRole::Midfielder => PASS_ROLE_SAFETY_MIDFIELDER_BONUS_WEIGHT,
        PlayerRole::Forward => PASS_ROLE_SAFETY_FORWARD_BONUS_WEIGHT,
    }
}

fn pass_role_final_third_forward_appetite(role: PlayerRole) -> f64 {
    match role {
        PlayerRole::Forward => 1.0,
        PlayerRole::Midfielder => 0.45,
        PlayerRole::Defender => 0.12,
        PlayerRole::Goalkeeper => 0.0,
    }
}

fn pass_final_third_forward_fit(
    role: PlayerRole,
    team: Team,
    origin: Vec2,
    field_length: f64,
    forward_yards: f64,
) -> f64 {
    if !field_length.is_finite() || field_length <= 0.0 || !forward_yards.is_finite() {
        return 0.0;
    }
    let forward_fit = (forward_yards / PASS_ROLE_RISK_FINAL_THIRD_PROGRESS_YARDS).clamp(0.0, 1.0);
    if forward_fit <= 0.0 {
        return 0.0;
    }
    let yards_to_goal = (team.goal_y(field_length) - origin.y).abs();
    let final_third_depth = (field_length / 3.0).max(1.0);
    if yards_to_goal > final_third_depth {
        return 0.0;
    }
    let final_third_fit = ((final_third_depth - yards_to_goal)
        + PASS_ROLE_RISK_FINAL_THIRD_ENTRY_BUFFER_YARDS)
        / PASS_ROLE_RISK_FINAL_THIRD_BLEND_YARDS;
    (pass_role_final_third_forward_appetite(role) * forward_fit * final_third_fit.clamp(0.0, 1.0))
        .clamp(0.0, 1.0)
}

fn pass_role_risk_score_adjustment(
    role: PlayerRole,
    team: Team,
    origin: Vec2,
    target: Vec2,
    field_length: f64,
    forward_yards: f64,
    quality: &PassTargetQuality,
    directive_risk_tolerance: f64,
) -> PassRoleRiskScoreAdjustment {
    let risk = pass_target_risk_from_quality(quality);
    let safety = 1.0 - risk;
    let final_third_forward_fit =
        pass_final_third_forward_fit(role, team, origin, field_length, forward_yards);
    let tactical_relief =
        pass_quality_unit_interval(directive_risk_tolerance) * PASS_ROLE_RISK_TACTICAL_RELIEF_MAX;
    let final_third_relief = final_third_forward_fit * PASS_ROLE_RISK_FINAL_THIRD_RELIEF_MAX;
    let risk_relief = (tactical_relief + final_third_relief).clamp(0.0, 0.68);
    let penalty = risk * pass_role_risk_penalty_weight(role) * (1.0 - risk_relief).max(0.32);
    let safety_bonus = safety * pass_role_safety_bonus_weight(role);
    let target_forward_yards = ((target.y - origin.y) * team.attack_dir()).max(0.0);
    let target_progress_fit =
        (target_forward_yards / PASS_ROLE_RISK_FINAL_THIRD_PROGRESS_YARDS).clamp(0.0, 1.0);
    let forward_risk_bonus = risk
        * final_third_forward_fit
        * target_progress_fit
        * PASS_ROLE_RISK_FINAL_THIRD_FORWARD_BONUS_WEIGHT;
    PassRoleRiskScoreAdjustment {
        safety_bonus,
        penalty,
        forward_risk_bonus,
    }
}

fn active_pass_role_risk_score_adjustment(
    role: PlayerRole,
    team: Team,
    origin: Vec2,
    target: Vec2,
    field_length: f64,
    forward_yards: f64,
    quality: &PassTargetQuality,
    directive_risk_tolerance: f64,
) -> PassRoleRiskScoreAdjustment {
    if !dd_soccer_enable_role_pass_risk_appetite() {
        return PassRoleRiskScoreAdjustment::default();
    }
    pass_role_risk_score_adjustment(
        role,
        team,
        origin,
        target,
        field_length,
        forward_yards,
        quality,
        directive_risk_tolerance,
    )
}

fn first_touch_shape_prior_for_snapshot(
    directive: &TeamTacticalDirective,
    team_shape: TeamShapeObservation,
    formation_lp_guidance: Option<&SoccerFormationLpPlayerGuidance>,
) -> f64 {
    let embedding_attack = directive
        .adversarial_embedding_attack_score
        .max(directive.neural_formation_attack_score)
        .clamp(0.0, 1.0);
    let overload = directive.attacking_overload_score.clamp(0.0, 1.0);
    let pass_priority = ((directive.pass_priority - 0.70) / 0.72).clamp(0.0, 1.0);
    let team_forward = (team_shape.forward_velocity_yps / 7.0).clamp(0.0, 1.0);
    let support_density = (team_shape.players_near_ball as f64 / 5.0).clamp(0.0, 1.0);
    let shape_width = (team_shape.spread_yards / 24.0).clamp(0.0, 1.0);
    let lp = formation_lp_guidance
        .map(|guidance| {
            let target_forward = if guidance.target.y.is_finite() && guidance.current.y.is_finite()
            {
                ((guidance.target.y - guidance.current.y) * directive.team.attack_dir() / 8.0)
                    .clamp(0.0, 1.0)
            } else {
                0.0
            };
            let local_mpc = if guidance.local_mpc_guidance {
                1.0
            } else {
                0.0
            };
            let pressure_fit = finite_unit_interval(guidance.pressure_weight);
            let speed_fit = finite_unit_interval(guidance.speed_match_weight);
            let shape_clean = (1.0
                - soccer_finite_nonnegative_metric(guidance.pair_error_yards) / 8.0)
                .clamp(0.0, 1.0);
            (target_forward * 0.28
                + local_mpc * 0.24
                + pressure_fit * 0.16
                + speed_fit * 0.12
                + shape_clean * 0.20)
                .clamp(0.0, 1.0)
        })
        .unwrap_or(0.0);
    (embedding_attack * 0.20
        + overload * 0.15
        + pass_priority * 0.14
        + team_forward * 0.16
        + support_density * 0.12
        + shape_width * 0.08
        + lp * 0.24)
        .clamp(0.0, 1.0)
}

fn first_time_pass_field_feasibility_for_snapshot(
    visible_pass_targets: &[usize],
    floor_pass_lane_score: f64,
    best_floor_pass_quality: PassTargetQuality,
    best_floor_pass_stride_fit: f64,
    forward_support_context: ForwardSupportContext,
    threaded_goal_pass_assessment: Option<KillerPassTargetAssessment>,
    first_touch_shape_prior: f64,
) -> f64 {
    if visible_pass_targets.is_empty() {
        return 0.0;
    }
    let target_density = (visible_pass_targets.len() as f64 / 3.0).clamp(0.0, 1.0);
    let forward_options =
        (forward_support_context.visible_forward_pass_options as f64 / 3.0).clamp(0.0, 1.0);
    let forward_proximity = (1.0
        - forward_support_context.nearest_forward_teammate_distance_yards / 32.0)
        .clamp(0.0, 1.0);
    let forward_fit = (forward_options * 0.36
        + forward_support_context
            .best_forward_pass_receiver_openness
            .clamp(0.0, 1.0)
            * 0.42
        + forward_proximity * 0.22)
        .clamp(0.0, 1.0);
    let target_fit = (best_floor_pass_quality.expected_completion.clamp(0.0, 1.0) * 0.34
        + best_floor_pass_quality.receiver_openness.clamp(0.0, 1.0) * 0.24
        + best_floor_pass_quality.stride_fit.clamp(0.0, 1.0) * 0.16
        + best_floor_pass_stride_fit.clamp(0.0, 1.0) * 0.12
        + floor_pass_lane_score.clamp(0.0, 1.0) * 0.14)
        .clamp(0.0, 1.0);
    let threaded_fit = threaded_goal_pass_assessment
        .map(|assessment| {
            (assessment.reception_window_score.clamp(0.0, 1.0) * 0.30
                + assessment.receiver_openness.clamp(0.0, 1.0) * 0.22
                + assessment.expected_completion.clamp(0.0, 1.0) * 0.20
                + assessment.stride_fit.clamp(0.0, 1.0) * 0.16
                + assessment.goal_channel_fit.clamp(0.0, 1.0) * 0.12)
                .clamp(0.0, 1.0)
        })
        .unwrap_or(0.0);
    let blocked_one_touch_lane =
        forward_support_context.visible_forward_pass_options == 0 && floor_pass_lane_score < 0.62;
    let one_touch_lane_gate = if blocked_one_touch_lane { 0.58 } else { 1.0 };
    ((target_fit * 0.58
        + forward_fit * 0.16
        + threaded_fit * 0.14
        + target_density * 0.04
        + first_touch_shape_prior.clamp(0.0, 1.0) * 0.12)
        * one_touch_lane_gate)
        .clamp(0.0, 1.0)
}

fn first_time_shot_field_feasibility_for_snapshot(
    directive: &TeamTacticalDirective,
    yards_to_goal: f64,
    goal_angle_degrees: f64,
    first_time_shot_block_probability: f64,
    opposing_goalkeeper_out_of_position: f64,
    first_touch_shape_prior: f64,
) -> f64 {
    let distance_fit = (1.0 - yards_to_goal / 34.0).clamp(0.0, 1.0);
    let angle_fit = (goal_angle_degrees / 42.0).clamp(0.0, 1.0);
    let block_fit = (1.0 - first_time_shot_block_probability.clamp(0.0, 1.0)).clamp(0.0, 1.0);
    let overload = directive.attacking_overload_score.clamp(0.0, 1.0);
    let attack_prior = directive
        .adversarial_embedding_attack_score
        .max(directive.neural_formation_attack_score)
        .clamp(0.0, 1.0);
    (distance_fit * 0.30
        + angle_fit * 0.20
        + block_fit * 0.24
        + opposing_goalkeeper_out_of_position.clamp(0.0, 1.0) * 0.08
        + overload * 0.07
        + attack_prior * 0.06
        + first_touch_shape_prior.clamp(0.0, 1.0) * 0.08)
        .clamp(0.0, 1.0)
}

fn first_touch_release_score_with_field_feasibility(
    technical_score: f64,
    field_feasibility: f64,
    shape_prior: f64,
) -> f64 {
    let field_feasibility = field_feasibility.clamp(0.0, 1.0);
    let shape_prior = shape_prior.clamp(0.0, 1.0);
    let gate = (0.28 + field_feasibility * 0.62 + shape_prior * 0.16).clamp(0.18, 1.14);
    (technical_score.clamp(0.0, 1.0) * gate + field_feasibility * 0.08).clamp(0.0, 1.0)
}

