// ON by default: a turnover is weighted by how costly it actually was — a goalkeeper
// giving the ball away, and any giveaway deep in our own end, is punished several times
// harder than a routine midfield turnover (see `keeper_giveaway_severity`). Set
// `DD_SOCCER_DISABLE_KEEPER_GIVEAWAY_PENALTY` to revert to the flat per-transition
// turnover penalty (⇒ byte-identical to the previous reward shaping).
fn dd_soccer_disable_keeper_giveaway_penalty() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_KEEPER_GIVEAWAY_PENALTY").is_ok())
}

/// Severity multiplier (`>= 1.0`) on the turnover-window penalty for a single lost-possession
/// transition, keyed off who lost it and where. A flat turnover treats a keeper hooking it
/// straight to the opposition inside his own box the same as a midfielder over-hitting a pass
/// at halfway; this makes the dangerous giveaways the policy should actually fear cost more.
///
/// Two independent, multiplicative factors, both `1.0` in the benign case so they only ever
/// raise the cost:
/// * **zone danger** — ramps from `1.0` at the edge of our own third up to
///   [`KEEPER_GIVEAWAY_DANGER_ZONE_MAX_MULT`] right on our own goal line, off `yards_to_own_goal`.
/// * **keeper role** — a goalkeeper giveaway is additionally scaled by
///   [`KEEPER_GIVEAWAY_ROLE_MULT`] (the keeper is the last line; losing it there is worst).
///
/// Returns `1.0` (no change) when the giveaway-weighting gate is disabled.
fn keeper_giveaway_severity(role: PlayerRole, yards_to_own_goal: f64, field_length: f64) -> f64 {
    if dd_soccer_disable_keeper_giveaway_penalty() {
        return 1.0;
    }
    keeper_giveaway_severity_factor(role, yards_to_own_goal, field_length)
}

/// Pure severity math (no env gate) so the weighting can be unit-tested deterministically
/// regardless of the process-global `DD_SOCCER_DISABLE_KEEPER_GIVEAWAY_PENALTY` cache.
pub(crate) fn keeper_giveaway_severity_factor(
    role: PlayerRole,
    yards_to_own_goal: f64,
    field_length: f64,
) -> f64 {
    let mut severity = 1.0;
    let own_third = (field_length / 3.0).max(1.0);
    if yards_to_own_goal.is_finite() && yards_to_own_goal < own_third {
        // 0.0 at the own-third line, 1.0 on the own goal line.
        let depth = (1.0 - yards_to_own_goal.max(0.0) / own_third).clamp(0.0, 1.0);
        severity *= 1.0 + depth * (KEEPER_GIVEAWAY_DANGER_ZONE_MAX_MULT - 1.0);
    }
    if matches!(role, PlayerRole::Goalkeeper) {
        severity *= KEEPER_GIVEAWAY_ROLE_MULT;
    }
    severity
}

// ON by default: in our own half, short passes (<4yd) that aren't a genuine pressure
// escape are treated as a liability — demoted in the pass ranking (Layer 1) and made the
// carrier prefer to dribble/hold over playing them (Layer 2). Set
// `DD_SOCCER_DISABLE_OWN_HALF_SHORT_PASS_LIABILITY` to revert both layers (⇒ byte-identical).
pub(crate) fn dd_soccer_disable_own_half_short_pass_liability() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_OWN_HALF_SHORT_PASS_LIABILITY").is_ok())
}

/// Penalty (`>= 0`) demoting a short own-half pass in the floor-pass ranking (Layer 1).
/// `> 0` only for a sub-[`OWN_HALF_SHORT_PASS_LIABILITY_MAX_YARDS`] pass played from our own
/// half that is NOT a genuine escape (the receiver is not clearly less pressured than the
/// holder). Unlike the build-up penalty it carries a floor so it does not fade out as the
/// pass nears 4yd. Returns `0.0` when the gate is disabled (⇒ byte-identical ranking).
fn own_half_short_pass_liability_penalty(
    in_own_half: bool,
    dist: f64,
    holder_pressure: f64,
    receiver_pressure: f64,
) -> f64 {
    if dd_soccer_disable_own_half_short_pass_liability() {
        return 0.0;
    }
    own_half_short_pass_liability_penalty_factor(
        in_own_half,
        dist,
        holder_pressure,
        receiver_pressure,
    )
}

/// Pure Layer-1 penalty math (no env gate) so it can be unit-tested regardless of the
/// process-global gate cache.
pub(crate) fn own_half_short_pass_liability_penalty_factor(
    in_own_half: bool,
    dist: f64,
    holder_pressure: f64,
    receiver_pressure: f64,
) -> f64 {
    if !in_own_half || dist >= OWN_HALF_SHORT_PASS_LIABILITY_MAX_YARDS {
        return 0.0;
    }
    // A real escape — the receiver is clearly more open than the pressured holder — is the
    // one short own-half ball worth playing; leave it alone.
    if receiver_pressure <= holder_pressure - POINTLESS_SHORT_PASS_RELIEF_MARGIN {
        return 0.0;
    }
    let shortness = (1.0 - dist / OWN_HALF_SHORT_PASS_LIABILITY_MAX_YARDS).clamp(0.0, 1.0);
    let floor = OWN_HALF_SHORT_PASS_LIABILITY_FLOOR_FRACTION;
    OWN_HALF_SHORT_PASS_LIABILITY_PENALTY * (floor + (1.0 - floor) * shortness)
}
/// Small retroactive MDP/POMDP penalty for locomotion energy spent in a tick that bought no
/// ball interaction over the next 10s (pointless off-ball running). Default-ON in prod (kill switch
/// `DD_SOCCER_ENABLE_WASTED_ENERGY_PENALTY=0`); default-OFF under test ⇒ byte-identical & zero-cost.
pub(crate) fn dd_soccer_enable_wasted_energy_penalty() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_WASTED_ENERGY_PENALTY"))
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_WASTED_ENERGY_PENALTY"))
    }
}
/// Stricter, team-aware refinement of the wasted-energy penalty: only a genuine SUSTAINED
/// flat-out sprint that bought NO positive team outcome (or personal touch) over the next 10s
/// is docked. Default-ON in prod (kill switch `DD_SOCCER_ENABLE_SUSTAINED_EFFORT_NO_OUTCOME_PENALTY=0`);
/// default-OFF under test ⇒ byte-identical & zero-cost. See `SUSTAINED_EFFORT_*`.
pub(crate) fn dd_soccer_enable_sustained_effort_no_outcome_penalty() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| {
            soccer_env_flag_enabled("DD_SOCCER_ENABLE_SUSTAINED_EFFORT_NO_OUTCOME_PENALTY")
        })
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_SUSTAINED_EFFORT_NO_OUTCOME_PENALTY"))
    }
}
/// True when either wasted-energy variant is active. Both share the windowed-sample +
/// ball-interaction-tracking machinery; the sustained variant additionally requires a long
/// flat-out sprint to retain a sample and treats a teammate's positive outcome as paying the
/// run off (`finalize_wasted_energy_window_with`).
pub(crate) fn wasted_energy_tracking_active() -> bool {
    dd_soccer_enable_wasted_energy_penalty()
        || dd_soccer_enable_sustained_effort_no_outcome_penalty()
}
/// Far-from-ball off-ball energy conservation throttle. Default-ON in prod (kill switch
/// `DD_SOCCER_ENABLE_FAR_OFFBALL_ENERGY_CONSERVATION=0`); default-OFF under test ⇒ byte-identical & zero-cost.
pub(crate) fn dd_soccer_enable_far_offball_energy_conservation() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| {
            soccer_env_flag_enabled("DD_SOCCER_ENABLE_FAR_OFFBALL_ENERGY_CONSERVATION")
        })
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_FAR_OFFBALL_ENERGY_CONSERVATION"))
    }
}
/// Team → fixed history-array index (`Home` = 0, `Away` = 1).
pub(crate) fn team_index(team: Team) -> usize {
    match team {
        Team::Home => 0,
        Team::Away => 1,
    }
}
/// True when a tracked sprint is long and sustained enough to be a candidate "big effort":
/// held at flat-out pace for ≥ `SUSTAINED_EFFORT_MIN_SECONDS` AND covering
/// ≥ `SUSTAINED_EFFORT_MIN_DISTANCE_YARDS`. Pure (testable in isolation).
pub(crate) fn sustained_sprint_run_qualifies(seconds: f64, distance_yards: f64) -> bool {
    seconds >= SUSTAINED_EFFORT_MIN_SECONDS && distance_yards >= SUSTAINED_EFFORT_MIN_DISTANCE_YARDS
}
/// Smooth off-ball energy-conservation throttle as a function of distance from the ball:
/// `1.0` up to `FAR_OFFBALL_CONSERVE_START_YARDS`, ramping via `smoothstep_unit` (no cliff)
/// down to `1.0 - FAR_OFFBALL_CONSERVE_MAX_REDUCTION` at `FAR_OFFBALL_CONSERVE_FULL_YARDS` and
/// held there beyond. Pure (testable in isolation).
pub(crate) fn far_offball_conservation_factor(ball_distance_yards: f64) -> f64 {
    let span = (FAR_OFFBALL_CONSERVE_FULL_YARDS - FAR_OFFBALL_CONSERVE_START_YARDS).max(1e-6);
    let t = ((ball_distance_yards - FAR_OFFBALL_CONSERVE_START_YARDS) / span).clamp(0.0, 1.0);
    1.0 - FAR_OFFBALL_CONSERVE_MAX_REDUCTION * smoothstep_unit(t)
}
/// True when a receiver moving at `nominal_speed_yps` would reach the reception point
/// meaningfully BEFORE the ball does — i.e. they would overrun the spot if they kept going, so
/// the ball arrives behind their run. Pure / testable. Returns false for a stationary/near-static
/// ball or degenerate inputs (nothing to sync to).
pub(crate) fn receive_in_stride_would_overrun(
    distance_to_target_yards: f64,
    nominal_speed_yps: f64,
    ball_distance_to_target_yards: f64,
    ball_speed_yps: f64,
) -> bool {
    if !(distance_to_target_yards.is_finite()
        && nominal_speed_yps.is_finite()
        && ball_distance_to_target_yards.is_finite()
        && ball_speed_yps.is_finite())
    {
        return false;
    }
    if nominal_speed_yps <= 1e-3 || ball_speed_yps <= RECEIVE_IN_STRIDE_MIN_BALL_SPEED_YPS {
        return false;
    }
    let ball_time = ball_distance_to_target_yards / ball_speed_yps;
    if ball_time <= 1e-3 {
        return false;
    }
    let self_time = distance_to_target_yards / nominal_speed_yps;
    self_time < ball_time * RECEIVE_IN_STRIDE_EARLY_MARGIN
}

/// Speed multiplier for a free receiver settling to take an incoming ball IN STRIDE rather than
/// overrunning it. `1.0` when the receiver is not early (would arrive with/after the ball); when
/// early, the pace that lands them ~as the ball arrives (`distance / ball_time`), as a fraction of
/// nominal, floored at [`RECEIVE_IN_STRIDE_MIN_FACTOR`] so they keep drifting onto the ball. Pure.
pub(crate) fn receive_in_stride_speed_factor(
    distance_to_target_yards: f64,
    nominal_speed_yps: f64,
    ball_distance_to_target_yards: f64,
    ball_speed_yps: f64,
) -> f64 {
    if !receive_in_stride_would_overrun(
        distance_to_target_yards,
        nominal_speed_yps,
        ball_distance_to_target_yards,
        ball_speed_yps,
    ) {
        return 1.0;
    }
    let ball_time = ball_distance_to_target_yards / ball_speed_yps;
    let required_speed = distance_to_target_yards / ball_time;
    (required_speed / nominal_speed_yps).clamp(RECEIVE_IN_STRIDE_MIN_FACTOR, 1.0)
}

/// Receive-in-stride / anti-overrun: a FREE receiver who would reach the reception point well
/// before the ball eases off (settles to a controlled pace) so the ball arrives in stride rather
/// than running on behind them. Default-ON in prod (kill switch
/// `DD_SOCCER_ENABLE_RECEIVE_IN_STRIDE=0`); default-OFF in tests for byte-identical movement.
pub(crate) fn dd_soccer_enable_receive_in_stride() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_RECEIVE_IN_STRIDE"))
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_RECEIVE_IN_STRIDE"))
    }
}

/// Per-fully-wasted-sprint-tick penalty points, overridable via
/// `DD_SOCCER_WASTED_ENERGY_PENALTY_POINTS` for A/B tuning. Falls back to
/// [`WASTED_ENERGY_PENALTY_POINTS`]; a non-finite/negative override is ignored.
fn wasted_energy_penalty_points() -> f64 {
    use std::sync::OnceLock;
    static V: OnceLock<f64> = OnceLock::new();
    *V.get_or_init(|| {
        std::env::var("DD_SOCCER_WASTED_ENERGY_PENALTY_POINTS")
            .ok()
            .and_then(|raw| raw.parse::<f64>().ok())
            .filter(|points| points.is_finite() && *points >= 0.0)
            .unwrap_or(WASTED_ENERGY_PENALTY_POINTS)
    })
}
fn dd_soccer_disable_offball_settle() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_OFFBALL_SETTLE").is_ok())
}
fn dd_soccer_disable_reception_urgency() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_RECEPTION_URGENCY").is_ok())
}

/// Receiver check-run correction. ON by default: an unpressured named receiver who has already
/// overrun the rolling pass path slows/checks toward the ball instead of sprinting farther past
/// it. Set `DD_SOCCER_DISABLE_RECEIVER_CHECK_RUN=1` for A/B parity.
fn dd_soccer_disable_receiver_check_run() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_RECEIVER_CHECK_RUN").is_ok())
}
/// "Drive to the corner flag and cross" for a wide carrier. ON by default: a committed run at the
/// byline corner (then a low cutback / high cross) instead of slowing 32-38yd out or cutting into
/// central traffic. Set `DD_SOCCER_DISABLE_BYLINE_DRIVE_TO_CORNER=1` to restore the old
/// central-pocket-only carry (A/B / parity).
fn dd_soccer_disable_byline_drive_to_corner() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_BYLINE_DRIVE_TO_CORNER").is_ok())
}
/// Individual winger "drive the byline" opt-in. ON by default: a wide carrier isolated wide with a
/// clear lane drives for the corner flag (then crosses) ON HIS OWN — without waiting for the team
/// strategy selector to commit to a byline-cross strategy — instead of stalling ~30yd out. Set
/// `DD_SOCCER_DISABLE_WINGER_BYLINE_OPTION=1` to restore the team-commitment-only behaviour
/// (A/B / parity). See `winger_byline_drive_opt_in`.
fn dd_soccer_disable_winger_byline_option() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_WINGER_BYLINE_OPTION").is_ok())
}
/// Wide-defender "hold width when the ball is advanced" rule. ON by default: once the ball is
/// 10+ yds AHEAD of our back-four line average, a wide defender pushes up WITH the play but no
/// longer bombs out to the touchline to open up — opening wide from behind an advanced ball only
/// isolates him and vacates the flank he covers. The exception is a live ground-pass outlet (he
/// is within ~20yd of the ball on a clear lane), where getting wide to receive is correct. Set
/// `DD_SOCCER_DISABLE_WINGBACK_ADVANCED_BALL_HOLD_WIDTH=1` to restore the always-open behaviour
/// byte-for-byte. See `wingback_advanced_ball_should_hold_width`.
fn dd_soccer_disable_wingback_advanced_ball_hold_width() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_WINGBACK_ADVANCED_BALL_HOLD_WIDTH").is_ok())
}
/// Outside-mid ball-lane attacking width. ON by default: a wide attacker opens to his touchline
/// by an amount that scales SMOOTHLY with how close the ball's lane is to his own flank (closest
/// ⇒ widest), instead of a binary "ball is on my half of the pitch" switch. Set
/// `DD_SOCCER_DISABLE_OUTSIDE_MID_BALL_LANE_WIDTH=1` to restore the legacy binary boost
/// byte-for-byte. See `wide_possession_outlet_target_for`.
fn outside_mid_ball_lane_width_enabled() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| !std::env::var("DD_SOCCER_DISABLE_OUTSIDE_MID_BALL_LANE_WIDTH").is_ok())
}
/// Long-pass run requirement (Part B of the long-pass-option-runs feature). ON by default: a
/// DEEP carrier may only pre-empt-commit a long aerial to a teammate who actually made the run
/// (`backfield_long_pass_run_invite_for > 0`), so a calm backfield holder picks out a runner
/// instead of lofting a long ball into empty space. Set `DD_SOCCER_DISABLE_LONG_PASS_RUN_REQUIRED=1`
/// to restore the unrestricted behaviour byte-for-byte (the deep-holder long ball fires whenever
/// the viability gate passes, regardless of whether a runner is on).
fn dd_soccer_disable_long_pass_run_required() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_LONG_PASS_RUN_REQUIRED").is_ok())
}
/// Keeper goalside guard. ON by default: the goalkeeper only abandons its goalside ball↔goal
/// tracking line to push up into the buildup-outlet shape when our team GENUINELY controls the
/// ball — it is held by a teammate, or one of our passes is in flight with a teammate the
/// favourite to receive it. Previously the keeper's "in possession" test fell back to
/// `last_touch_team`, so a LOOSE ball we last touched (a deflection, a popped-loose tackle, a
/// cleared ball an opponent is about to win) kept the keeper upfield instead of dropping between
/// the centre of its goal and the ball. Set `DD_SOCCER_DISABLE_GK_GOALSIDE_GUARD=1` to restore the
/// prior last-touch behaviour (byte-identical, A/B / parity). See `goalkeeper_buildup_possession_team`.
fn dd_soccer_disable_gk_goalside_guard() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_GK_GOALSIDE_GUARD").is_ok())
}
/// "Show for the ball" boost. ON by default: a teammate that can break into a clean, passable
/// pocket near the carrier values that outlet markedly more (rewarding forward outlets most), so
/// the carrier reliably HAS a teammate to play to — instead of being left to thump it to nobody or
/// force it into a marked man. The raw most-open-space term otherwise drags runners away from the
/// ball into space the carrier cannot reach. Set `DD_SOCCER_DISABLE_SHOW_FOR_BALL_BOOST=1` to
/// restore the unboosted `SHORT_OUTLET_SHOW_BONUS` (A/B / parity).
fn dd_soccer_disable_show_for_ball_boost() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_SHOW_FOR_BALL_BOOST").is_ok())
}
/// Off-ball spacing discipline. Default-ON in prod (kill switch
/// `DD_SOCCER_ENABLE_OFF_BALL_SPACE_DISCIPLINE=0`); default-OFF under test = byte-identical for clean A/B. When ON,
/// `open_space_for` rewards off-ball teammates for *improving* the passing picture rather than
/// merely closing on the ball: the "show for the ball" / ball-arrival proximity pulls are
/// cancelled for a player who is ALREADY a clean, in-range outlet, and candidates that collapse
/// inside the carrier's comfortable receiving radius are penalised (unless the carrier is
/// pressured and genuinely needs a short option). This kills the "two off-ball players >4yd
/// apart spiral into the carrier to <3yd while the passing lane is already open" red flag.
fn dd_soccer_enable_off_ball_space_discipline() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_OFF_BALL_SPACE_DISCIPLINE"))
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_OFF_BALL_SPACE_DISCIPLINE"))
    }
}
/// Forward-run-when-unmarked (gated, default-ON = the desired behaviour; kill switch for A/B).
/// Principle: when the team is in possession and this off-ball player is UNMARKED (no opponent
/// within [`FORWARD_RUN_UNMARKED_MARK_RADIUS_YARDS`]) and CAN run forward into open space, he must
/// not elect a BACKWARD run — the team should move forward in possession. When ON, `open_space_for`
/// applies a veto-strength penalty to backward candidates (and a bonus to forward-into-space ones)
/// for such a player, but ONLY when a forward-into-space option genuinely exists, so a legitimate
/// drop to offer an outlet when everything ahead is covered is untouched. Set
/// `DD_SOCCER_ENABLE_FORWARD_RUN_WHEN_UNMARKED=0` (or `false`/`no`/`off`) to restore the old
/// weak-forward-bias scoring (byte-identical A/B).
fn dd_soccer_enable_forward_run_when_unmarked() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_FORWARD_RUN_WHEN_UNMARKED"))
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_FORWARD_RUN_WHEN_UNMARKED"))
    }
}
/// One-two "give to feet" + bound wall-partner reception. ON by default: a one-two give is aimed
/// at the wall partner's feet (not led ahead toward goal like a through-ball) and the named
/// partner is bound to collect it, so the give can't be thrown into space the partner never
/// occupies while the passer has already burst into the return run (the "defender plays the
/// shortest pass to nobody and runs away" bug). Set `DD_SOCCER_DISABLE_ONE_TWO_GIVE_TO_FEET=1` to
/// restore the old led-give behaviour (A/B / parity).
fn dd_soccer_disable_one_two_give_to_feet() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DISABLE_ONE_TWO_GIVE_TO_FEET").is_ok())
}

/// How many goal-mouth placements [`WorldSnapshot::scored_shot_placement_x`] sweeps
/// (the schema doc's ~9 placement buckets: both posts, both half-spaces, centre).
const SCORED_SHOT_PLACEMENT_BUCKETS: usize = 9;
/// Smallest safety margin inside the post a scored shot aims for (an elite finisher).
const SCORED_SHOT_POST_MARGIN_MIN_YARDS: f64 = 0.6;
/// Extra inside-the-post margin added as shooting skill falls (a weak finisher tucks it
/// further inside the frame rather than threading the post and missing wide).
const SCORED_SHOT_POST_MARGIN_SKILL_YARDS: f64 = 1.6;

/// See [`WorldSnapshot::scored_shot_placement_x`]: set `DD_SOCCER_ENABLE_SCORED_SHOT_PLACEMENT=1`
/// to aim non-curl shots at the keeper's least-saveable goal-mouth placement instead of the
/// goal centre. Default off ⇒ shots keep the centred aim (byte-identical baseline / A/B).
fn dd_soccer_enable_scored_shot_placement() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_SCORED_SHOT_PLACEMENT"))
}

/// Pass-to-space (spatial-target hardening, Codex round-10 shape). When set, the neural MCTS pass
/// expansion emits, for each shortlisted receiver, a SECOND candidate plan that keeps
/// `target_player = Some(receiver)` but sets `target_point` to the anticipated lead/into-space
/// reception point instead of the receiver's feet — so the critic can choose to play the ball
/// ahead into space for a runner, not only to feet. The receiver stays bound, so the existing
/// pass MPC/receipt/concede-veto logic still applies. Default OFF ⇒ byte-identical (feet-only
/// candidate as before).
fn dd_soccer_enable_neural_pass_space() -> bool {
    #[cfg(test)]
    {
        soccer_env_flag_enabled("DD_SOCCER_ENABLE_NEURAL_PASS_SPACE")
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_NEURAL_PASS_SPACE"))
    }
}

/// Forward-pass attempt shaping. Default-ON in prod because this is the anti-plateau learning
/// bridge: the selector gets a small, dense reward for choosing a good forward-pass picture before
/// sparse completion credit arrives. Default-OFF under tests to preserve parity unless a test opts
/// in. `DD_SOCCER_ENABLE_FORWARD_PASS_ATTEMPT_REWARD=0` is the production kill switch.
fn dd_soccer_enable_forward_pass_attempt_reward() -> bool {
    #[cfg(test)]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| soccer_env_flag_enabled("DD_SOCCER_ENABLE_FORWARD_PASS_ATTEMPT_REWARD"))
    }
    #[cfg(not(test))]
    {
        use std::sync::OnceLock;
        static V: OnceLock<bool> = OnceLock::new();
        *V.get_or_init(|| gate_default_on("DD_SOCCER_ENABLE_FORWARD_PASS_ATTEMPT_REWARD"))
    }
}

fn forward_pass_attempt_reward_points(pass: &PendingPass, expected_completion: f64) -> f64 {
    if pass.target.is_none() || pass.is_cross || pass.offside.is_some() {
        return 0.0;
    }
    let forward_yards = (pass.intended_target.y - pass.origin.y) * pass.team.attack_dir();
    if forward_yards < FORWARD_PASS_ATTEMPT_REWARD_MIN_FORWARD_YARDS {
        return 0.0;
    }
    let expected_completion = expected_completion.clamp(0.0, 1.0);
    let receiver_openness = pass.receiver_openness.clamp(0.0, 1.0);
    if expected_completion < FORWARD_PASS_ATTEMPT_REWARD_MIN_EXPECTED_COMPLETION
        || receiver_openness < FORWARD_PASS_ATTEMPT_REWARD_MIN_RECEIVER_OPENNESS
    {
        return 0.0;
    }
    let progress = ((forward_yards - FORWARD_PASS_ATTEMPT_REWARD_MIN_FORWARD_YARDS)
        / (FORWARD_PASS_ATTEMPT_REWARD_FULL_FORWARD_YARDS
            - FORWARD_PASS_ATTEMPT_REWARD_MIN_FORWARD_YARDS)
            .max(1.0))
    .clamp(0.0, 1.0);
    let aerial_multiplier = if pass.flight.is_aerial() { 0.65 } else { 1.0 };
    let quality_multiplier = 0.35 + expected_completion * 0.65;
    let openness_multiplier = 0.80 + receiver_openness * 0.20;
    ((FORWARD_PASS_ATTEMPT_REWARD_BASE_POINTS
        + progress * FORWARD_PASS_ATTEMPT_REWARD_PROGRESS_POINTS)
        * quality_multiplier
        * openness_multiplier
        * aerial_multiplier)
        .clamp(0.0, FORWARD_PASS_ATTEMPT_REWARD_MAX_POINTS)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MctsForwardTargetRankBucket {
    NoForwardCandidate,
    InsideCap,
    PrunedByCap,
}

fn first_mcts_forward_target_rank<I>(team: Team, origin: Vec2, target_positions: I) -> Option<usize>
where
    I: IntoIterator<Item = Option<Vec2>>,
{
    target_positions
        .into_iter()
        .enumerate()
        .find_map(|(rank, target_position)| {
            let target_position = target_position?;
            let forward_yards = (target_position.y - origin.y) * team.attack_dir();
            (forward_yards >= FORWARD_PASS_ATTEMPT_REWARD_MIN_FORWARD_YARDS).then_some(rank)
        })
}

fn mcts_forward_target_rank_bucket(
    best_forward_rank: Option<usize>,
    limit: usize,
) -> MctsForwardTargetRankBucket {
    match best_forward_rank {
        Some(rank) if rank < limit => MctsForwardTargetRankBucket::InsideCap,
        Some(_) => MctsForwardTargetRankBucket::PrunedByCap,
        None => MctsForwardTargetRankBucket::NoForwardCandidate,
    }
}

/// Diagnostic-only (`DD_SOCCER_DUMP_MCTS_PASS_TARGET_DIAG`): before the MCTS pass-target cap is
/// applied, report whether the first viable forward receiver is inside the cap, pruned by it, or
/// absent. This separates an enumeration/interface bottleneck from downstream value/reward issues.
fn mcts_pass_target_diag_enabled() -> bool {
    use std::sync::OnceLock;
    static V: OnceLock<bool> = OnceLock::new();
    *V.get_or_init(|| std::env::var("DD_SOCCER_DUMP_MCTS_PASS_TARGET_DIAG").is_ok())
}

const MCTS_PASS_TARGET_DIAG_DEFAULT_LOG_EVERY: u64 = 200;

static MCTS_PASS_TARGET_DIAG_REACHED: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_FLOOR: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_AERIAL: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_HAS_FORWARD: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_NO_FORWARD: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_FORWARD_INSIDE_CAP: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_FORWARD_PRUNED_BY_CAP: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static MCTS_PASS_TARGET_DIAG_FORWARD_RANK_SUM: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

fn mcts_pass_target_diag_rate(numerator: u64, denominator: u64) -> f64 {
    if denominator == 0 {
        0.0
    } else {
        numerator as f64 / denominator as f64
    }
}

fn log_mcts_pass_target_diag(limit: usize) {
    use std::sync::atomic::Ordering::Relaxed;
    let reached = MCTS_PASS_TARGET_DIAG_REACHED.load(Relaxed);
    let floor = MCTS_PASS_TARGET_DIAG_FLOOR.load(Relaxed);
    let aerial = MCTS_PASS_TARGET_DIAG_AERIAL.load(Relaxed);
    let has_forward = MCTS_PASS_TARGET_DIAG_HAS_FORWARD.load(Relaxed);
    let no_forward = MCTS_PASS_TARGET_DIAG_NO_FORWARD.load(Relaxed);
    let inside_cap = MCTS_PASS_TARGET_DIAG_FORWARD_INSIDE_CAP.load(Relaxed);
    let pruned_by_cap = MCTS_PASS_TARGET_DIAG_FORWARD_PRUNED_BY_CAP.load(Relaxed);
    let rank_sum = MCTS_PASS_TARGET_DIAG_FORWARD_RANK_SUM.load(Relaxed);
    let avg_best_forward_rank = if has_forward == 0 {
        0.0
    } else {
        rank_sum as f64 / has_forward as f64
    };
    eprintln!(
        "mcts_pass_target_diag reached={reached} floor={floor} aerial={aerial} \
         has_forward={has_forward} no_forward={no_forward} \
         forward_inside_cap={inside_cap} forward_pruned_by_cap={pruned_by_cap} \
         forward_inside_rate={:.3} forward_pruned_rate={:.3} no_forward_rate={:.3} \
         avg_best_forward_rank_1based={avg_best_forward_rank:.2} cap={limit}",
        mcts_pass_target_diag_rate(inside_cap, has_forward),
        mcts_pass_target_diag_rate(pruned_by_cap, has_forward),
        mcts_pass_target_diag_rate(no_forward, reached),
    );
}

fn maybe_log_mcts_pass_target_diag(sample_count: u64, limit: usize) {
    use std::sync::OnceLock;
    static LOG_EVERY: OnceLock<u64> = OnceLock::new();
    let log_every = *LOG_EVERY.get_or_init(|| {
        std::env::var("DD_SOCCER_MCTS_PASS_TARGET_DIAG_LOG_EVERY")
            .ok()
            .and_then(|value| value.trim().parse::<u64>().ok())
            .unwrap_or(MCTS_PASS_TARGET_DIAG_DEFAULT_LOG_EVERY)
    });
    if log_every > 0 && sample_count > 0 && sample_count % log_every == 0 {
        log_mcts_pass_target_diag(limit);
    }
}

fn record_mcts_pass_target_diag(
    snapshot: &WorldSnapshot,
    player_id: usize,
    team: Team,
    prefix: &str,
    targets: &[usize],
    limit: usize,
) {
    if !mcts_pass_target_diag_enabled() {
        return;
    }
    let Some(origin) = snapshot.player_position(player_id) else {
        return;
    };
    use std::sync::atomic::Ordering::Relaxed;
    let sample_count = MCTS_PASS_TARGET_DIAG_REACHED.fetch_add(1, Relaxed) + 1;
    if prefix == "aerial-pass" {
        MCTS_PASS_TARGET_DIAG_AERIAL.fetch_add(1, Relaxed);
    } else {
        MCTS_PASS_TARGET_DIAG_FLOOR.fetch_add(1, Relaxed);
    }
    let best_forward_rank = first_mcts_forward_target_rank(
        team,
        origin,
        targets
            .iter()
            .map(|target_id| snapshot.player_position(*target_id)),
    );
    match mcts_forward_target_rank_bucket(best_forward_rank, limit) {
        MctsForwardTargetRankBucket::NoForwardCandidate => {
            MCTS_PASS_TARGET_DIAG_NO_FORWARD.fetch_add(1, Relaxed);
        }
        MctsForwardTargetRankBucket::InsideCap => {
            MCTS_PASS_TARGET_DIAG_HAS_FORWARD.fetch_add(1, Relaxed);
            MCTS_PASS_TARGET_DIAG_FORWARD_INSIDE_CAP.fetch_add(1, Relaxed);
            MCTS_PASS_TARGET_DIAG_FORWARD_RANK_SUM
                .fetch_add(best_forward_rank.unwrap_or(0) as u64 + 1, Relaxed);
        }
        MctsForwardTargetRankBucket::PrunedByCap => {
            MCTS_PASS_TARGET_DIAG_HAS_FORWARD.fetch_add(1, Relaxed);
            MCTS_PASS_TARGET_DIAG_FORWARD_PRUNED_BY_CAP.fetch_add(1, Relaxed);
            MCTS_PASS_TARGET_DIAG_FORWARD_RANK_SUM
                .fetch_add(best_forward_rank.unwrap_or(0) as u64 + 1, Relaxed);
        }
    }
    maybe_log_mcts_pass_target_diag(sample_count, limit);
}

/// Diagnostic-only (gated by `DD_SOCCER_DUMP_PASS_SPACE_DIAG`): counts pass-space survival at
/// SOURCE candidate expansion, SCORED winning-plan selection, and EXECUTED launch. No-op
/// (byte-identical) unless the diag env is set.
