pub(crate) fn player_sample_forward_progress_over_seconds(
    history: &[PlayerPositionSample],
    current_position: Vec2,
    attack_dir: f64,
    current_clock_seconds: f64,
    seconds: f64,
) -> Option<f64> {
    if history.len() < 2 || seconds <= 0.0 {
        return None;
    }

    let latest_clock = if current_clock_seconds.is_finite() {
        current_clock_seconds
    } else {
        history
            .iter()
            .rev()
            .find(|sample| sample.clock_seconds.is_finite())
            .map(|sample| sample.clock_seconds)?
    };
    let target_clock = latest_clock - seconds;
    let mut oldest: Option<&PlayerPositionSample> = None;
    let mut previous: Option<&PlayerPositionSample> = None;

    for sample in history
        .iter()
        .filter(|sample| sample.clock_seconds.is_finite() && sample.clock_seconds <= latest_clock)
    {
        oldest.get_or_insert(sample);
        if let Some(prev) = previous {
            if prev.clock_seconds <= target_clock && target_clock <= sample.clock_seconds {
                let dt_seconds = sample.clock_seconds - prev.clock_seconds;
                if dt_seconds > 1e-9 {
                    let t = ((target_clock - prev.clock_seconds) / dt_seconds).clamp(0.0, 1.0);
                    let start_position = prev.position + (sample.position - prev.position) * t;
                    return Some((current_position.y - start_position.y) * attack_dir);
                }
            }
        }
        previous = Some(sample);
    }

    let oldest = oldest?;
    let elapsed_seconds = (latest_clock - oldest.clock_seconds).max(0.0);
    if elapsed_seconds >= seconds * 0.5 {
        let observed = (current_position.y - oldest.position.y) * attack_dir;
        Some(observed * (seconds / elapsed_seconds.max(1e-9)).clamp(0.5, 2.0))
    } else {
        None
    }
}

#[derive(Clone, Copy, Debug)]
struct OffsidePositionAssessment {
    ball_y: f64,
    second_last_defender_y: f64,
    active_line_y: f64,
    yards_beyond_line: f64,
}

#[derive(Clone, Copy, Debug, Default)]
struct OffsideRecoveryObservation {
    offside_position: bool,
    yards_beyond_line: f64,
    clock_seconds: f64,
    recovery_pressure: f64,
    target_distance_yards: f64,
}

const OFFSIDE_RECOVERY_COMPLETION_TARGET_SECONDS: f64 = 4.5;
const OFFSIDE_RECOVERY_JOG_REFERENCE_YPS: f64 = 3.0;
const OFFSIDE_RECOVERY_URGENT_DISTANCE_YARDS: f64 = 4.0;
const OFFSIDE_RECOVERY_TARGET_MATCH_TOLERANCE_YARDS: f64 = 0.75;

fn active_offside_line_y(team: Team, ball_y: f64, second_last_defender_y: f64) -> f64 {
    match team {
        Team::Home => ball_y.max(second_last_defender_y),
        Team::Away => ball_y.min(second_last_defender_y),
    }
}

fn offside_position_assessment(
    team: Team,
    position: Vec2,
    ball_y: f64,
    second_last_defender_y: f64,
    field_length: f64,
) -> Option<OffsidePositionAssessment> {
    if !position.x.is_finite()
        || !position.y.is_finite()
        || !ball_y.is_finite()
        || !second_last_defender_y.is_finite()
        || !field_length.is_finite()
    {
        return None;
    }
    let attack_dir = team.attack_dir();
    let half_line = field_length * 0.5;
    if (position.y - half_line) * attack_dir <= 0.0 {
        return None;
    }
    let active_line_y = active_offside_line_y(team, ball_y, second_last_defender_y);
    let yards_beyond_line = (position.y - active_line_y) * attack_dir;
    if yards_beyond_line <= 0.0 {
        return None;
    }
    Some(OffsidePositionAssessment {
        ball_y,
        second_last_defender_y,
        active_line_y,
        yards_beyond_line,
    })
}

